window.__BUNDLE = {"body": "<div class=\"wrap\">\n\n  <section id=\"intro\" class=\"stack\" style=\"gap:28px\">\n    <div data-greeting></div>\n    <div id=\"testStart\" class=\"stack\" style=\"gap:28px\" hidden>\n      <div class=\"stack\">\n        <div class=\"eyebrow\">For yourself · a guide and a test for self-reflection</div>\n        <h1>Steps of Stability</h1>\n        <p class=\"slogan\">To belong and feel at home in a new country</p>\n        <p class=\"lead\">After a move, you have to build your life anew, like a house: from the bottom up. First the ground under your feet, then a hearth and people of your own, then your voice, order, your work, meaning. Here you can find out what these steps are and check which of them already hold you and which one creaks.</p>\n      </div>\n      <div class=\"st-resume\" id=\"stResume\" hidden></div>\n      <div class=\"st-tiles\" id=\"stTiles\"></div>\n      <div id=\"stAB\"></div>\n      <div data-reportfan></div>\n      <div class=\"st-entries\">\n        <button type=\"button\" class=\"st-entry\" id=\"goGuide\"><span class=\"st-eh\">Get to know the steps</span><span>A guide to the eight steps: what they are, what they look like after a move, and questions to help you get to know yourself.</span><span class=\"st-go\">Read →</span></button>\n        <button type=\"button\" class=\"st-entry main\" id=\"goTest\"><span class=\"st-eh\">Take the “7 Steps of Stability” test</span><span>Which steps hold you in your new country, which one creaks, and where you in particular should start. About 20 minutes.</span><span class=\"st-go\">Take the test →</span></button>\n      </div>\n\n      <section id=\"guide\" class=\"stack\" style=\"gap:18px\" hidden></section>\n\n      <section id=\"testPrep\" class=\"stack\" style=\"gap:24px\" hidden>\n        <div class=\"card stack\">\n          <div class=\"eyebrow\">Test · about 20 minutes</div>\n          <h2>7 Steps of Stability</h2>\n          <p>Imagine the staircase in the house you are building in a new country. Seven steps: from the ground under your feet to the view of your whole life from a hill. Some steps beneath you are already solid, while one may creak, making it hard to climb higher however hard you try. The test will help you hear that creak.</p>\n          <p>It has three short parts. <b>About you</b>: two questions about your story. <b>Anchor</b>: short statements about your life; mark how true each one is for you. <b>Situations</b>: twelve scenes from life, in each of which you share out 10 points among four options.</p>\n          <p>Pour yourself some tea and find a quiet corner: this time is just for you. There are no right or wrong answers here. Answer not “as it should be” but as it is, over the last four weeks.</p>\n          <div class=\"scale-legend\"><span><b>0</b> not me at all</span><span><b>1</b> mostly not</span><span><b>2</b> partly</span><span><b>3</b> mostly yes</span><span><b>4</b> definitely me</span></div>\n          <p class=\"note\">This is not a grade or a check of “am I normal”. Almost everyone who has moved goes through the lower steps again: it is not weakness but the price of moving. The test is not a diagnosis.</p>\n        </div>\n        <div data-testinfo></div>\n        <div class=\"stack\">\n          <h3>What is your name?</h3>\n          <div class=\"row\" style=\"align-items:stretch\">\n            <div class=\"field\"><label for=\"nameMe\">Your name</label><input id=\"nameMe\" maxlength=\"30\" autocomplete=\"given-name\" placeholder=\"For example, Anna\"></div>\n          </div>\n          <p class=\"note\">Your name is only used to make your report look nice.</p>\n        </div>\n        <div><button class=\"btn\" id=\"startBtn\">Start the test</button></div>\n        <div data-share=\"compact\" style=\"margin-top:8px\"></div>\n      </section>\n    </div>\n  </section>\n\n  <section id=\"quiz\" class=\"stack\" hidden style=\"gap:20px\">\n    <div class=\"stack\" style=\"gap:10px\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <span class=\"eyebrow\" id=\"stepLabel\"></span>\n        <span class=\"eyebrow\" id=\"countLabel\"></span>\n      </div>\n      <div class=\"progress\"><i id=\"prog\" style=\"width:0\"></i></div>\n    </div>\n    <div class=\"stack\" style=\"gap:6px\">\n      <div><span class=\"part-tag\" id=\"partTag\"></span></div>\n      <h2 id=\"roleTitle\"></h2>\n      <p class=\"muted\" id=\"roleSub\"></p>\n    </div>\n    <div class=\"card\" id=\"qlist\" style=\"padding-block:6px\"></div>\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button class=\"btn ghost\" id=\"back\">Back</button>\n      <button class=\"btn\" id=\"next\" disabled>Next</button>\n    </div>\n  </section>\n\n  <section id=\"result\" hidden>\n    <div class=\"rep\" id=\"report\"></div>\n    <div data-share style=\"margin-top:18px\"></div>\n    <div data-lead></div>\n  </section>\n\n  <div data-disclaimer style=\"margin-top:28px\"></div>\n</div>\n<div class=\"pdf-stage\" id=\"stage\" aria-hidden=\"true\"></div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = 'https://script.google.com/macros/s/AKfycbyizp1XjzNdrUj4WHgj4Vyj81QhjY2D7puqyeY3LaweWB4mePxPhfHCx5fIsfaJy9hV/exec';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = 'https://voznesenskaya.ch/';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {\n  'roza-lyubvi': 'https://claude.ai/artifact/6Nv7pCtqpAd9xoWUkvEwS1',\n  'kompas': 'https://claude.ai/artifact/5TPCgkiVSZEr8H2g8d1UkY'\n};\n// Деловой почтовый адрес и e-mail для «Выходных данных» и «Политики конфиденциальности».\n// ЛИЧНЫЙ АДРЕС ИРИНЫ НЕ УКАЗЫВАТЬ. Пока поля пустые, на страницах стоит временная строка «скоро появятся».\n// address — строки через \\n, например 'Musterstrasse 1\\n8000 Zürich'.\nconst LEGAL = {\n  address: {\n    ru: 'проспект Бажана, 5-Г\\n02121 Киев, Украина',\n    uk: 'просп. Миколи Бажана, 5-Г\\n02121 Київ, Україна',\n    de: 'Mykoly-Bazhana-Prospekt 5-H\\n02121 Kyjiw, Ukraine',\n    en: '5-H Mykoly Bazhana Avenue\\n02121 Kyiv, Ukraine'\n  },\n  email: 'voznesenskaya.iryna@gmail.com', since: '02.10.2026'\n};\n", "const BRAND = 'coach';\nconst TEST_META = { id: 'stupeni', name: 'Steps of Stability', slogan: 'To belong and feel at home in a new country' };\nconst TEST_INFO = {\n  why: 'I created this questionnaire to help you take a gentle look at your life in a new country as a house that is built from the bottom up. After a move, almost everyone goes through the lower steps all over again: sleep and energy, your own people, your own voice, clear rules. The questionnaire shows which steps beneath you are already solid and which one creaks, and suggests where you in particular might begin.',\n  from: [\n    'You live in a new country, and everything seems to be going along as it should, yet something is off. You have less energy than you would like. It feels as if you need to tackle everything at once: the language, work, friends, paperwork, children, and it is unclear where to start.',\n    'Sometimes it seems that everyone else is coping and you are not. And that makes it even harder.'\n  ],\n  to: [\n    'You see your life as a house built from the bottom up, and you know which steps beneath you are already solid. This is your anchor, and there is more of it than it seemed.',\n    'You know the one step to start with, and you understand why that one. You see exactly where the crack is: in what you feel, what you do, what is around you or what you believe. You hear what sounds loudest in your heart, and you can tell a dream from an anchor.',\n    'And you leave with one small step for this week.'\n  ],\n  key: 'You don’t need to fix everything at once. It is enough to strengthen one step, and everything above it will become easier. And the tiredness and confusion after a move are not weakness but the price almost everyone pays.',\n  next: [\n    'Treat the result gently: it is a snapshot of the last 4 weeks, not a judgement of you.',\n    'Start with the lowest step that creaks, even if you want to go straight to the top.',\n    'Lean on the solid steps: they are already yours.',\n    'Read about your step in the guide and answer the questions at the end for yourself.',\n    'In 4–6 weeks, take the test again and see what has changed.',\n    'If things get very hard, talk to someone close to you or to a professional.'\n  ]\n};\nconst TEST_DISCLAIMER = [\n  'The guide and the “Steps of Stability” test are tools for reflection, self-observation and personal growth. They are not psychological or medical diagnostics or a psychotherapeutic assessment, and they do not replace a consultation with a professional. The test is not a diagnosis.',\n  'The test results reflect your personal perception over the last 4 weeks and may change.',\n  'Questions of housing, documents, status and money are handled by social services, lawyers and government agencies. Coaching does not replace them.',\n  'If you are going through a crisis, violence or a threat to your safety, please contact a professional or the emergency services in your country.'\n];\n\n/* превью отчёта веером на стартовой странице (картинки — src/stupeni/preview/1..5.jpg) */\nconst REPORT_FAN = {\n \"pages\": \"12\",\n \"title\": \"What your report will look like\",\n \"lead\": \"Your personal 12-page report is put together from your answers and stays with you as a PDF. It comes with a notes sheet. Here are a few pages from an example: this is what the report looks like for Anna, who moved recently.\",\n \"items\": [\n  {\n   \"t\": \"Your staircase\",\n   \"d\": \"Which step holds firm, which one creaks and which one is best to start with. The main thing is visible on the very first page.\"\n  },\n  {\n   \"t\": \"Three wheels\",\n   \"d\": \"Where you are now, where you want to be and how far apart the two are. The difference speaks for itself.\"\n  },\n  {\n   \"t\": \"Where exactly the crack is\",\n   \"d\": \"Your step across four facets: what you feel, what you do, what you think and what is around you. And your own words.\"\n  },\n  {\n   \"t\": \"Where you are heading\",\n   \"d\": \"Whether you want to stay, what state you are in right now and what exactly is holding you back.\"\n  },\n  {\n   \"t\": \"Next step\",\n   \"d\": \"An invitation to an introductory meeting: 30 minutes online to get to know each other, talk through what you want to work on and see how useful I can be to you.\"\n  },\n  {\n   \"t\": \"Notes sheet for your notes\",\n   \"d\": \"A separate file with all the questions and steps from your report. Print it out and answer by hand: that way your answers are more honest and the steps feel closer.\"\n  }\n ]\n};\n", "/* =====================================================================\n   Библиотека значков — общая для всех тестов (с 02.10.2026).\n   Один стиль: сетка 24×24, мягкая заливка светлым тоном + тонкий контур глубоким тоном того же цвета\n   (как акварель с контуром в утверждённой палитре), линия 1.8, скруглённые концы.\n   Использование: ico('flame', '#C25468', '#EEA9B3', 26) — имя, цвет контура, цвет заливки, размер.\n   Если заливка не задана, берётся очень светлый тон контура.\n   Каталог с картинками всех значков — файл «Библиотека значков.html».\n   ===================================================================== */\nconst ICONS = {\n  /* ступени, дом, опоры */\n  earth:    (c, f, s) => `<circle cx=\"12\" cy=\"8\" r=\"3.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M3 15c3-2 6-2 9 0s6 2 9 0M3 19.5c3-2 6-2 9 0s6 2 9 0\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  hearth:   (c, f, s) => `<path d=\"M12 3c3 4 6.5 6 6.5 10.5a6.5 6.5 0 0 1-13 0c0-3 2-4.5 3-6.5 1 2 2 3 3 3 0-3-1-5 .5-7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M9 21h6\" stroke=\"${c}\" ${s}/>`,\n  door:     (c, f, s) => `<rect x=\"6\" y=\"3\" width=\"12\" height=\"18\" rx=\"1.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"14.8\" cy=\"12.5\" r=\"1.2\" fill=\"${c}\"/><path d=\"M3 21h18\" stroke=\"${c}\" ${s}/>`,\n  key:      (c, f, s) => `<circle cx=\"8\" cy=\"12\" r=\"4.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12.2 12H21M18 12v3M21 12v3\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  workshop: (c, f, s) => `<path d=\"M4.5 11V20.5H19.5V11\" fill=\"#fff\" stroke=\"${c}\" ${s}/><path d=\"M3 7.2L4.6 3.5H19.4L21 7.2V8.6A2.25 2.25 0 0 1 16.5 8.6A2.25 2.25 0 0 1 12 8.6A2.25 2.25 0 0 1 7.5 8.6A2.25 2.25 0 0 1 3 8.6Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M7.5 7.2V8.6M12 7.2V8.6M16.5 7.2V8.6M3 7.2H21\" stroke=\"${c}\" stroke-width=\"1.4\" stroke-linecap=\"round\"/><path d=\"M8 20.5V15.2H11.5V20.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><rect x=\"13.6\" y=\"13.6\" width=\"3.6\" height=\"3.2\" rx=\".6\" fill=\"${f}\" stroke=\"${c}\" stroke-width=\"1.5\"/>`,\n  sprout:   (c, f, s) => `<path d=\"M12 21v-9\" stroke=\"${c}\" ${s}/><path d=\"M12 13c-4.5 0-7-3-7-7 4.5 0 7 3 7 7zM12 11c0-4.5 3-7 7.5-7 0 4.5-3 7-7.5 7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  hill:     (c, f, s) => `<path d=\"M2 19.5l7-9.5 4 5 3-3.5 6 8z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"17\" cy=\"5.5\" r=\"2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  sky:      (c, f, s) => `<path d=\"M12 3l1.9 5.6L19.5 10.5l-5.6 1.9L12 18l-1.9-5.6L4.5 10.5l5.6-1.9z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"19\" cy=\"19\" r=\"1.4\" fill=\"${c}\"/><circle cx=\"5\" cy=\"19.5\" r=\"1\" fill=\"${c}\"/>`,\n  home:     (c, f, s) => `<path d=\"M3.5 11 12 4l8.5 7v9.5h-17z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M10 20.5v-5h4v5\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  homeLight:(c, f, s) => `<path d=\"M3.5 11 12 4l8.5 7v9.5h-17z\" fill=\"none\" stroke=\"${c}\" ${s}/><rect x=\"9\" y=\"11.5\" width=\"6\" height=\"5\" rx=\"1\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 11.5v5M9 14h6\" stroke=\"${c}\" stroke-width=\"1.2\"/>`,\n  /* отношения */\n  flame:    (c, f, s) => `<path d=\"M12 3c3 4 6.5 6 6.5 10.5a6.5 6.5 0 0 1-13 0c0-3 2-4.5 3-6.5 1 2 2 3 3 3 0-3-1-5 .5-7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 20a2.6 2.6 0 0 1-2.6-2.6c0-1.6 1.4-2.4 2.6-4 1.2 1.6 2.6 2.4 2.6 4A2.6 2.6 0 0 1 12 20z\" fill=\"${c}\" fill-opacity=\".35\"/>`,\n  rings:    (c, f, s) => `<circle cx=\"9\" cy=\"12\" r=\"5.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"15\" cy=\"12\" r=\"5.2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  heart:    (c, f, s) => `<path d=\"M12 20s-7.5-4.6-7.5-10.2A4.3 4.3 0 0 1 12 7.3a4.3 4.3 0 0 1 7.5 2.5C19.5 15.4 12 20 12 20z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  bridge:   (c, f, s) => `<path d=\"M2.5 16.5V13.2C7 9.2 17 9.2 21.5 13.2V16.5H18.4C17.4 14.2 15 13 12 13S6.6 14.2 5.6 16.5Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M2.5 10.4C7 6.4 17 6.4 21.5 10.4\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M6 8.3V11.2M10 7.2V10.2M14 7.2V10.2M18 8.3V11.2\" stroke=\"${c}\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><path d=\"M2.5 20.2C4.5 19.1 6.5 19.1 8.5 20.2S12.5 21.3 14.5 20.2 18.5 19.1 21.5 20.2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  together: (c, f, s) => `<path d=\"M12 6.8A6 6 0 0 1 12 17.2A6 6 0 0 1 12 6.8Z\" fill=\"${f}\"/><circle cx=\"9\" cy=\"12\" r=\"6\" fill=\"none\" stroke=\"${c}\" ${s}/><circle cx=\"15\" cy=\"12\" r=\"6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  trees:    (c, f, s) => `<path d=\"M7.5 21v-5M16.5 21v-5\" stroke=\"${c}\" ${s}/><path d=\"M7.5 16.5c-2.6 0-4.3-2-4.3-4.6S5 6 7.5 4c2.5 2 4.3 5.3 4.3 7.9s-1.7 4.6-4.3 4.6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M16.5 16.5c-2.6 0-4.3-2-4.3-4.6S14 6 16.5 4c2.5 2 4.3 5.3 4.3 7.9s-1.7 4.6-4.3 4.6z\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M3 21h18\" stroke=\"${c}\" ${s}/>`,\n  hands:    (c, f, s) => `<path d=\"M3 13.5l4.5-4 4 2.5 4-2.5 5.5 4-6 5.5h-6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M11.5 12l2.5 2.5M9.5 14l2 2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  speech:   (c, f, s) => `<path d=\"M4 5.5h16v10H10l-5 4v-4H4z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M8 9.5h8M8 12.5h5\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  people:   (c, f, s) => `<circle cx=\"8.5\" cy=\"8.5\" r=\"3\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"16\" cy=\"9.5\" r=\"2.6\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M3 19.5c.6-3.4 2.9-5.3 5.5-5.3s4.9 1.9 5.5 5.3M13.5 15c.8-.5 1.6-.7 2.5-.7 2.3 0 4.3 1.7 4.9 4.6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  shield:   (c, f, s) => `<path d=\"M12 3l7.5 3v5.5c0 4.6-3.2 8-7.5 9.5-4.3-1.5-7.5-4.9-7.5-9.5V6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M9 12l2.2 2.2L15.5 10\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  anchor:   (c, f, s) => `<circle cx=\"12\" cy=\"5.5\" r=\"2.3\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 7.8V20M8 11h8M4.5 14c.5 3.5 3.6 6 7.5 6s7-2.5 7.5-6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  /* путь, рефлексия, эксперимент */\n  compass:  (c, f, s) => `<circle cx=\"12\" cy=\"12\" r=\"8.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M14.8 9.2l-1.8 4.8-4.8 1.8 1.8-4.8z\" fill=\"${c}\" fill-opacity=\".85\" stroke=\"${c}\" stroke-width=\"1.2\" stroke-linejoin=\"round\"/>`,\n  path:     (c, f, s) => `<path d=\"M3.5 20.5V17H8v-3.8h4.5V9.5H17v11z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M4.5 12 13 4.5M10 4.5h3v3M20.5 20.5H3\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  telegram: (c, f, s) => `<path d=\"M3.2 11.4L20.2 4.3C20.8 4.1 21.3 4.6 21.2 5.2L18.4 19C18.3 19.6 17.6 19.9 17.1 19.5L12.6 16.2L10.2 18.6C9.9 18.9 9.4 18.7 9.4 18.3V14.8L17 7.8L7.6 13.4L3.4 12.2C2.8 12 2.7 11.6 3.2 11.4Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  instagram:(c, f, s) => `<rect x=\"3.5\" y=\"3.5\" width=\"17\" height=\"17\" rx=\"5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"12\" cy=\"12\" r=\"4\" fill=\"#fff\" stroke=\"${c}\" ${s}/><circle cx=\"16.9\" cy=\"7.1\" r=\"1.1\" fill=\"${c}\"/>`,\n  mail:     (c, f, s) => `<rect x=\"3\" y=\"5.5\" width=\"18\" height=\"13\" rx=\"2.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M3.8 7L12 12.8L20.2 7\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  megaphone:(c, f, s) => `<path d=\"M4 10V14H7L15 18.5V5.5L7 10Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M7 14L8.2 19H10.4L9.6 14\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M18 9.5C19 10.2 19.5 11 19.5 12S19 13.8 18 14.5\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  chatbot:  (c, f, s) => `<path d=\"M5 5H19A2 2 0 0 1 21 7V15A2 2 0 0 1 19 17H11L6.5 20.5V17H5A2 2 0 0 1 3 15V7A2 2 0 0 1 5 5Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"8.5\" cy=\"11\" r=\"1.2\" fill=\"${c}\"/><circle cx=\"12\" cy=\"11\" r=\"1.2\" fill=\"${c}\"/><circle cx=\"15.5\" cy=\"11\" r=\"1.2\" fill=\"${c}\"/>`,\n  swissguide:(c, f, s) => `<path d=\"M2.8 10.6L19.6 3.4C20.3 3.1 20.9 3.7 20.7 4.4L17.2 18.2C17 18.9 16.2 19.1 15.7 18.6L11.4 14.8L9 17.5C8.6 17.9 8 17.6 8 17.1V13.6L16.4 6.2L6.7 12.4L3 11.6C2.4 11.4 2.3 10.8 2.8 10.6Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M18 22.4C18 22.4 13.4 19.7 13.4 16.9A2.3 2.3 0 0 1 18 15.9A2.3 2.3 0 0 1 22.6 16.9C22.6 19.7 18 22.4 18 22.4Z\" fill=\"#D52B1E\" stroke=\"#fff\" stroke-width=\"1\"/><path d=\"M18 16.6V20M16.3 18.3H19.7\" stroke=\"#fff\" stroke-width=\"1.3\" stroke-linecap=\"round\"/>`,\n  signpost: (c, f, s) => `<path d=\"M12 3v18M8.5 21h7\" stroke=\"${c}\" ${s}/><path d=\"M12 5h6.3l2.2 2.2-2.2 2.2H12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 11.5H5.7l-2.2 2.2 2.2 2.2H12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  eye:      (c, f, s) => `<path d=\"M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"12\" cy=\"12\" r=\"3\" fill=\"none\" stroke=\"${c}\" ${s}/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"${c}\"/>`,\n  explore:  (c, f, s) => `<circle cx=\"10.5\" cy=\"10.5\" r=\"6\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M15 15l5.5 5.5\" stroke=\"${c}\" ${s}/><path d=\"M8 9.5a2.8 2.8 0 0 1 2.5-2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  flask:    (c, f, s) => `<path d=\"M9.5 3.5v5.5L4.5 18a2 2 0 0 0 1.8 3h11.4a2 2 0 0 0 1.8-3l-5-9V3.5\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M6.8 15h10.4l1.6 3a1.2 1.2 0 0 1-1.1 1.8H6.3A1.2 1.2 0 0 1 5.2 18z\" fill=\"${f}\" stroke=\"${c}\" stroke-width=\"1.2\"/><path d=\"M8 3.5h8\" stroke=\"${c}\" ${s}/>`,\n  mirror:   (c, f, s) => `<ellipse cx=\"12\" cy=\"9.5\" rx=\"5.5\" ry=\"6.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 16v5M8.5 21h7M9.5 7a3 3 0 0 1 2-1.6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  pen:      (c, f, s) => `<path d=\"M15.5 4.5l4 4L9 19l-5 1 1-5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M13.5 6.5l4 4\" stroke=\"${c}\" ${s}/>`,\n  book:     (c, f, s) => `<path d=\"M3.5 5.5c3-1 5.8-.8 8.5 1 2.7-1.8 5.5-2 8.5-1v13c-3-1-5.8-.8-8.5 1-2.7-1.8-5.5-2-8.5-1z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 6.5v13\" stroke=\"${c}\" ${s}/>`,\n  seed:     (c, f, s) => `<path d=\"M12 20c-3.6 0-6-2.6-6-6.3C6 9.5 9 6 12 4c3 2 6 5.5 6 9.7 0 3.7-2.4 6.3-6 6.3z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 20v-7.5\" stroke=\"${c}\" ${s}/>`,\n  sun:      (c, f, s) => `<circle cx=\"12\" cy=\"12\" r=\"4.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 2.8v2.4M12 18.8v2.4M2.8 12h2.4M18.8 12h2.4M5.5 5.5l1.7 1.7M16.8 16.8l1.7 1.7M5.5 18.5l1.7-1.7M16.8 7.2l1.7-1.7\" stroke=\"${c}\" ${s}/>`,\n  moon:     (c, f, s) => `<path d=\"M19 15.5A8 8 0 0 1 8.5 5a8 8 0 1 0 10.5 10.5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  lantern:  (c, f, s) => `<path d=\"M9 6h6l1.5 3v8L15 20H9l-1.5-3V9z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M10 3.5h4M12 3.5V6M12 11v4\" stroke=\"${c}\" ${s}/>`,\n  cup:      (c, f, s) => `<path d=\"M4.5 9h12v5a5 5 0 0 1-5 5h-2a5 5 0 0 1-5-5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M16.5 10.5h1.5a2.3 2.3 0 0 1 0 4.6h-1.8M8 3.5c-.8 1 .8 2-.1 3M12 3.5c-.8 1 .8 2-.1 3\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  mask:     (c, f, s) => `<path d=\"M4 6.5c5-2 11-2 16 0v5.5c0 4.5-3.6 8-8 8s-8-3.5-8-8z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M7.5 11c1-.8 2.5-.8 3.5 0M13 11c1-.8 2.5-.8 3.5 0M9 15.5c1.8 1.2 4.2 1.2 6 0\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  lock:     (c, f, s) => `<rect x=\"5\" y=\"10.5\" width=\"14\" height=\"10\" rx=\"2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M8 10.5V8a4 4 0 0 1 8 0v2.5M12 14.5v2.5\" fill=\"none\" stroke=\"${c}\" ${s}/>`\n};\n/* светлый тон цвета для заливки по умолчанию */\nconst icoSoft = c => { const h = String(c).replace('#', ''); if (h.length !== 6) return 'none';\n  return '#' + [0, 2, 4].map(i => Math.round(parseInt(h.substr(i, 2), 16) * .3 + 255 * .7).toString(16).padStart(2, '0')).join(''); };\nfunction ico(name, line = '#2E5A88', fill, size = 24){\n  const draw = ICONS[name] || ICONS.seed;\n  const s = 'stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"';\n  return `<svg viewBox=\"0 0 24 24\" width=\"${size}\" height=\"${size}\" aria-hidden=\"true\">${draw(line, fill || icoSoft(line), s)}</svg>`;\n}\n\n/* знак-аватар Ирины: цветок-мандала (с 03.10.2026) */\nconst AVATAR_SVG = '<svg viewBox=\"0 0 100 100\" aria-hidden=\"true\"><circle cx=\"50\" cy=\"50\" r=\"46\" fill=\"#FFFCF8\" stroke=\"#6E4F3C\" stroke-width=\"3\"/><g transform=\"rotate(22.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(67.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(112.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(157.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(202.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(247.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(292.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(337.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(0.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(45.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(90.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(135.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(180.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(225.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(270.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(315.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><circle cx=\"50\" cy=\"50\" r=\"7\" fill=\"#B98324\"/></svg>';\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Iryna Voznesenskaya',\n  about: 'ICF coach in Switzerland and psychologist in Ukraine.',\n  coach: { place: 'Switzerland · Zurich', title: 'Coach', badge: 'Transformational coach and neurocoach, ICF',\n           text: ['I support people who, for many different reasons, have left their country and are now building a life anew in a new place. I know how much strength this takes: stress that lingers even after the papers are sorted, unfamiliar rules, a language in which you cannot yet say what matters most, and the quiet feeling that, along with your home, you left a part of yourself behind.',\n                  'In our work we go deep, through emotional intelligence, to where your reactions and decisions are born. That is why change happens from the inside and stays with you. Step by step you begin to feel you belong in a foreign country, find your place, gently rebuild your sense of self and are, in a way, born anew here to live your happy life.'],\n           legal: 'In Switzerland I work only as a coach. Coaching is not psychotherapy and does not replace psychological or medical care.',\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Ukraine · Kyiv', title: 'Psychologist in Ukraine', badge: 'Psychologist · C. G. Jung’s analytical psychology',\n           text: ['I work with people for whom living, warm relationships matter. Love often does not disappear; it simply grows quiet under fatigue, hurt and everyday routine, and each partner is left alone with their pain.',\n                  'I work at the depth of unconscious processes: through deep dialogue, metaphor, images and symbols, drawing on Carl Jung’s analytical psychology. This brings to light what is hard to put into words, and gives a couple the chance to hear each other again and bring back closeness and warmth.'],\n           legal: 'As a psychologist I work only with clients in Ukraine, based on my Ukrainian qualification.',\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'kompas', path: 'kompas/', name: 'Adaptation Compass', slogan: 'Where you are now in your new country and where to go next', brand: 'coach', tag: 'For people who have moved · 10 minutes', pages: 11,\n    door: 'I have moved abroad and want to understand where I am now',\n    text: 'For people who have moved to another country. Six areas of your new life — language, daily life, work, people, energy and meaning: what has already become a support, where things are still empty, and how you live between two cultures.' },\n  { id: 'stupeni', path: 'stupeni/', name: 'Steps of Stability', slogan: 'To belong and feel at home in a new country', brand: 'coach', tag: 'For those who have moved · guide and test · 20 minutes', pages: 12,\n    door: 'I want to understand why I’m not moving towards my goal',\n    text: 'For those building a life in a new country. Seven steps — from the ground under your feet and your own people to your own work and meaning: which ones already hold you, which one creaks and where to start.' },\n  { id: 'blizost', path: 'blizost/', name: 'Being close and being yourself', slogan: 'Closeness in which you don’t have to lose yourself', brand: 'psy', tag: 'For yourself, about your relationship · 20 minutes', pages: 15,\n    door: 'I want to understand how close we really are',\n    text: 'How close you really are. Through concrete actions — the four pillars of a couple: closeness, passion, commitment and the ability to stay yourself, and what keeps you from coming closer.' },\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/', name: 'The Rose of Love', slogan: 'To hear each other again and bring warmth back to your relationship', brand: 'psy', tag: 'For couples · 15 minutes', pages: 12,\n    door: 'I want to understand what is happening in our relationship',\n    text: 'Three roles in a couple: he is lover, husband and father, she is lover, wife and mother. Specific actions show which roles are vivid, which have gone quieter and what each of you puts into the relationship.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">${ico('instagram', '#C25468', null, 18)} Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">${ico('telegram', '#3F6FBF', null, 18)} Telegram channel</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4>${p.badge ? `<span class=\"pbadge\">${p.badge}</span>` : ''}${[].concat(p.text).map(t => `<p>${t}</p>`).join('')}${p.legal ? `<p class=\"plegal\">${p.legal}</p>` : ''}<div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'About the author'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono av\">${AVATAR_SVG}</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return '© ' + new Date().getFullYear() + ' · ' + (typeof TEST_META !== 'undefined' ? '«' + TEST_META.name + '» · ' : '') + (BRAND === 'coach' ? 'Iryna Voznesenskaya · ICF coach (Switzerland) · psychologist (Ukraine)' : 'Iryna Voznesenskaya · psychologist (Ukraine) · ICF coach (Switzerland)');\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'How did you hear about me?', opts: ['Instagram','Telegram','Recommended by friends or acquaintances','Google search','Facebook','Other'] },\n  interest: { q: 'What are you interested in?', opts: ['Psychology: couple relationships','Coaching: adapting after moving abroad and finding yourself','Just curious for now'] }\n};\nconst GREET = {\n  head: ['Hi! I’m {A}','Glad you’re here! My name is {A}','Welcome! I’m {A}','Hello! I’m {A}'],\n  about: ['ICF coach in Switzerland and psychologist in Ukraine.','I work in two countries: as an ICF coach in Switzerland and as a psychologist in Ukraine.','I help people find themselves and build warm relationships: as an ICF coach in Switzerland and as a psychologist in Ukraine.'],\n  ask: ['Before the test, please answer three short questions. This helps me understand how I can be useful to you.',\n        'Three short questions before we start, and then straight to the test.',\n        'It matters to me to know who comes to my tests. Please answer three short questions.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono av\">${AVATAR_SVG}</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <p class=\"greet-more\"><a href=\"${BASE}#who\">More about me and how I work →</a></p>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} You can choose more than one option.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Go to the test</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, thank you for your honest answers.',\n           '{N}, you are already taking an important step: looking honestly at your relationship.',\n           '{N}, this report is only the beginning of a conversation.',\n           '{N}, the test shows a picture, but real change begins in conversation.',\n           '{N}, behind every number in this report is your own story.'],\n    body: ['The numbers show where things have gone quiet in your couple. But behind them there is always something personal: tiredness, hurt, habits, unspoken expectations. In our meeting we will gently look at your situation and find the first steps to {F}.',\n           'Sometimes one precise question is enough for a couple to hear each other again. If you would like to {F}, I invite you to a meeting: calm, gentle, without judgement.',\n           'Relationships change not through knowledge, but through new actions. I help couples find these actions and not give them up after a week. Let’s look together at how to {F}.',\n           'You can move towards change on your own, or with support. In our meeting we will discuss your triangle and outline how to {F}.',\n           'Many couples live with the same tension for years because they don’t know how to start the conversation. I will help you start it in a way that helps you {F}.'],\n    cta:  ['Book a 30-minute introductory meeting online. We will get to know each other, talk through what you want to work on and see how useful I can be to you.',\n           'The introductory meeting lasts 30 minutes. You tell me what is happening in your relationship, and I listen and ask questions. In that time we will talk through what you want to work on and see how useful I can be to you both.',\n           'The first meeting is 30 minutes online, to get to know each other, talk through what you want to work on and see how useful I can be to you.'],\n    title: ['I invite you to a 30-minute meeting','Let’s talk about your relationship','The next step is a conversation'],\n    legal: 'Psychologist consultations are held online for clients in Ukraine.'\n  },\n  coach: {\n    open: ['{N}, thank you for making time for yourself.',\n           '{N}, you are already taking an important step: looking at yourself honestly and gently.',\n           '{N}, this report is only the beginning of the journey.',\n           '{N}, sometimes one test opens up more questions than answers. And that is good.',\n           '{N}, everything you see now can be turned into support.'],\n    body: ['Moving to a new country changes everything: language, habits, roles in the family and even how we see ourselves. In coaching we look for what supports you in the new world and, step by step, help you {F}.',\n           'When the country changes, we change too. Sometimes it feels like losing yourself. I help you find yourself again so that you can {F}.',\n           'You have already come a long way. Coaching helps you turn this experience into strength and {F}.',\n           'The answers are already within you, but they are hard to hear in the bustle of a new life. Working with me, you will find your own answers and decide how to {F}.',\n           'Adaptation is not only about documents and language. It is about finding your place. Let’s look together at how to {F}.'],\n    cta:  ['Book a 30-minute introductory meeting online. We will get to know each other, talk through what you want to work on and see how useful I can be to you.',\n           'The introductory meeting lasts 30 minutes. You tell me what matters to you right now, and I listen and ask questions. In that time we will talk through what you want to work on and see how useful I can be to you.',\n           'The first meeting is 30 minutes online, to get to know each other, talk through what you want to work on and see how useful I can be to you.'],\n    title: ['I invite you to a 30-minute meeting','Let’s talk about you','The next step is a conversation'],\n    legal: 'Coaching is not psychotherapy and does not replace psychological or medical care.'\n  }\n};\nconst INVITE_HUMAN = {\n  coach: 'A test gives you a map, but it cannot see the whole of you. In a personal meeting, when we work with your own question and your own goal, the work becomes far more productive and brings real results. A machine cannot see what a person with professional skills will notice: the pause before an answer, a tone of voice, what you leave unsaid, and what really matters to you. I work in depth, through emotional intelligence: we look not only at what you do, but also at what you feel and what drives you. That is why change happens at a deep level instead of staying a nice plan on paper.',\n  psy: 'A test gives you a map, but it cannot see your relationship as a whole. In a personal meeting, when we work with your own question and your own goal, the work becomes far more productive and brings real results. A machine cannot see what a person with professional skills will notice: the pause before an answer, a tone of voice, what is left unsaid, and what really matters to each of you. I work at the depth of unconscious processes: through deep dialogue, metaphor and images, drawing on C. G. Jung’s analytical psychology. This brings to light what moves your relationship from within and what is hard to put into words.'\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'bring more warmth and understanding into your relationship', coach: 'find your place in the new world' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /^Coaching/.test(x) : /^Psycholog/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">You are also interested in my work as a ${AUTHOR[other].title.replace(/^./, c => c.toLowerCase())}. You can find out more about it here: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  const word = 'ВСТРЕЧА';\n  const ig = A.instagram ? 'https://ig.me/m/' + handle(A.instagram).slice(1) : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"inv-letter\">\n      <div class=\"eyebrow\">${key === 'psy' ? 'Working on your relationship' : 'Working on yourself'}</div>\n      <h2>${pick(P.title, 0)}</h2>\n      <p class=\"inv-open\">${fill(pick(P.open, 1))}</p>\n      <p>${fill(pick(P.body, 2))}</p>\n      <p class=\"inv-human\">${key === 'psy' ? INVITE_HUMAN.psy : INVITE_HUMAN.coach}</p>\n      <p>${fill(pick(P.cta, 3))}</p>\n      <p class=\"inv-sign\">${AUTHOR.name.split(' ')[0]}</p>\n    </div>\n    <div class=\"inv-ticket\">\n      <div class=\"inv-facts\"><span><b>30</b>minutes</span><span><b>online</b>from home</span><span><b>1:1</b>just us</span></div>\n      <div class=\"inv-how\">\n        <p>To book, send me one word:</p>\n        <div class=\"inv-word\"><span>“${word}”</span><button type=\"button\" class=\"inv-copy\" data-copy=\"${word}\">Copy</button></div>\n        <p class=\"inv-small\">and I will suggest a convenient time.</p>\n      </div>\n      <div class=\"inv-links\">\n        ${ig ? `<a class=\"inv-btn main\" href=\"${ig}\" target=\"_blank\" rel=\"noopener\">Message me on Instagram</a>` : ''}\n        ${A.telegram ? `<a class=\"inv-btn\" href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram</a>` : ''}\n      </div>\n    </div>\n    ${otherLine}\n    <p class=\"note inv-legal\">${P.legal}</p></div>`;\n}\n\ndocument.addEventListener('click', async ev => {\n  const b = ev.target.closest('.inv-copy'); if (!b) return;\n  try { await navigator.clipboard.writeText(b.dataset.copy); b.textContent = 'Copied ✓'; }\n  catch(e){ const r = document.createRange(); r.selectNodeContents(b.previousElementSibling); const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r); b.textContent = 'Selected'; }\n  setTimeout(() => b.textContent = 'Copy', 2500);\n});\n\n/* ---------- Колесо-лепестки (общее для всех тестов) ----------\n   fill — закрашенные лепестки (0–100), outline — пунктир второй точки (0–100), sec — [{label, fill, line}] */\nlet __wheelN = 0;\nfunction petalWheelSVG(sec, fill, outline, size, turn){\n  const n = sec.length, a0 = -Math.PI / 2 + (turn || 0) * 2 * Math.PI / n, da = 2 * Math.PI / n;\n  const sideLen = Math.max(0, ...sec.map((q, k) => Math.abs(Math.cos(a0 + (k + .5) * da)) > .3 ? q.label.length : 0));\n  const W = size || 340, c = W / 2, R0 = W / 2 - Math.max(66, 16 + sideLen * 6.8), h = da / 2 * .9, id = 'pw' + (++__wheelN);\n  const P = (r, a) => `${(c + r * Math.cos(a)).toFixed(1)} ${(c + r * Math.sin(a)).toFixed(1)}`;\n  const petal = (r, th) => { r = Math.max(r, 10); const e = h * .8;\n    return `M${c} ${c}C${P(r * .45, th - h * 1.12)} ${P(r * .86, th - h * 1.12)} ${P(r * .97, th - e)}A${r} ${r} 0 0 1 ${P(r * .97, th + e)}C${P(r * .86, th + h * 1.12)} ${P(r * .45, th + h * 1.12)} ${c} ${c}Z`; };\n  let s = `<svg viewBox=\"0 0 ${W} ${W}\" role=\"img\" aria-label=\"Wheel\"><defs><filter id=\"${id}\" x=\"-5%\" y=\"-5%\" width=\"110%\" height=\"110%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".035\" numOctaves=\"2\" seed=\"${__wheelN % 7 + 2}\"/><feDisplacementMap in=\"SourceGraphic\" scale=\"4\"/></filter></defs>`;\n  s += `<circle cx=\"${c}\" cy=\"${c}\" r=\"${R0 + 6}\" fill=\"#FFFCF8\"/>`;\n  [.25, .5, .75, 1].forEach(f => s += `<circle cx=\"${c}\" cy=\"${c}\" r=\"${(R0 * f).toFixed(1)}\" fill=\"none\" stroke=\"#E2D6C6\" stroke-width=\"${f === 1 ? 1 : .7}\" ${f < 1 ? 'stroke-dasharray=\"1.5 4\"' : ''}/>`);\n  sec.forEach((q, k) => {\n    const th = a0 + (k + .5) * da;\n    if (fill) { const d = petal(R0 * fill[k] / 100, th); s += `<path d=\"${d}\" fill=\"${q.fill}\" fill-opacity=\".92\" filter=\"url(#${id})\"/><path d=\"${d}\" fill=\"none\" stroke=\"${q.line}\" stroke-width=\"1.3\" stroke-linejoin=\"round\"/>`; }\n    if (outline) s += `<path d=\"${petal(R0 * outline[k] / 100, th)}\" fill=\"none\" stroke=\"${q.line}\" stroke-width=\"2\" stroke-dasharray=\"4 4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>`;\n    const [lx, ly] = P(R0 + 18, th).split(' ').map(Number), anchor = Math.abs(lx - c) < 12 ? 'middle' : lx > c ? 'start' : 'end';\n    s += `<text x=\"${(anchor === 'start' ? lx - 2 : anchor === 'end' ? lx + 2 : lx).toFixed(1)}\" y=\"${(ly + 4).toFixed(1)}\" text-anchor=\"${anchor}\" font-family=\"Manrope, sans-serif\" font-size=\"12\" font-weight=\"700\" fill=\"${q.line}\">${q.label}</text>`;\n  });\n  return s + `<circle cx=\"${c}\" cy=\"${c}\" r=\"4\" fill=\"#8C7F71\"/></svg>`;\n}\nconst WHEEL_LEGEND = `<div class=\"st-legend\"><span><i class=\"f\"></i>where you are now</span><span><i class=\"d\"></i>where you want to be</span></div>`;\n\n/* ---------- Остаться или нет (для тестов про жизнь после переезда) ---------- */\nconst STAY_Q = 'Do you want to stay and live here?';\nconst STAY_OPTS = ['Yes, I have decided to stay', 'Probably yes, but sometimes I have doubts', 'I don’t know yet, I’m thinking about it', 'Probably not: I want to go back or move on', 'It is not only my decision'];\n\n/* ---------- Telegram-канал: приглашение подписаться ---------- */\n// Украина → канал психолога (украинская аудитория); любая другая страна или не указана → канал коуча (швейцарская аудитория)\nfunction channelHtml(country){\n  const ua = country === 'Украина' || (!country && BRAND === 'psy'), P = AUTHOR[ua ? 'psy' : 'coach'];\n  return `<div class=\"blk channel\"><div class=\"eyebrow\">Telegram channel</div><h2>Join my channel</h2>\n    <p>The channel is brand new. This is where our ${ua ? 'Ukrainian' : 'Swiss'} audience gathers: ${ua ? 'people for whom warm, living relationships matter' : 'people who live in Switzerland and are building their lives here'}. The plan is to share useful information and to find support and like-minded people. The channel is in Russian. I would be glad if you were among the first.</p>\n    <div class=\"invite-links\"><a href=\"${P.telegram}\" target=\"_blank\" rel=\"noopener\">Subscribe: ${P.telegram.replace('https://', '')}</a></div></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Also try</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span class=\"tslogan\">${t.slogan}</span><span>${t.text}</span><span class=\"tgo\">Take the test →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'This questionnaire is a tool for reflection, self-observation and personal growth, and a starting point for conversation. It is not a psychological or medical diagnosis or a psychotherapeutic assessment, and it does not replace a consultation with a professional.',\n  'The results reflect your personal perception over the last 4 weeks and may change.',\n  'If you are going through a crisis, violence or a threat to your safety, please contact a professional or the emergency services in your country.'\n];\n/* Отношение к жизни как к эксперименту — общая строка для планов во всех тестах (02.10.2026) */\nconst EXPERIMENT = 'Treat these weeks as an experiment. Explore yourself: try a step and observe yourself — what you feel, what comes easily, where resistance shows up. There is no “it worked” or “it didn’t” here: any result is new knowledge about yourself.';\nfunction experimentHtml(){ return `<p class=\"exp-note\">${EXPERIMENT}</p>`; }\n/* Точка А → точка Б: если в TEST_INFO есть from / to / key — показываем, с чем человек приходит и с чем уходит. */\nfunction abHtml(){\n  if (typeof TEST_INFO === 'undefined' || !TEST_INFO.from) return '';\n  const ps = a => [].concat(a).map(x => `<p>${x}</p>`).join('');\n  return `<div class=\"ab\"><div class=\"ab-a\"><span class=\"ab-l\">Point A · where you start</span>${ps(TEST_INFO.from)}</div>\n    <div class=\"ab-arrow\" aria-hidden=\"true\"><svg viewBox=\"0 0 40 24\" width=\"40\" height=\"24\"><path d=\"M2 12h32M26 4l8 8-8 8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div>\n    <div class=\"ab-b\"><span class=\"ab-l\">Point B · what you leave with</span>${ps(TEST_INFO.to)}</div></div>\n    ${TEST_INFO.key ? `<div class=\"ab-key\"><b>The key insight</b><p>${TEST_INFO.key}</p></div>` : ''}`;\n}\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  if (TEST_INFO.from) return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Why take it</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\"><div><h3>What to do with it</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div></div></div>`;\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">About this questionnaire</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>What it gives you</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>What to do with it</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\n/* Текст «Важно» сверяется по смыслу с каждым тестом: свой вариант — TEST_DISCLAIMER в meta.js (null = общая строка). */\nfunction disclaimerHtml(list){\n  const D = list || (typeof TEST_DISCLAIMER !== 'undefined' ? TEST_DISCLAIMER.map((x, i) => x || DISCLAIMER[i]).filter(Boolean) : DISCLAIMER);\n  return `<div class=\"disclaimer\"><b>Important</b>${D.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['I took “The Rose of Love” test for couples: interesting and very accurate. Take it too, then we can compare:',\n                  'I found “The Rose of Love” test: 15 minutes, and you can see which roles in your couple are vivid and which have gone quieter. Give it a try:'],\n  'kompas':      ['I took the “Adaptation Compass” test for people living abroad. It really helps you see where you are now. Give it a try:',\n                  'I found the “Adaptation Compass” test: 10 minutes, and you can see what has already become a support in the new country and what is still quiet. Give it a try:'],\n  'blizost':     ['I took the reflection test “Being close and being yourself” — about how close we really are. Very deep. Try it:',\n                  'I found the test “Being close and being yourself”: 20 honest minutes about closeness, passion and how not to lose yourself in a relationship. Take it:'],\n  'stupeni':     ['I took the “Steps of Stability” test — very warm and accurate, about rebuilding your life after a move. Try it:',\n                  'I found “Steps of Stability”: a guide and test for people living in a new country. You can see which steps hold and which one creaks. Take it:',\n                  'If you also live outside your home country — take “Steps of Stability”. It helped me understand where to start:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Try this test:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Know someone who might find this test useful too? Send them the link.</p>`\n    : `<div class=\"eyebrow\">Share</div><h3>Send the test to friends</h3><p>If the test was useful, send it to people it might help too. ${TEST_META.id === 'roza-lyubvi' || TEST_META.id === 'blizost' ? 'Even better, invite your partner to take it too, and compare how each of you sees your relationship.' : 'Especially to those who have also recently moved.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Share</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Copy link</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Link to the test\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Link copied. Paste it into a message to a friend.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Copy the link from the field above.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\n/* копирайт внизу каждой страницы сайта */\n(function(){ const w = document.querySelector('.wrap'); if (!w || w.querySelector('.copy')) return;\n  const f = document.createElement('footer'); f.className = 'copy'; f.textContent = '© ' + new Date().getFullYear() + ' Iryna Voznesenskaya. All rights reserved.'; w.appendChild(f); })();\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  try { (JSON.parse(localStorage.getItem('irinaTestsSurvey') || '[]') || []).forEach(id => { const c = document.getElementById(id); if (c) c.checked = true; }); } catch(e){}\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Please mark how you heard about me.' : !a.interest.length ? 'Please mark what you are interested in.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    try { localStorage.setItem('irinaTestsSurvey', JSON.stringify([...document.querySelectorAll('input[data-sv]:checked')].map(i => i.id))); } catch(e){}\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n\n/* ---------- превью отчёта веером (стартовая страница теста) ---------- */\n(function(){\n  const host = document.querySelector('[data-reportfan]');\n  if (!host || typeof REPORT_FAN === 'undefined' || !window.RP_IMG || !RP_IMG.length) return;\n  const F = REPORT_FAN, N = Math.min(F.items.length, RP_IMG.length);\n  const calm = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;\n  host.className = 'rf';\n  host.innerHTML = `<div class=\"rf-head\"><div class=\"eyebrow\">Your personal report · PDF</div><h3>${F.title}</h3><p>${F.lead}</p></div>\n    <div class=\"rf-stage stacked\" role=\"group\" aria-label=\"Pages of the sample report\">\n      ${F.items.slice(0, N).map((it, i) => `<button type=\"button\" class=\"rf-page\" data-i=\"${i}\" aria-label=\"Page: ${it.t}\"><img src=\"${RP_IMG[i]}\" alt=\"Sample report page: ${it.t}\" loading=\"lazy\" draggable=\"false\"></button>`).join('')}\n      <span class=\"rf-badge\">${F.pages}<small>pages</small></span>\n    </div>\n    <div class=\"rf-cap\" aria-live=\"polite\"></div>\n    <div class=\"rf-nav\"><button type=\"button\" class=\"rf-arrow\" data-d=\"-1\" aria-label=\"Previous page\">‹</button><div class=\"rf-dots\">${F.items.slice(0, N).map((_, i) => `<span data-i=\"${i}\"></span>`).join('')}</div><button type=\"button\" class=\"rf-arrow\" data-d=\"1\" aria-label=\"Next page\">›</button></div>\n    <p class=\"rf-hint\">Tap the page in the middle to take a closer look.</p>`;\n  const stage = host.querySelector('.rf-stage'), pages = [...host.querySelectorAll('.rf-page')], dots = [...host.querySelectorAll('.rf-dots span')], cap = host.querySelector('.rf-cap');\n  let cur = 0, timer = null;\n  function lay(){\n    const w = stage.clientWidth, deg = w < 420 ? 8 : 10;\n    pages.forEach((p, i) => {\n      let o = i - cur; if (o > N / 2) o -= N; if (o < -N / 2) o += N;\n      const a = Math.abs(o);\n      p.style.transform = `translateX(-50%) rotate(${o * deg}deg) translateY(${o ? a * 4 : -16}px) scale(${o ? 1 - a * .04 : 1.03})`;\n      p.style.zIndex = 10 - a; p.classList.toggle('on', !o);\n      p.tabIndex = o ? -1 : 0;\n    });\n    dots.forEach((d, i) => d.classList.toggle('on', i === cur));\n    cap.innerHTML = `<b>${F.items[cur].t}</b><span>${F.items[cur].d}</span>`;\n  }\n  function go(i, user){ cur = (i + N) % N; lay(); if (user) stop(); }\n  function stop(){ if (timer) clearInterval(timer); timer = null; }\n  pages.forEach((p, i) => p.addEventListener('click', () => i === cur ? zoom(i) : go(i, true)));\n  dots.forEach((d, i) => d.addEventListener('click', () => go(i, true)));\n  host.querySelectorAll('.rf-arrow').forEach(b => b.addEventListener('click', () => go(cur + +b.dataset.d, true)));\n  let sx = null; stage.addEventListener('touchstart', e => { sx = e.touches[0].clientX; }, { passive: true });\n  stage.addEventListener('touchend', e => { if (sx == null) return; const dx = e.changedTouches[0].clientX - sx; if (Math.abs(dx) > 40) go(cur + (dx < 0 ? 1 : -1), true); sx = null; });\n  function zoom(i){\n    const box = document.createElement('div'); box.className = 'rf-zoom'; box.setAttribute('role', 'dialog'); box.setAttribute('aria-label', F.items[i].t);\n    box.innerHTML = `<figure><img src=\"${RP_IMG[i]}\" alt=\"Sample report page: ${F.items[i].t}\"><figcaption>${F.items[i].t} · sample</figcaption></figure><button type=\"button\" class=\"rf-x\" aria-label=\"Close\">×</button>`;\n    const close = () => { box.remove(); document.removeEventListener('keydown', esc); };\n    const esc = e => { if (e.key === 'Escape') close(); };\n    box.addEventListener('click', close); document.addEventListener('keydown', esc);\n    document.body.appendChild(box); box.querySelector('.rf-x').focus();\n  }\n  lay(); window.addEventListener('resize', lay);\n  const open = () => { stage.classList.remove('stacked'); if (!calm && !timer) timer = setInterval(() => go(cur + 1), 3800); };\n  if ('IntersectionObserver' in window && !calm) {\n    const io = new IntersectionObserver(es => { if (es.some(e => e.isIntersecting)) { setTimeout(open, 250); io.disconnect(); } }, { threshold: .35 });\n    io.observe(stage);\n  } else open();\n  host.addEventListener('pointerenter', stop);\n})();\n\n/* ---------- Бланк для записей (печатный PDF к разбору) ----------\n   Во время buildBlocks() тест записывает сюда свои вопросы и шаги:\n   wsReset(); wsAdd(заголовок, пояснение, [вопросы], строк); wsStep(текст). */\nlet WS = { sections: [], steps: [] };\nfunction wsReset(){ WS = { sections: [], steps: [], situation: null }; }\n/* Одна ситуация под микроскопом (с 02.10.2026): в каждом бланке человек берёт одну конкретную ситуацию и проходит её\n   по шагам — факты, мысли, чувство, тело, кем я себя чувствую, что сделала и чего хотела, что было нужно, на что похоже, что иначе.\n   intro — какую ситуацию выбрать (своя для каждого теста); rel — тест об отношениях; male — мужские формы. */\nfunction wsSituation(intro, rel = false, male = false){ WS.situation = { intro, rel, male }; }\nfunction wsSituationQs(rel, male){\n  const g = (f, m) => male ? m : f;\n  return [\n    'What happened? Describe it like a scene from a film: where you were, who said or did what. Only facts, no judgements.'.replace('you were', g('you were', 'you were')),\n    'Which thoughts came first? Write them down word for word, just as they sounded in your head.',\n    'What feeling came up? Name it in one or two words: hurt, fear, anger, shame, loneliness, helplessness, guilt… How strong was it, from 0 to 10?',\n    'Where did this feeling live in your body? What was happening with your breathing, throat, shoulders, stomach, hands?',\n    `${g('Who did you feel you were', 'Who did you feel you were')} in that moment? How old were you inside? ${g('Perhaps a little girl nobody hears, a strict mother, an outsider, guilty, invisible…', 'Perhaps a little boy nobody hears, a strict father, an outsider, guilty, invisible…')}`,\n    `What did you ${g('do', 'do')}? And what did you really want to do or say?`,\n    rel ? 'What did you need in that moment — from your partner and from yourself?'.replace('yourself', g('yourself', 'yourself')) : `What did you need in that moment — from other people and from ${g('yourself', 'yourself')}?`,\n    `What does this remind you of? When have you ${g('felt', 'felt')} like this before: ${rel ? 'in this relationship, in past ones,' : 'before the move,'} in your family, in childhood?`,\n    'If this situation happened again tomorrow, what would you do differently? One small action.'.replace('do', g('do', 'do'))\n  ];\n}\nfunction wsAdd(title, note, qs, lines = 6){ if (qs && qs.length) WS.sections.push({ title, note, qs, lines }); }\nfunction wsStep(t){ if (t) WS.steps.push(String(t).replace(/<[^>]+>/g, '')); }\nfunction liTexts(html){ const d = document.createElement('div'); d.innerHTML = html; return [...d.querySelectorAll('li')].map(x => x.textContent.replace(/\\s+/g, ' ').trim()).filter(Boolean); }\nconst wsLines = n => `<div class=\"ws-lines\">${'<i></i>'.repeat(n)}</div>`;\nfunction worksheetBlocks(opts = {}){\n  const pair = !!opts.pair, nm = opts.name ? esc(opts.name) : '';\n  const B = [];\n  B.push({ html: `<div class=\"blk ws ws-head\"><div class=\"eyebrow\">Notes sheet · for the report “${TEST_META.name}”</div>\n    <h1>${TEST_META.name}</h1>${TEST_META.slogan ? `<p class=\"slogan\">${TEST_META.slogan}</p>` : ''}\n    <div class=\"ws-fields\"><span>Name<i>${nm}</i></span><span>Date<i></i></span></div>\n    <p>This notes sheet is your place for honest answers. Print it out, make yourself a cup of tea and find a quiet corner. Write by hand, slowly and without drafts: the hand often knows more than we have time to think. There are no right answers here, and nobody but you will read them.</p>\n    <p>Treat these pages as an exploration of yourself. Notice which questions speak to you straight away and which you would rather avoid: that is important knowledge too.</p>\n    <p class=\"note\">The questions come from your report. If you have no answer to a question right now, leave it and come back later. An empty line is an answer too.</p></div>` });\n  let n = 0;\n  WS.sections.forEach(s => s.qs.forEach((q, i) => {\n    n++;\n    B.push({ html: `<div class=\"blk ws ws-q\">${i === 0 ? `<div class=\"ws-sec\"><h2>${s.title}</h2>${s.note ? `<p class=\"note\">${s.note}</p>` : ''}</div>` : ''}\n      <div class=\"ws-row\"><span class=\"ws-n\">${n}</span><div><p class=\"ws-qt\">${q}</p>${wsLines(s.lines)}</div></div></div>` });\n  }));\n  if (WS.situation){\n    const S = WS.situation, qs = wsSituationQs(S.rel, S.male);\n    qs.forEach((q, i) => { n++; B.push({ newPage: i === 0, html: `<div class=\"blk ws ws-q\">${i === 0 ? `<div class=\"ws-sec\"><h2>One situation under the microscope</h2><p>${S.intro}</p><p class=\"note\">Go through the questions slowly, from top to bottom. Don’t look for right answers: simply notice what was happening inside you. Often it is one small situation that shows what is really going on.</p></div>` : ''}\n      <div class=\"ws-row\"><span class=\"ws-n\">${n}</span><div><p class=\"ws-qt\">${q}</p>${wsLines(i === 0 ? 6 : 4)}</div></div></div>` }); });\n  }\n  const goalQ = pair\n    ? ['How do we want to be with each other in three months?', 'What small signs will tell us that we are moving forward?', 'What could stop us, and what will we do then?']\n    : ['What do I want for myself in three months? Describe it as if it has already happened.', 'What small signs will tell me that I am moving forward?', 'What could stop me, and what will I do then?'];\n  goalQ.forEach((q, i) => { n++; B.push({ html: `<div class=\"blk ws ws-q\">${i === 0 ? `<div class=\"ws-sec\"><h2>${pair ? 'Our goal' : 'My goal'}</h2><p class=\"note\">A goal written in your own hand comes closer.</p></div>` : ''}\n    <div class=\"ws-row\"><span class=\"ws-n\">${n}</span><div><p class=\"ws-qt\">${q}</p>${wsLines(5)}</div></div></div>` }); });\n  if (WS.steps.length) B.push({ newPage: true, html: `<div class=\"blk ws ws-plan\"><div class=\"ws-sec\"><h2>My steps for 4 weeks</h2><p class=\"note\">The steps from your report. Each week, note what worked and what you notice. Small wins count too.</p></div>\n    <div class=\"ws-steps\">${WS.steps.map(t => `<p><span class=\"ws-box\"></span>${t}</p>`).join('')}</div>\n    <div class=\"ws-weeks\">${[1,2,3,4].map(w => `<div><b>Week ${w}</b><small>What worked</small>${wsLines(3)}<small>What I notice</small>${wsLines(2)}</div>`).join('')}</div></div>` });\n  B.push({ html: `<div class=\"blk ws ws-q\"><div class=\"ws-sec\"><h2>After 4 weeks</h2><p class=\"note\">Read through everything written above and answer three more questions.</p></div>\n    ${['What has changed during this time?', (pair ? 'What turned out to be the hardest, and what was easier than we thought?' : (WS.situation && WS.situation.male ? 'What turned out to be the hardest, and what was easier than I thought?' : 'What turned out to be the hardest, and what was easier than I thought?')), (pair ? 'What do we want to take with us going forward?' : 'What do I want to take with me going forward?')].map(q => `<p class=\"ws-qt\">${q}</p>${wsLines(4)}`).join('')}</div>` });\n  B.push({ html: `<div class=\"blk ws ws-end\"><p>When you have finished, take the test again and compare your reports. And if you would like to talk about what you have written with a real person, come to an introductory meeting: 30 minutes online, free of charge. We will get to know each other, talk through what you want to work on and see how useful I can be to you. To book, send me the word “ВСТРЕЧА”.</p><p class=\"ws-sign\">${AUTHOR.name}</p></div>` });\n  return B;\n}\nfunction wsNoteHtml(){\n  const url = (typeof SITE_URL !== 'undefined' && SITE_URL ? SITE_URL.replace(/\\/?$/, '/') : '') + (TEST_META.id === 'stupeni' ? 'stupeni/' : TEST_META.id + '/');\n  return `<div class=\"blk ws-note\"><div class=\"eyebrow\">Notes sheet</div><h3>Answer the questions by hand</h3>\n    <p>This report comes with a separate file: a notes sheet. It contains all the questions and steps from your report, with lines for your answers. Print it out and write by hand, without hurrying: that way your answers become more honest and the steps feel closer.</p>\n    <p class=\"note\">${window.__PDF ? `The notes sheet is downloaded together with this report; look for it in your “Downloads” folder. If it is not there, open the test on the <a href=\"${url}\">website</a>, open your report, and below the form you will find the “Download notes sheet” button.` : 'The notes sheet is downloaded together with the PDF report via the form below.'}</p></div>`;\n}\n", "/* =====================================================================\n   Данные и конфиденциальность — общее для всех тестов (с 02.10.2026).\n   - Ответы тестов хранятся только в браузере человека и через 90 дней удаляются сами.\n   - Кнопка «Удалить мои ответы».\n   - Страна спрашивается в мини-опросе (раньше — в анкете перед PDF).\n   - Ссылки на Политику конфиденциальности и Выходные данные в подвале.\n   Тексты на четырёх языках — здесь же (PRIV). Подключается после brand.js, до теста.\n   ===================================================================== */\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst DATA_DAYS = 90;\n\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nconst PRIV_ALL = {\n  ru: {\n    countryQ: 'Где ты сейчас живёшь?', countryPick: 'Выбери страну', countryTop: 'Часто выбирают', countryAll: 'Все страны', countryOther: 'Другая страна',\n    countryErr: 'Выбери, пожалуйста, страну, в которой ты сейчас живёшь.',\n    countryNote: 'Страна нужна, чтобы показать в разборе подходящее приглашение и полезные ссылки.',\n    privacy: 'Политика конфиденциальности', impressum: 'Выходные данные', home: 'Главная', allTests: 'Все тесты',\n    onlyYou: 'Твои ответы остаются только у тебя. Я их не вижу.',\n    keepUntil: d => `Твои ответы и разбор хранятся только на этом устройстве, до ${d}. Потом они удалятся сами. Скачай PDF, если хочешь сохранить разбор.`,\n    del: 'Удалить мои ответы', delAsk: 'Удалить все ответы этого теста с этого устройства? Разбор тоже исчезнет. Если хочешь его сохранить, сначала скачай PDF.',\n    delYes: 'Да, удалить', delNo: 'Отмена', delDone: 'Ответы удалены с этого устройства.'\n  },\n  uk: {\n    countryQ: 'Де ти зараз живеш?', countryPick: 'Обери країну', countryTop: 'Часто обирають', countryAll: 'Усі країни', countryOther: 'Інша країна',\n    countryErr: 'Обери, будь ласка, країну, у якій ти зараз живеш.',\n    countryNote: 'Країна потрібна, щоб показати в розборі відповідне запрошення та корисні посилання.',\n    privacy: 'Політика конфіденційності', impressum: 'Вихідні дані', home: 'Головна', allTests: 'Усі тести',\n    onlyYou: 'Твої відповіді залишаються тільки в тебе. Я їх не бачу.',\n    keepUntil: d => `Твої відповіді та розбір зберігаються тільки на цьому пристрої, до ${d}. Потім вони видаляться самі. Завантаж PDF, якщо хочеш зберегти розбір.`,\n    del: 'Видалити мої відповіді', delAsk: 'Видалити всі відповіді цього тесту з цього пристрою? Розбір теж зникне. Якщо хочеш його зберегти, спочатку завантаж PDF.',\n    delYes: 'Так, видалити', delNo: 'Скасувати', delDone: 'Відповіді видалено з цього пристрою.'\n  },\n  de: {\n    countryQ: 'Wo lebst du zurzeit?', countryPick: 'Wähle ein Land', countryTop: 'Häufig gewählt', countryAll: 'Alle Länder', countryOther: 'Anderes Land',\n    countryErr: 'Wähle bitte das Land, in dem du zurzeit lebst.',\n    countryNote: 'Das Land brauche ich, um dir in der Auswertung die passende Einladung und hilfreiche Links zu zeigen.',\n    privacy: 'Datenschutzerklärung', impressum: 'Impressum', home: 'Startseite', allTests: 'Alle Tests',\n    onlyYou: 'Deine Antworten bleiben nur bei dir. Ich sehe sie nicht.',\n    keepUntil: d => `Deine Antworten und die Auswertung sind nur auf diesem Gerät gespeichert, bis ${d}. Danach werden sie automatisch gelöscht. Lade das PDF herunter, wenn du die Auswertung behalten möchtest.`,\n    del: 'Meine Antworten löschen', delAsk: 'Alle Antworten dieses Tests von diesem Gerät löschen? Auch die Auswertung verschwindet. Wenn du sie behalten möchtest, lade zuerst das PDF herunter.',\n    delYes: 'Ja, löschen', delNo: 'Abbrechen', delDone: 'Die Antworten wurden von diesem Gerät gelöscht.'\n  },\n  en: {\n    countryQ: 'Where do you live now?', countryPick: 'Choose a country', countryTop: 'Frequently chosen', countryAll: 'All countries', countryOther: 'Other country',\n    countryErr: 'Please choose the country where you live now.',\n    countryNote: 'I need the country to show you the right invitation and useful links in your results.',\n    privacy: 'Privacy policy', impressum: 'Legal notice', home: 'Home', allTests: 'All tests',\n    onlyYou: 'Your answers stay with you only. I cannot see them.',\n    keepUntil: d => `Your answers and results are stored only on this device, until ${d}. After that they are deleted automatically. Download the PDF if you want to keep your results.`,\n    del: 'Delete my answers', delAsk: 'Delete all answers to this test from this device? Your results will disappear too. If you want to keep them, download the PDF first.',\n    delYes: 'Yes, delete', delNo: 'Cancel', delDone: 'Your answers have been deleted from this device.'\n  }\n};\nconst PRIV = PRIV_ALL[PAGE_LANG] || PRIV_ALL.ru;\n\n/* ---------- 1. Автоудаление ответов через 90 дней ---------- */\n(function purge(){\n  try {\n    const limit = Date.now() - DATA_DAYS * 864e5;\n    for (let i = localStorage.length - 1; i >= 0; i--){\n      const k = localStorage.key(i);\n      if (!k || !/^irinaTests\\./.test(k)) continue;\n      let v = null; try { v = JSON.parse(localStorage.getItem(k) || 'null'); } catch(e){}\n      const t = v && (v.t || v.startedAt);\n      if (!t || t < limit) localStorage.removeItem(k);\n    }\n    localStorage.removeItem('irinaTestsLead');   // прежняя анкета (с e-mail) больше не хранится\n  } catch(e){}\n})();\n\n/* ключ сохранённых ответов текущего теста */\nfunction answersKey(){ return (typeof TEST_META !== 'undefined') ? 'irinaTests.' + TEST_META.id + '.v1' : ''; }\nfunction answersSavedAt(){ try { const v = JSON.parse(localStorage.getItem(answersKey()) || 'null'); return v ? (v.t || v.startedAt || 0) : 0; } catch(e){ return 0; } }\nfunction retentionLine(){\n  const t = answersSavedAt() || Date.now();\n  const d = new Date(t + DATA_DAYS * 864e5).toLocaleDateString(typeof DATE_LOCALE !== 'undefined' ? DATE_LOCALE : 'ru-RU', { day:'2-digit', month:'2-digit', year:'numeric' });\n  return PRIV.keepUntil(d);\n}\n\n/* ---------- 2. Страна в мини-опросе ---------- */\nconst COUNTRY_KEY = 'irinaTestsCountry';\nfunction surveyCountry(){\n  const s = document.getElementById('svCountry');\n  if (s && s.value) return s.value;\n  try { return localStorage.getItem(COUNTRY_KEY) || ''; } catch(e){ return ''; }\n}\n// Тесты раньше брали страну из анкеты (window.__leadCountry). Теперь она всегда берётся из мини-опроса.\ntry { Object.defineProperty(window, '__leadCountry', { configurable: true, get: surveyCountry, set: () => {} }); } catch(e){}\n\nfunction countrySelectHtml(id){\n  return `<select id=\"${id}\"><option value=\"\">${PRIV.countryPick}</option></select>`;\n}\nfunction fillCountrySelect(sel, value){\n  if (!sel || sel.options.length > 1) return;\n  const g1 = document.createElement('optgroup'); g1.label = PRIV.countryTop;\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = PRIV.countryAll;\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option(PRIV.countryOther, OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n  if (value && (COUNTRIES.includes(value) || value === OTHER_COUNTRY)) sel.value = value;\n}\n(function surveyCountryField(){\n  const box = document.querySelector('[data-greeting] .surveys'); if (!box || document.getElementById('svCountry')) return;\n  const fs = document.createElement('fieldset'); fs.className = 'survey sv-country';\n  fs.innerHTML = `<legend>${PRIV.countryQ} *</legend>${countrySelectHtml('svCountry')}<p class=\"note\">${PRIV.countryNote}</p>`;\n  box.appendChild(fs);\n  let saved = ''; try { saved = localStorage.getItem(COUNTRY_KEY) || ''; } catch(e){}\n  const sel = fs.querySelector('select'); fillCountrySelect(sel, saved);\n  sel.addEventListener('change', () => { try { localStorage.setItem(COUNTRY_KEY, sel.value); } catch(e){} });\n  // без страны тест не открывается (проверка срабатывает раньше общей кнопки «Перейти к тестированию»)\n  document.addEventListener('click', ev => {\n    const go = ev.target.closest && ev.target.closest('#svGo'); if (!go) return;\n    const a = (typeof surveyAnswers === 'function') ? surveyAnswers() : { heard: [1], interest: [1] };\n    if (!a.heard.length || !a.interest.length) return;          // об этих вопросах скажет общая проверка\n    if (!sel.value){\n      ev.stopPropagation(); ev.preventDefault();\n      const err = document.getElementById('svErr'); if (err){ err.textContent = PRIV.countryErr; err.hidden = false; }\n      sel.focus();\n    } else { try { localStorage.setItem(COUNTRY_KEY, sel.value); } catch(e){} }\n  }, true);\n})();\n\n/* ---------- 3. Удалить мои ответы ---------- */\nfunction deleteAnswersHtml(){\n  if (!answersKey()) return '';\n  return `<div class=\"del-answers\"><button type=\"button\" class=\"linkbtn\" data-del-answers>${PRIV.del}</button>\n    <div class=\"del-ask\" hidden><p>${PRIV.delAsk}</p><div class=\"row\"><button type=\"button\" class=\"btn small\" data-del-yes>${PRIV.delYes}</button><button type=\"button\" class=\"btn ghost small\" data-del-no>${PRIV.delNo}</button></div></div>\n    <p class=\"note del-done\" hidden>${PRIV.delDone}</p></div>`;\n}\ndocument.addEventListener('click', ev => {\n  const b = ev.target.closest && ev.target.closest('[data-del-answers],[data-del-yes],[data-del-no]'); if (!b) return;\n  const box = b.closest('.del-answers'), ask = box.querySelector('.del-ask');\n  if (b.hasAttribute('data-del-answers')){ ask.hidden = !ask.hidden; return; }\n  if (b.hasAttribute('data-del-no')){ ask.hidden = true; return; }\n  try {\n    const pre = 'irinaTests.' + TEST_META.id + '.';\n    for (let i = localStorage.length - 1; i >= 0; i--){ const k = localStorage.key(i); if (k && k.indexOf(pre) === 0) localStorage.removeItem(k); }\n  } catch(e){}\n  ask.hidden = true; box.querySelector('.del-done').hidden = false;\n  setTimeout(() => { location.hash = ''; location.reload(); }, 900);\n});\n\n/* ---------- 4. Подвал: правовые ссылки и удаление ответов ---------- */\nfunction legalUrl(page){\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  return root + page + '/';\n}\nfunction privacyLinksHtml(){\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  return `<a href=\"${root}\">${PRIV.home}</a> · <a href=\"${root}testy/\">${PRIV.allTests}</a> · <a href=\"${legalUrl('privacy')}\">${PRIV.privacy}</a> · <a href=\"${legalUrl('impressum')}\">${PRIV.impressum}</a>`;\n}\n(function footer(){\n  const f = document.querySelector('.wrap .copy'); if (!f || f.querySelector('.legal-links')) return;\n  const p = document.createElement('span'); p.className = 'legal-links'; p.innerHTML = privacyLinksHtml();\n  f.appendChild(document.createElement('br')); f.appendChild(p);\n  if (answersKey() && document.getElementById('intro')){\n    const d = document.createElement('div'); d.innerHTML = deleteAnswersHtml(); f.appendChild(d.firstElementChild);\n  }\n})();\n/* строка «Твои ответы остаются только у тебя» на стартовой странице, рядом с кнопкой начала */\n(function startNote(){\n  const host = document.querySelector('#testStart [data-share=\"compact\"]'); if (!host || document.querySelector('.only-you')) return;\n  const p = document.createElement('p'); p.className = 'note only-you';\n  p.innerHTML = `${PRIV.onlyYou} <a href=\"${legalUrl('privacy')}\">${PRIV.privacy}</a>`;\n  host.parentNode.insertBefore(p, host);\n})();\n\n/* ---------- 6. Общая шапка сайта на каждой странице (тесты, «Тесты», правовые) — вернуться можно откуда угодно ---------- */\n(function siteHeader(){\n  if (document.querySelector('.sitebar')) return;\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  const T = {\n    ru: { sub: 'специалист по адаптации · коуч', name: 'Ирина Вознесенская', nav: ['Обо мне', 'Работа со мной', 'Продукты', 'Твой путь', 'Тесты', 'Свои люди'], cta: 'Знакомство' },\n    uk: { sub: 'фахівчиня з адаптації · коуч', name: 'Ірина Вознесенська', nav: ['Про мене', 'Робота зі мною', 'Продукти', 'Твій шлях', 'Тести', 'Свої люди'], cta: 'Знайомство' },\n    de: { sub: 'Coach fürs Ankommen', name: 'Iryna Voznesenskaya', nav: ['Über mich', 'Arbeit mit mir', 'Angebote', 'Dein Weg', 'Tests', 'Svoi ludi'], cta: 'Kennenlernen' },\n    en: { sub: 'relocation coach', name: 'Iryna Voznesenskaya', nav: ['About me', 'Work with me', 'Services', 'Your path', 'Tests', 'Svoi ludi'], cta: 'Intro call' }\n  }[PAGE_LANG] || {};\n  const L = T.nav ? T : { sub: 'специалист по адаптации · коуч', name: 'Ирина Вознесенская', nav: ['Обо мне', 'Работа со мной', 'Продукты', 'Твой путь', 'Тесты', 'Свои люди'], cta: 'Знакомство' };\n  const hrefs = [root + '#who', root + '#requests', root + '#path', root + 'put/', root + 'testy/', 'https://svoiludi.ch/'];\n  const here = location.pathname.replace(/\\/+$/, '').split('/').pop();\n  const h = document.createElement('header'); h.className = 'sitebar';\n  h.innerHTML = `<div class=\"sitebar-in\">\n    <a class=\"sb-mark\" href=\"${root}\"><span class=\"sb-mono av\">${typeof AVATAR_SVG !== \"undefined\" ? AVATAR_SVG : \"ИВ\"}</span><span><b>${L.name}</b><small>${L.sub}</small></span></a>\n    <nav class=\"sb-nav\" aria-label=\"Menu\">${L.nav.map((t, i) => `<a href=\"${hrefs[i]}\"${i === 4 && here === 'testy' ? ' aria-current=\"page\"' : ''}>${t}</a>`).join('')}</nav>\n    <a class=\"sb-cta\" href=\"https://t.me/IrynaNeuroCoach\" target=\"_blank\" rel=\"noopener\">${L.cta}</a></div>`;\n  document.body.insertBefore(h, document.body.firstChild);\n})();\n", "/* СГЕНЕРИРОВАНО из «Вход 1 — Путеводитель по уровням.md» скриптом tools/guide2js.py — правки вносить в md */\nconst GUIDE = {\n \"introTitle\": \"A house built anew\",\n \"intro\": \"<p>Imagine: you have moved. The suitcases are unpacked, the paperwork submitted, the children have a new school. But along with the city and the flat, you left your whole home behind in the old place. Not the walls, but the invisible thing that held you up for years. The familiar rhythm of the day. People you could call in the middle of the night. The language you joke in. Clear rules. Work for which you were respected. And the quiet feeling of “this is my life”.</p><p>In the new place, this invisible home has to be built again. And it is built the same way as any real house, from the bottom up. First the ground you can stand on. Then the hearth. Then the walls, the windows, the roof. Nobody starts with the roof: it simply would not hold.</p><p>More than half a century ago, the American psychologist Clare Graves spent many years asking all kinds of people one question: “What is a good life for you?” The answers turned out to resemble a staircase. Every person has steps, and each one grows out of the one before. Later his students called this Spiral Dynamics and gave each step its own colour. It sounds scientific, but in practice it is all very human. It is a map of what a person needs in order to live rather than merely survive.</p><p>The steps are not grades. The lower one is no worse than the upper one, just as a foundation is no worse than a roof. When you are cold, it is right to think about warmth, not about the meaning of life. The lower steps hold up the higher ones: if one step wobbles, it is hard to stand any higher, however much effort you put in. That is why it is always worth starting with the lowest one that creaks.</p><p>Moving pushes almost everyone downwards. At home you may have stood confidently high up, but here the lower steps are knocked out in a single blow, and you are learning all over again to sleep, to find your people, to speak, to make sense of the rules. This is not a setback and not a weakness. It is the price of moving, and everyone pays it. And one more thing: once you have climbed higher, you do not throw away the lower steps, you stand on them. Sleep and your own people are needed even by someone who is already at the very top.</p><p>Graves noticed another important thing: the steps are a response to life conditions. When conditions change, a person has to search for an anchor again, and that is normal. That is exactly why moving shakes you up so much: all the conditions changed at once.</p><p>And his students Don Beck and Christopher Cowan described how people change in general. Not in a straight line, but in a circle. First comes balance: life and what you need match up. Then a vague unease: something is wrong, but it is unclear what. Then a dead end: it is already clear what is wrong, but there seems to be no way out, and that brings anger and helplessness. Then a shift: the barrier is named, another path appears, and suddenly things feel easy. And finally a new balance, already one step higher. Each of these states is normal. What matters is not to get stuck in any of them.</p><p>Beck and Cowan also noticed that change needs certain conditions. It needs energy, and there is none while the lower questions remain unresolved. It needs the feeling of “I don’t want to go on like this”. It needs clarity about what exactly is wrong and where you could go. The barrier needs to be called by its name. And it needs support close by while the new is still unfamiliar. If any of this is missing, a person stays where they are, however hard they try. The test will help you see which of these you have and which you still lack.</p><p>Read from the bottom up, without hurrying. In some places you will recognise yourself straight away, in others you will smile: “that was me in my first year”. At the end of each step, five questions are waiting for you. Take a pen and answer in writing: five minutes of honesty with yourself sometimes give more than a month of thinking.</p><blockquote><p>This is not a judgement and not a test of “am I normal”. It is a map. It does not tell you who you are — it shows what you need right now.</p></blockquote>\",\n \"levels\": [\n  {\n   \"n\": 1,\n   \"name\": \"Ground under your feet\",\n   \"color\": \"Beige\",\n   \"sub\": \"the body step\",\n   \"teaser\": \"When the main thing is just staying on your feet\",\n   \"note\": \"\",\n   \"body\": \"<p>Do you remember stepping ashore after a long voyage? The ground is still swaying, your legs feel like cotton wool, and until you have stood for a while, drunk some water and had a good sleep, none of the beauty of the new shore can bring you joy. Everything starts with this step: simply staying on your feet.</p><p>This is the body step. Sleep, food, warmth, a roof over your head and the simple feeling that nothing will collapse tomorrow. There are no big plans here, just a body that needs to recover. An adult comes back here every time there is less energy than life demands: illness, the birth of a child, grief. And a move.</p><p>At home almost everything ran by itself. You did not think about how to get to the shop, what to say at the pharmacy, where the light switch is. In the new place nothing runs by itself. Every action turns into a little exam: read, understand, ask again, guess. Your mind stands guard all day like a watchman, and by evening there is no energy left at all, even though you “didn’t do anything special”. This is not laziness. It is the bill your body sends you for having to reboot all your habits at once.</p><blockquote><p>“I fall asleep to my phone and wake up at four in the morning.” “My head and back hurt, and the doctors say everything is fine.” “During the day I forget to eat, and in the evening I comfort-eat.” “What will happen in six months? We’ll see.” “All I want is for everyone to go to bed and for it to be quiet.”</p></blockquote><p>Sometimes there really is no ground under your feet: the housing is temporary, money is short, others decide about your documents, and it is unclear what will happen after the next extension. This is often the case for those who fled the war, and here social services should be the first to help, while my work runs alongside and a little later. And sometimes it is the other way round: the flat, the insurance and the money are all in order, yet you cannot sleep and are constantly as tense as a stretched string. Well-being on the outside, wobbly legs on the inside.</p><p>When this step is solid, you wake up with energy and do not eat on the run. You have your own corner where you can close the door and breathe out. You know roughly what the next few months will bring, and that is enough to let your shoulders drop.</p><p>The gift of the beige step is that it teaches you to listen to your body and look after your energy. Someone who has gone through it gently no longer confuses tiredness with laziness and can say to themselves: “Today I have done enough.” The catch is that you can forget to leave survival mode. The danger passed long ago, yet you still skimp on food and put off seeing a doctor “just in case”. Or you do not allow yourself to rest until everything is sorted, and it is never sorted.</p><p>What helps you climb from here is not a heroic effort but rhythm. Going to bed at the same time. Standing in daylight for ten minutes in the morning. Making one corner of your home your own: hanging up something you love, putting out a cup that makes you happy. Drawing a small horizon in three columns: what I know for sure, what will be settled by a certain date, what does not depend on me. When your body has rested a little, you will have energy for people, and you will step higher on your own.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>When did I last wake up truly rested?</li><li>Where in my home is there a place that is mine alone?</li><li>What do I know for sure about the next six months? And what does not depend on me — and can I let it go?</li><li>What am I putting off “for later” when it comes to my body?</li><li>Who can I say “I’m having a hard time right now” to?</li></ol>\"\n  },\n  {\n   \"n\": 2,\n   \"name\": \"The hearth and your people at the table\",\n   \"color\": \"Purple\",\n   \"sub\": \"the “we” step\",\n   \"teaser\": \"When you long for someone to be waiting for you in the evening\",\n   \"note\": \"\",\n   \"body\": \"<p>Evening. A fire is burning, and your own people are sitting at the table. You can speak your mother tongue, laugh at old jokes and stay silent without explaining anything. Here you are known, awaited, and missed if you do not come.</p><p>Humans are pack animals: alone, we survive neither in the forest nor in a foreign country. The second step is about belonging. About your own people, family, roots, celebrations, about that warm “we”. Here you are strong not on your own, but because you are with someone.</p><p>At home, your circle formed by itself, over years: the neighbourhood, school, university, work. Here nobody will hand it down to you. You have to build it again, as an adult, when time is short and the first step is somehow so hard to take. And the language does not help: friendship starts with small talk about nothing, the weather or a funny moment on the bus, and that very lightness is something a foreign language does not give you yet. Then there is a strange feeling of being “in between”: back home you are already a bit of a stranger, and here you do not belong yet.</p><blockquote><p>“There is someone I can text ‘how are you’, but no one I can tell ‘I feel awful’.” “Lots of acquaintances, but all of them out of circumstance.” “The holidays are the hardest.” “I am ashamed to admit I am lonely: after all, everything is fine with us.”</p></blockquote><p>At the same time, approaching Russian-speaking communities can feel daunting: arguments, comparisons, talk about who has settled in how. And you end up somewhere in the middle, among people but without your own.</p><p>When this step is solid, you have at least one person you can call late in the evening. There is a place or a group where people are glad to see you. Your celebrations live on here too, and your connection with your family is warm and alive.</p><p>The gift of the purple step is warmth and protection. Your own people have your back. This step preserves language, cooking, fairy tales and songs, everything that is later passed on to children, and without it any success feels empty. The catch is that the hearth can turn into a fortress. You can shut yourself in with your own and never go out to the locals: “they are cold, we are different”. You can cling to a circle that has long stopped keeping you warm, because you are afraid of being left completely alone. Or keep quiet about yourself just so you are not thrown out of the pack.</p><p>What helps you kindle this fire is not courage or charm, but repetition. The same people, at the same time, every week. An acquaintance becomes an acquaintance from the second meeting, so inviting someone again is not being pushy. When at least one person of your own is close by, you will grow an anchor from which to start acting yourself.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Who would I call if I felt bad tonight?</li><li>Where have I been in the past month “just because”, not on business?</li><li>Which of our traditions live on in my home here? Which have I lost — and do I want them back?</li><li>Who have I felt warmth with recently? Did I invite her again?</li><li>What am I afraid of when I think about inviting someone first?</li></ol>\"\n  },\n  {\n   \"n\": 3,\n   \"name\": \"Your own voice\",\n   \"color\": \"Red\",\n   \"sub\": \"the strength step\",\n   \"teaser\": \"When you want to feel again: “I can”\",\n   \"note\": \"\",\n   \"body\": \"<p>This is a door you open yourself. Without your husband beside you, without a friend acting as interpreter, without your child who will “say it better”. You walk in and speak, perhaps with mistakes and a tremble in your voice, and you walk out with the matter sorted. And inside you hear: “I did it.”</p><p>The third step is about strength, courage and the right to a voice. Here a person straightens up and says: “I want”, “I can”, “no, you cannot treat me like that”. A strong voice is not about volume or scenes. It is a calm “no” without excuses and the confidence that you will manage, even if it gets awkward.</p><p>A foreign language takes away not your words but your adulthood. A woman who was asked for advice at home, who made decisions and led the way, suddenly becomes the one “who didn’t understand”. People speak to her slowly and loudly, as if to a child, and others make simple decisions for her. And every time she keeps quiet, a small pebble settles inside: “I can’t.” The pebbles keep piling up. At home, too, her voice grows quieter: “the money isn’t mine, so I have no right to ask for anything”.</p><blockquote><p>“I write a message even though calling would be quicker — just so I don’t have to speak.” “I ask my husband to book my doctor’s appointments.” “I was overcharged and said nothing, and then spent the whole evening replaying what I should have said.” “I get angry at the children — at those who won’t answer back.”</p></blockquote><p>When this step is solid, you make the calls, book appointments, ask questions and push back yourself. At home you say what you need, and you are heard. Awkwardness happens, but it no longer stops you.</p><p>The gift of the red step is the feeling “I exist”. The courage to begin, the energy to take risks, the strength to protect what is yours and who is yours. Without it there will be no job, no business of your own and no respect: neither from others nor for yourself. The catch is that strength is easily lost in both directions. You can overdo it: harshness, quarrels, “I’ll show them all”, constant defensiveness that burns you out. Or you can hide it completely: a smile and “it’s nothing” on the outside, and suppressed anger on the inside.</p><p>Your voice comes back in small steps. One action a day in the foreign language: saying hello, asking the price, making a call. One phrase that gives you back your adulthood: not “sorry, my German is bad” but “please speak more slowly”. And an “I did it” column where you write down every victory. In three weeks there will be twenty-one pieces of evidence against “I can’t”. And when your strength returns, you will want to understand how everything works here.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Which of my tasks are others doing for me right now? Which one do I want to take back first?</li><li>When did I last stay silent even though I wanted to speak? What would I say now?</li><li>What do I need at home — and do I say it out loud?</li><li>Who am I angry at “in the wrong direction”?</li><li>What small victory did I win this week?</li></ol>\"\n  },\n  {\n   \"n\": 4,\n   \"name\": \"Map and keys\",\n   \"color\": \"Blue\",\n   \"sub\": \"the order step\",\n   \"teaser\": \"When every letter in the letterbox makes your heart beat faster\",\n   \"note\": \"\",\n   \"body\": \"<p>You are in a large, unfamiliar building. Lots of doors, each with a sign in a foreign language, and behind one of them is what you need. Now imagine you are holding a map of this building and a bunch of labelled keys. You are still in an unfamiliar place, but you are no longer afraid.</p><p>The fourth step is about order, rules and reliability. It matters to a person to understand how the world around them works: who is responsible for what, what is right, what is customary, where to go with a question. Order on the outside brings calm on the inside.</p><p>There are rules here, and plenty of them. But nobody explains them: it is assumed that you grew up here and absorbed them with your mother’s milk. A local does not even know that they know it, and when asked “so how does this work?” they shrug: “well, usually…”. And a mistake can be costly: a fine, a refusal, a missed deadline. Unwritten rules are even trickier than written ones. How to greet the neighbours, whether you can do laundry on a Sunday, what to bring when you are invited round.</p><blockquote><p>“The letter from the municipality has been lying unopened for two days.” “I don’t know where to go: taxes, insurance, school, my diploma.” “Twenty chats, twenty different pieces of advice.” “I found out about the missed deadline when it was already too late.”</p></blockquote><p>When this step is solid, a letter in the letterbox stays just a letter. You know where to go with a question, your papers are sorted into folders, your deadlines are under control. You understand how things are done here and are hardly afraid of making mistakes.</p><p>The gift of the blue step is calm and an anchor. The chaos of a new country turns into a system you can live in. You become someone who has everything under control, and people start coming to you for advice. The catch is that order can turn to stone. Rules become more important than living people, including yourself. Fear of mistakes paralyses you: better to do nothing than to do it wrong. And the world splits into “right” and “wrong”, and into one of those columns fall sometimes them, sometimes us.</p><p>To climb higher, you do not need to know everything. You need to get organised in a single evening. One page on the fridge about what to do with any letter. A few folders. Three piles: urgent, can wait, not mine. And one reliable guide instead of twenty chats. When the rules become clear, a new question will arise inside: “So where is my place here? What will I do with myself?”</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Which letter or task am I putting off because I’m scared? What’s the worst that could happen — and what would I do then?</li><li>Who is my main source of answers? Can I trust them?</li><li>Which local rules seem strange to me? And if I understood why they exist — would it get easier?</li><li>Where does the fear of making a mistake stop me from starting?</li><li>What in my paperwork could I sort out in one evening?</li></ol>\"\n  },\n  {\n   \"n\": 5,\n   \"name\": \"Your own workshop\",\n   \"color\": \"Orange\",\n   \"sub\": \"the work step\",\n   \"teaser\": \"When everything inside you tightens at the question “What do you do?”\",\n   \"note\": \"\",\n   \"body\": \"<p>You have your own workshop. Maybe a small one, maybe for now just a corner of the kitchen. Your tools are in it: everything you know and can do. You make something, someone needs it, and they pay for it. And when people ask you “what do you do?”, you happily open the door and show them.</p><p>The fifth step is about work, growth and your own price. Here you want to make something of yourself: find an occupation that suits your strength and your heart, grow, earn and be recognised for what you can do. Rules here are no longer walls but tools: how to do things better, how to arrange them your own way.</p><p>A move resets three kinds of savings to zero at once, savings you built up over years. Professional: your diploma isn’t recognised here. Reputational: nobody knows what you’re worth. And human: there’s no one to vouch for you. At home all this took twenty years to build, and here it vanished in a single day. You’re offered jobs below your previous level or none at all. “You don’t have local experience”, but where is it supposed to come from? You have no money of your own, and every purchase for yourself turns into a little inner haggle.</p><blockquote><p>“My CVs go out into silence, and my diploma sits in a drawer”. “I have lots of ideas, but no idea where to start”. “I look at those who’ve settled in and feel worse”. “It feels like I’m nobody here”.</p></blockquote><p>When this step is solid, you have something of your own to do: a job, your own business or a project. There is money you’ve earned yourself, even if it’s not much. And you know your worth, regardless of your job title.</p><p>The gift of the orange step is the taste of growth and freedom. “I can choose who to be”. Skills turn into work, work into money, and money into a voice and independence. The catch is that you may start valuing yourself only for results: no position means no me. The race begins, along with endless comparison, because someone has always settled in better. And in this race it’s easy to forget about sleep from the first step and your people from the second.</p><p>The way up doesn’t start with blindly searching for vacancies, but with looking into your workshop. What can I do, not according to my diploma but according to life? Which of it is needed here? Talk to five people instead of guessing. Choose one path that suits your strength: a job, a small business of your own or a trial project. And earn your first franc for what you can do: it matters more than the amount. When your own business appears, a new question will come: “And what is it all for?”</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>What have people most often said “thank you” to me for? Which of it is needed here?</li><li>Which path is within my strength right now — a job, a small business of my own or a trial project?</li><li>What do I answer to “what do you do?” — and what do I want to answer a year from now?</li><li>What does my own money mean to me — an amount or freedom?</li><li>Who do I compare myself with? Does it help me — or only hurt?</li></ol>\"\n  },\n  {\n   \"n\": 6,\n   \"name\": \"A garden for others\",\n   \"color\": \"Green\",\n   \"sub\": \"the contribution step\",\n   \"teaser\": \"When you already have something of your own and want to share\",\n   \"note\": \"\",\n   \"body\": \"<p>You’ve grown your own garden and suddenly notice that you want to share. Treat the neighbours to apples, give a seedling to a woman who has just arrived, invite people to sit in the shade. The garden is no longer only yours, it warms others too. But a good gardener knows: if you give away all the water, the garden will dry up.</p><p>The sixth step is about people, warmth and meaning. When you already have something of your own, you want what you’ve made to matter to someone beyond your family: to share your experience, do something together, be part of a community. What matters here is not “who’s first” but “that everyone is well”.</p><p>Someone who has walked a hard road understands newcomers very well. You want to help, give tips, give a hug, and that’s wonderful. But a trap is hiding here. Helping others is the noblest way of not dealing with your own life. It gives warmth and a sense of being needed and can go on for years, while your own question “so where am I going?” stays unanswered. If the garden grows where your own workshop should have stood, it isn’t a contribution but an escape.</p><blockquote><p>“I help everyone, and for free, and there’s no strength left for my own things”. “I look after every newcomer — I remember what it was like for me”. “Taking money feels awkward: it’s just help, after all”. “The business is there, everything works, but there’s no joy”.</p></blockquote><p>When this step is solid, there is something you do not only for yourself, and you understand what for. You give by choice without being drained, and your contribution is seen and valued.</p><p>The gift of the green step is the ability to listen, empathise and bring people together. This is where those come from who welcome newcomers, build communities and make a foreign country a little warmer. The catch is rescuing everyone and ending up empty-handed. Fearing conflict so much that every conversation turns into an endless “let’s hear everyone out”. Living other people’s lives instead of your own.</p><p>To climb higher, it’s worth honestly counting who you give to, how much, and what you get in return. Choosing who you want to give to: those who come after you, colleagues in your field, or what will remain after you. Learning to say “no” and naming a first price for what you do well. When giving rests on your own anchor, you want to see your whole life at once.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>What do I do here not only for myself and my family?</li><li>How many hours a month do I give to others? And how many — to myself?</li><li>Who exactly do I want to be useful to — and in what form?</li><li>Where do I say “yes” when I want to say “no”?</li><li>If my help for others disappeared — what would be left that’s mine?</li></ol>\"\n  },\n  {\n   \"n\": 7,\n   \"name\": \"The view from the hill\",\n   \"color\": \"Yellow\",\n   \"sub\": \"the whole-life step\",\n   \"teaser\": \"When you’ve lived here a long time but still feel you’re living out of a suitcase\",\n   \"note\": \"\",\n   \"body\": \"<p>You walked through the valley for a long time, along paths and over little bridges, and now you’ve climbed a hill. From here you can see everything at once: where you came from, where you are now, where the roads lead. Your former life and your present one turn out to be not two different shores but one valley. And you choose for yourself which path to take next.</p><p>The seventh step is about seeing life as a whole. Here a person stops living by other people’s scripts, “the way it should be” and “like everyone else”, and puts together their own: what matters to me, why, how. They see that every step has its own truth, and take from each what they need.</p><p>The decision to leave is almost impossible to close once and for all. It resurfaces with every difficulty: “if we hadn’t left, this wouldn’t have happened”. And as long as this question is open, life stays a draft. And a draft isn’t worth taking care of: you can skip buying furniture, not hang pictures, not learn the language seriously. “Once we go back”, “once I’ve learnt the language”, “once the children have grown up”, and the years go by.</p><blockquote><p>“I’ve been here for many years and I’m still living out of suitcases”. “In every crisis I wonder again whether we did the right thing”. “‘There’ and ‘here’ just won’t come together as one”. “I look back and see years on pause”.</p></blockquote><p>When this step is solid, your life stops being a waiting room. You’ve made peace with the decision to leave. From “there” you’ve taken what is dear to you, from “here” what has become yours. You know how you want to live the coming years, and that makes you glad.</p><p>The gift of the yellow step is freedom and a grown-up view. You no longer need someone to tell you what’s right. The catch is understanding everything and choosing nothing, when “there’s no single right answer” becomes a convenient excuse not to decide. Or watching your own life from the outside, like a spectator. Or climbing the hill by skipping the lower steps: a wide view, but behind you an empty fridge and not a single person of your own.</p><p>To climb higher, close the question of the move on paper: what I gained, what I lost, what I would pay for again and what not. Finish the story of “if we hadn’t left”, honestly, year by year: as long as it isn’t finished, it comes back on every hard day. And do one thing you’ve been putting off until the return: hang a picture, buy beautiful crockery. When your own life is put together, your gaze rises above it by itself.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>What am I putting off “until we go back” or “until better times”?</li><li>If we hadn’t left — what would my life be like in ten years? Honestly, all the way to the end.</li><li>What from “there” do I want to take with me forever? What from “here” has already become mine?</li><li>If life were ending tomorrow — what would I regret?</li><li>What single phrase would I use to describe each of the next three years?</li></ol>\"\n  },\n  {\n   \"n\": 8,\n   \"name\": \"The sky above home\",\n   \"color\": \"Turquoise\",\n   \"sub\": \"the “bigger than me” step\",\n   \"teaser\": \"When “here” and “there” merge into one life\",\n   \"note\": \"This isn’t a step to be fixed, but a horizon you grow into. In the test it only opens if all seven steps beneath you are solid.\",\n   \"body\": \"<p>The house is built. You go out onto the roof and see the sky, the same one over every country. The river below flows across borders without asking permission. And suddenly you realise: you are not “from here” or “from there”, you simply live. And the house you’ve built will one day become a refuge for those who come after.</p><p>The eighth step is about the whole and about connections. A person feels part of something bigger than their own life: people, nature, work that will outlive them. They don’t need to prove anything or compete with anyone. Caring for yourself and caring for the world become one and the same here.</p><p>After a move it sounds like this: “I no longer live ‘in emigration’, I simply live”. The question “where is my real life” has disappeared by itself. You are not a representative of your country, nor a guest in someone else’s. Beneath you are solid steps: there is sleep, your people, your own business and what you give. Inside it is quiet. And there is something you do for those who will come after you.</p><blockquote><p>“I no longer divide my life into ‘here’ and ‘there’”. “I want something to remain after me”. “I’m interested in those who come after me”.</p></blockquote><p>It isn’t always easy here either. You’ve outgrown your old circle but haven’t found a new one yet, and there’s no one to talk to on your level. Old goals no longer call you, and new ones haven’t been named yet. And you want what you’ve created not to end with you.</p><p>The gift of this step is wisdom, quiet and a generosity that doesn’t drain you. This is where mentors, hosts of gatherings and authors come from, those who open doors for others.</p><p>And one important warning. The phrase “I’m a citizen of the world, I’m at home everywhere” can be true, or it can be a painkiller. If the ground beneath your feet is shaking, if there is no strength and no sleep, no people of your own, this beautiful phrase helps you not feel that, for now, home is nowhere. The check is simple: a real sky above home has the home itself beneath it. If the lower steps are solid, “I’m at home everywhere” is the truth. If not, it’s time to go down and strengthen the foundation. That’s nothing to be ashamed of. It’s honest.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Do I still divide my life into “here” and “there”?</li><li>What do I do for those who will come after me?</li><li>Who can I talk to about what matters most — on my level?</li><li>What do I want to leave behind?</li><li>Are the lower steps beneath me solid — sleep, my people, my own business?</li></ol>\"\n  }\n ],\n \"end\": \"<blockquote><p>You’ve walked through all eight steps, from the ground under your feet to the sky above home. Surely at one of them you stopped and thought: “That’s about me”. Or maybe at two at once.</p><p>Recognising yourself is the first step. The second is checking which steps beneath you are solid and which one creaks. The test takes about twenty minutes and will show where you in particular should start.</p></blockquote>\",\n \"sources\": \"<p>Clare W. Graves. <i>The Never Ending Quest.</i> ECLET Publishing, 2005 — Clare Graves’s main work on how people understand “the good life”.</p><p>Don E. Beck, Christopher C. Cowan. <i>Spiral Dynamics: Mastering Values, Leadership and Change.</i> Blackwell, 1996 — the book in which the levels were given colours and change is described as transitions between states.</p><p>Spiral Dynamics: states and conditions for change — spiral-dynamics.com/faq_change.htm</p><p>Jørgen Carling, Silje Vatne Pettersen. <i>Return Migration Intentions in the Integration–Transnationalism Matrix.</i> International Migration, 2014 — on how the decision to stay or return depends on how strong the ties are here and there.</p><p>The guide describes the steps in simple words and applies them to life after a move. It is the author’s own adaptation of the model for self-discovery, not a scientific diagnosis.</p>\"\n};\n", "const capLead = (n, s) => n ? n + ', ' + s : s.charAt(0).toUpperCase() + s.slice(1);\nconst capJoin = (p, s) => p ? p + ' ' + s : s.charAt(0).toUpperCase() + s.slice(1);\n/* =====================================================================\n   «Ступени устойчивости» — путеводитель + тест «7 ступеней устойчивости».\n   Тексты: «Вход 1 — Путеводитель по уровням.md» (→ guide.js) и\n           «Вход 2 — Тест 7 ступеней устойчивости.md» (вопросы и разбор ниже).\n   ===================================================================== */\n\n/* ---------- ступени: палитра «Акварель с контуром · свежая» ---------- */\nconst LV = [\n  { name: 'Ground under your feet', color: 'Beige',    short: 'body',           fill: '#E2DCD0', line: '#8E8470', focus: 'regain your strength and the ground under your feet' },\n  { name: 'The hearth and your people',      color: 'Purple', short: '“we”',           fill: '#C4BDEA', line: '#6A5FB8', focus: 'find your people in the new country' },\n  { name: 'Your own voice',       color: 'Red',    short: 'strength',           fill: '#EEA9B3', line: '#C25468', focus: 'get your voice and confidence back' },\n  { name: 'Map and keys',    color: 'Blue',      short: 'order',        fill: '#A6C4F0', line: '#3F6FBF', focus: 'calmly figure out how everything works here' },\n  { name: 'Your own workshop',  color: 'Orange',  short: 'work',           fill: '#F2C6A8', line: '#C97E52', focus: 'find your own business and your own price' },\n  { name: 'A garden for others',   color: 'Green',    short: 'contribution',          fill: '#B0DCC0', line: '#4E9A70', focus: 'give from abundance, not until you’re drained' },\n  { name: 'The view from the hill',      color: 'Yellow',     short: 'whole life',    fill: '#EEE29E', line: '#A99A2E', focus: 'stop living on pause and put your whole life together' },\n  { name: 'The sky above home',   color: 'Turquoise',  short: '“bigger than me”',  fill: '#9ADDE0', line: '#2894A0', focus: 'understand what you want to leave behind' }\n];\nconst mix = (a, b, t) => '#' + [1, 3, 5].map(i => Math.round(parseInt(a.substr(i, 2), 16) * (1 - t) + parseInt(b.substr(i, 2), 16) * t).toString(16).padStart(2, '0')).join('');\nLV.forEach(l => l.soft = mix(l.fill, '#FFFFFF', .55));\n\nconst GR = ['I feel', 'I do', 'Around me', 'I think'];\nconst GR_SUB = ['what’s inside me', 'what I actually do', 'what’s out there', 'what I believe in'];\n\n/* g: 0 чувствую · 1 делаю · 2 вокруг меня · 3 думаю; r: обратная фраза (4 − ответ) */\nconst ITEMS = [\n  [ [0,'I wake up in the morning full of energy.'], [0,'By evening I’m so tired that all I want is quiet and for no one to bother me.',1],\n    [1,'I get enough sleep and go to bed at roughly the same time.'], [1,'I eat on the run or eat to cope with tiredness in the evenings.',1],\n    [2,'I have a place where I can close the door and breathe out.'], [2,'I have a home and money for the essentials, and I’m not afraid for them.'],\n    [3,'I know what the coming months will bring — at least roughly.'], [3,'I don’t allow myself to rest until everything is done.',1] ],\n  [ [0,'Here I sometimes feel truly warm with people.'], [0,'I feel lonely even when there are people around.',1],\n    [1,'In the past month I’ve met someone in person — not for anything practical, just because.'], [1,'I invite people myself: for coffee, to my home, for a walk.'],\n    [2,'There is someone I can call when I’m feeling bad.'], [2,'There is a place or a group where people expect me and recognise me.'],\n    [3,'Our traditions and holidays live on in my home, here too.'], [3,'I feel like a stranger both here and back home.',1] ],\n  [ [0,'I feel grown-up and confident when I handle my affairs here.'], [0,'I feel ashamed and awkward when I have to speak a foreign language.',1],\n    [1,'I book doctor’s appointments myself and sort out everyday matters by phone.'], [1,'Simple matters are handled for me by my husband, a friend or my child.',1],\n    [2,'At home I say what I need — and I’m heard.'], [2,'People talk to me as an equal, not slowly and loudly.'],\n    [3,'If I’ve been treated unfairly, I say so out loud.'], [3,'I have the right to say no without justifying myself.'] ],\n  [ [0,'A letter in the letterbox doesn’t frighten me.'], [0,'I’m afraid of doing something wrong and “getting caught out” — with a fine, a refusal, a missed deadline.',1],\n    [1,'My papers are sorted, and I know where everything is.'], [1,'I put confusing letters aside and don’t open them straight away.',1],\n    [2,'I have a reliable source of answers — a person or a service, not twenty chat groups.'], [2,'I know where to go with a question about insurance, taxes, school or housing.'],\n    [3,'I understand how people are expected to behave here.'], [3,'I understand why the rules here exist, even if I don’t agree with all of them.'] ],\n  [ [0,'I answer calmly when people ask what I do.'], [0,'When I look at those who have settled in, I feel worse.',1],\n    [1,'I have something of my own to do — a job, a business or a project I consider mine.'], [1,'I’m taking steps towards my work goal — learning, searching, trying things out.'],\n    [2,'I have money I’ve earned myself — even if it’s not much.'], [2,'My experience and skills are needed and valued by someone here.'],\n    [3,'I know my worth, and it doesn’t depend on my job title.'], [3,'I feel like I’m “nobody” here.',1] ],\n  [ [0,'What I do brings me joy, not just results.'], [0,'After helping others I often feel drained.',1],\n    [1,'There is something I do here not only for myself and my family.'], [1,'I say “no” when people ask too much.'],\n    [2,'There is a circle or a project where I’m a co-creator, not a guest.'], [2,'My contribution is noticed and valued, rather than “well, you only gave a bit of advice”.'],\n    [3,'I understand why I do what I do.'], [3,'Taking money for what I do well feels uncomfortable — “it’s just help, after all”.',1] ],\n  [ [0,'I feel I’m living my life, not waiting for the real one to begin.'], [0,'It’s as if there are two halves in me — “there” and “here” — and they don’t fit together.',1],\n    [1,'I do things I used to put off “until better times” or “until we go back”.'], [1,'I live as if out of a suitcase: I never fully settle in, “in case we leave”.',1],\n    [2,'My home here feels like mine, not temporary.'], [2,'In my life there is room both for what I brought “from there” and for what I found here.'],\n    [3,'I’ve made peace with the decision to leave — I no longer replay it inside me.'], [3,'I can picture how I want to live the next few years — and it makes me glad.'] ]\n];\nconst SKY = [ [0,'Inside I feel calm: I don’t need to prove anything to anyone.'], [1,'I do something for those who will come after me.'],\n  [2,'There are people near me I talk to about what matters most.'], [3,'I no longer divide my life into “here” and “there”.'],\n  [3,'I feel part of something bigger than my own life.'], [3,'My old goals no longer call to me, and I haven’t found new ones yet.',1] ];\n\n/* ситуации: [ступень 0–7, текст]; каждая ступень встречается ровно 6 раз */\nconst SITS = [\n  ['It’s Friday evening and the week has been hard. What do you want most?', [[0,'An early night, quiet, seeing no one — just recover.'],[1,'Invite my people over, cook lots, talk in my own language.'],[3,'Sort out the pile of paperwork and plan next week — then I can let go.'],[5,'Meet a friend and have a heart-to-heart about what I really feel.']]],\n  ['Your neighbours invite you to an apéro in the courtyard.', [[1,'I’ll go if someone from my own circle goes too — on my own I feel uncomfortable.'],[2,'I’ll go and start talking myself, even with mistakes — no more hiding.'],[4,'I’ll go: it’s a chance to meet useful people.'],[6,'I’ll go out of curiosity — to see how they live and take what resonates with me.']]],\n  ['At the reception desk, they talk to you slowly, loudly and condescendingly.', [[2,'I’ll say it straight: “Speak normally, I understand.” I won’t allow it.'],[3,'I’ll calmly ask for it in writing and check what the proper procedure is.'],[5,'I’ll try to understand the person — maybe they’re having a hard day; I don’t want a quarrel.'],[7,'I’ll note it to myself and let it go: it’s not about me, just an episode.']]],\n  ['You’re offered a job below your qualifications.', [[0,'I’ll accept if it means a steady income and peace of mind: this is no time for ambition.'],[3,'First I’ll look into the terms: contract, insurance, probation period.'],[4,'I’ll take it as a stepping stone — but with a plan for how to move up within a year.'],[6,'I’ll think about how it fits into my life as a whole, not just my wallet.']]],\n  ['An acquaintance has recently moved here and asks you to help her settle in.', [[1,'I’ll bring her into our circle — so she has her own people right away.'],[4,'I’ll give her a clear plan: what to do in the first month and where to go.'],[5,'I’ll be there, listen, support her — I know from experience how hard it is.'],[7,'I’ll help — and think about how this experience could be useful to those who arrive after us.']]],\n  ['You and your husband can’t agree on how to spend your holiday and what to spend the money on.', [[0,'The main thing for me is to rest and catch up on sleep; the rest doesn’t matter.'],[2,'I’ll say what I want — I’ve gone along with others long enough.'],[5,'What matters is that everyone is happy and no one ends up hurt.'],[6,'We’ll look for an option that brings different things together — there’s no single right answer.']]],\n  ['You remember how it was “there”, back home.', [[1,'I miss my people, the holidays and traditions — I want to keep them alive for the children.'],[3,'I try not to compare: there are different rules here, and you have to live by them.'],[6,'I see both lives from the outside: each has something valuable, and I choose what to take.'],[7,'“There” and “here” are no longer separate — it’s one life, mine.']]],\n  ['Picture yourself five years from now. What matters most to you?', [[0,'That life is calm, my health is fine and I’m not afraid of tomorrow.'],[2,'That I don’t depend on anyone and make my own decisions.'],[4,'That I’ve made it in my work and am paid my price.'],[7,'That something remains after me — for those who come after.']]],\n  ['Someone close to you who moved with you says: “I want to go home.”', [[0,'First let them rest and get some sleep — when you’re tired, everything seems worse.'],[1,'We’ll find them their own people here: a group, a club, friends.'],[4,'We’ll set a goal worth staying for, and the first step towards it.'],[6,'We’ll talk about how you don’t have to choose one country — you can hold on to both.']]],\n  ['An argument about politics flares up in a Russian-speaking chat.', [[2,'I’ll state my position plainly — I won’t stay silent.'],[3,'I’ll remind everyone of the chat rules: this isn’t the place for it.'],[5,'I’ll try to make sure everyone hears each other and no one leaves hurt.'],[7,'I see that behind the argument everyone shares the same pain — a lost home — and I don’t get drawn in.']]],\n  ['You have a whole free day — just for yourself.', [[0,'Sleep in, a bath, no rushing anywhere.'],[2,'Do something I haven’t dared to do for a long time — even if it’s a little scary.'],[5,'Spend it with people: a get-together, volunteering, a shared project.'],[6,'Spend it the way I want, with no “shoulds” — and think about where I’m heading.']]],\n  ['You’ve been asked to talk about your country — at your child’s school or at work.', [[1,'I’ll talk about our holidays and cook one of our dishes.'],[3,'I’ll prepare thoroughly, to a plan, so everything is accurate.'],[4,'It’s a chance to show what I can do — I’ll make it vivid.'],[7,'I’ll show that more unites us than divides us.']]]\n];\nconst SITS_PER_SCREEN = 3;\nconst GOAL_HINT = ['get enough sleep and wake up with energy', 'have at least one person close to me nearby', 'make calls, book appointments and say “no” myself',\n  'open letters calmly and know where to go', 'find my own work and earn my first money from it', 'help with joy, not by forcing myself', 'stop living out of a suitcase'];\n\nconst STAY = ['Yes, I have decided to stay', 'Probably yes, but sometimes I have doubts', 'I don’t know yet, I’m thinking about it', 'Probably not: I want to go back or move on', 'It is not only my decision'];\nconst STAY_SHORT = ['decided to stay', 'probably staying, but has doubts', 'not decided yet', 'thinking of going back or moving on', 'the decision doesn’t depend only on her'];\nconst STAY_TXT = [\n  ['The decision is made', 'You have decided to stay. This is one of the strongest anchors in a new country: your energy no longer drains away into the question “maybe not here?” but goes into settling in. Even if some steps still creak, you already have the main thing — a direction.'],\n  ['Probably yes, but the doubt comes back', 'You’re mostly here, but doubt sometimes comes back. This is a very common state. It’s worth noticing when exactly it comes: often it’s not about the country but about the step that is creaking at that moment. Tiredness, loneliness, a setback at work sound like “maybe we shouldn’t have left”. Strengthen the step and the doubt will grow quieter.'],\n  ['You have not decided yet', 'You have not yet decided whether to stay, and that’s honest. But life “in between” comes at a high price: it’s hard to invest in the language, people and your own work when you don’t know how long you’ll be here. Migration researchers note that the decision to stay or leave doesn’t come from a single reason but from how strong your ties are here and there. You don’t have to decide today. But you can decide how to live while you’re deciding: set yourself a deadline and live these months for real, not out of a suitcase.'],\n  ['You are thinking of going back or moving on', 'You’re thinking of going back or moving on, and that’s a normal choice. But even a temporary life is still a life. Sleep, your people, your voice and order matter even if you’re here for just a year. And what you build now — experience, language, confidence — you’ll take with you.'],\n  ['The decision does not depend on you alone', 'Whether to stay or leave doesn’t depend only on you: on your husband’s job, on documents, on circumstances. It’s one of the hardest kinds of uncertainty, because others set the horizon. What helps here is telling apart what doesn’t depend on me, what I can discuss and influence, and what is mine right now, whatever the decision.']\n];\nconst HOW = ['came with family / husband', 'for work — my own or my husband’s', 'got married', 'left because of war or danger', 'other'];\nconst YEARS = ['less than a year', '1–3 years', '3–7 years', 'more than 7 years'];\nconst LABELS = ['not me at all', 'mostly not', 'partly', 'mostly yes', 'that’s me exactly'];\nconst CHEER = ['Answer for the last 4 weeks. Don’t think too long: your first response is usually the most honest.',\n  'One step behind you. Breathe — let’s keep going.', 'You’re doing well. A little further up.',\n  'You’re halfway up the stairs. Time for a sip of tea.', 'Answer as it is — no one is checking here.',\n  'Almost at the top. Just a little more.', 'The last step of this part.'];\nconst STATUS = ['start here', 'creaking', 'solid'];\nconst STEP_LINE = [\n  ['Your energy is low, and sleep and rest don’t restore it yet. Your body needs care first of all.', 'Your energy is just about enough: one hard week and you’re running on nerves again.', 'You get enough sleep, you have a place of your own and a rough plan for the coming months.'],\n  ['You don’t yet have enough of your own people around, and that takes a lot of warmth.', 'There are people, but more through circumstance; warm get-togethers are rare.', 'You have your people: someone to call and places where people are waiting for you.'],\n  ['Many things are still decided for you, and your voice is quieter than you’d like.', 'You manage on your own, but it’s a strain, and you still avoid difficult conversations.', 'You sort out your own affairs and can say “no”.'],\n  ['Rules and paperwork still scare you, and the fear of making a mistake drains your energy.', 'On the whole it’s clear, but letters still make you tense.', 'You understand how things work here, and a letter in the letterbox doesn’t scare you.'],\n  ['You don’t yet have your own work or your own price here, and that hurts your self-respect.', 'You have something to do, but it’s not quite your own, or it’s your own but without money or recognition.', 'You have your own business and know your worth.'],\n  ['You give more than you keep for yourself, or haven’t yet found who needs your experience.', 'You help and share, but not always by choice.', 'You give from abundance and understand what it’s for.'],\n  ['Life still feels like a draft: “there” and “here” don’t fit together.', 'You’re mostly here, but sometimes you’re “living out of a suitcase” again.', 'This is your whole life, and you know where you’re going.']\n];\nconst STATUS_LINE = ['This step is asking for care.', 'It holds, but it creaks. In a hard week it may let you down.', 'This step holds. You can lean on it.'];\n\n/* ---------- тексты разбора по ступеням ---------- */\nconst RES = [\n  { main: ['Right now the main work isn’t the language, a career or big plans. Right now what matters most is you, your body, your sleep, your strength.',\n           'Remember that feeling when you step ashore after a long voyage and the ground is still rocking? Moving abroad is that kind of voyage. All the habits that ran by themselves at home had to be switched on by hand, and your mind stands guard all day like a watchman. The tiredness you feel isn’t laziness or weakness. It’s the honest bill for the huge work you do every day that nobody sees.',\n           'While the ground under your feet is still rocking, it’s hard to build higher. So let’s start here — gently and without heroics.'],\n    gr: ['On the outside everything is there — a roof, money, insurance — but inside there’s no strength. This happens when the danger is already behind you but your body doesn’t believe it yet. It needs time and a little care to breathe out.',\n         'You know perfectly well that you need to sleep and eat properly — but it isn’t working. What helps here isn’t one more piece of advice, but a simple rhythm: the same time, the same small ritual.',\n         'You lack outside support — a corner of your own, a clear future, money without worry. Start with what can be done in one evening: make yourself a place where you can close the door.',\n         'You don’t let yourself rest until everything is done. But rest isn’t a reward for completing the plan. It’s the fuel without which the plan won’t move.'],\n    step: 'Three evenings in a row, go to bed an hour earlier. In the morning, stand in the daylight for ten minutes — by the window or outside. And choose one corner at home that will be yours alone.',\n    product: '“Two weeks to get the ground back under your feet”', productText: 'A self-guided written mini-programme: 10 minutes a day, no meetings — right now you might not even have the energy for them.' },\n  { main: ['You miss your people — those you feel warm with, with whom you don’t have to explain yourself, and whom you can call late in the evening.',\n           'At home your circle came together by itself, over years: the courtyard, school, work. Here nobody handed it down to you. It has to be built from scratch — as an adult, in a foreign language, when time is short and the first step is somehow so hard. Loneliness after moving isn’t a sign that something is wrong with you. It’s the most common pain of those who have left.',\n           'The good news: a hearth isn’t lit as a bonfire straight away, but from a single spark. Let’s start with one person.'],\n    gr: ['There are people around you, but no warmth. So what you need isn’t a new crowd, but a little more depth with those already close.',\n         'You wait to be invited but don’t invite anyone yourself. Friendship as an adult rests not on courage but on repetition: the same people, the same time.',\n         'For now there isn’t a single person or place where you belong. One person is already enough for the fire to catch.',\n         'You feel like an outsider both here and there. The traditions you brought with you are the first bridge: they are where something of your own begins in the new place too.'],\n    step: 'Be the first to message someone you recently enjoyed spending time with, and invite them for a coffee. Not ten people — one. And if they say yes, invite them a second time too: an acquaintance becomes an acquaintance from the second meeting.',\n    product: '“One person of your own”', productText: 'A 6-week written programme: one letter and one small action a week. Not about courage, but about a schedule.' },\n  { main: ['Your step right now is about voice and strength.',\n           'A foreign language doesn’t take away your words — it takes away your adulthood. A woman whose advice was sought at home suddenly becomes the one “who didn’t understand”. People speak to her slowly and loudly, and decide simple things for her. And every time you stayed silent, a little pebble settles inside: “I can’t”.',\n           'Your voice comes back not through a dictionary but through actions — small ones, every day. Every door you’ve opened yourself removes one pebble.'],\n    gr: ['You can do things, but every time it feels shameful and awkward. Shame goes away not when confidence appears, but when you’ve built up many times when you did it — in spite of the shame.',\n         'Other people do lots of simple things for you. Take one back — the smallest. That will be your first door.',\n         'For now people don’t take you into account — at home or in offices. Start with one phrase that gives you back your adulthood: “Please speak more slowly”.',\n         'You doubt you have the right to ask for what’s yours. You do. You just don’t fully believe it yet.'],\n    step: 'Every day, one small action in the foreign language: say hello, ask a price, make a phone call. And each time, write in a notebook: “I did it”.',\n    product: '“A Grown Woman’s Phrasebook” + 21 days', productText: 'Ready-made phrases for the doctor, phone calls and difficult conversations, plus 21 small actions, one a day.' },\n  { main: ['It’s as if you’re in a big building with dozens of doors, each with a sign in a foreign language. There are rules here, but nobody explains them: the locals grew up with them and don’t even know they know them.',\n           'Your fear of making mistakes isn’t anxiety or oversensitivity. It’s a reasonable response to a system where mistakes are costly.',\n           'You don’t need to know everything. You need a map and a bunch of keys — a little order and one reliable guide.'],\n    gr: ['You know a lot, but the fear of making a mistake is louder than your knowledge. A simple rule helps: five questions for any letter, and it stops being frightening.',\n         'Paperwork gets put off, deadlines slip away. What you need here isn’t willpower, but a system you can set up in one evening.',\n         'There’s no reliable source of answers. One guide is better than twenty chats.',\n         'The rules here still seem strange because it isn’t clear what they’re for. Once you understand the “why”, the rules stop weighing on you.'],\n    step: 'Sort your post into three piles: urgent, can wait, not mine. Just that — and breathing will already get easier.',\n    product: '“The folder that answers for you”', productText: 'A reference guide and a filing system you can set up in one evening: what to do with any letter, where to go with a question, the unwritten rules.' },\n  { main: ['Your step right now is about your own business and your own price.',\n           'The move wiped out, in one go, three kinds of savings you had built up over years: professional — your diploma isn’t recognised here, reputational — nobody knows what you’re worth, and human — there’s no one to vouch for you. This didn’t happen because you did something wrong. The move did this.',\n           'But the tools from your workshop haven’t gone anywhere. Let’s start not with job hunting, but with opening the workshop door and seeing what’s already inside.'],\n    gr: ['You have work, but inside you still hear “I’m nobody”. Your self-respect shouldn’t have to wait for a job title.',\n         'There are ideas, but no steps. You need one track — one that fits your strength, not your dream.',\n         'You don’t yet have money of your own or recognition. The first franc you earn matters more than the amount: it says “I can”.',\n         'You measure yourself against other people’s successes. But comparing yourself with those who arrived earlier is like comparing a seedling with a tree.'],\n    step: 'Write down everything you can do — not according to your diploma, but according to life. Then tick what could be useful here.',\n    product: '“My own price”', productText: 'A 30-day written workshop: a skills bank, three tracks — a job, a small business of your own, a trial project — and the first franc you earn.' },\n  { main: ['You already have your own garden, and you want to share — to help, to give advice, to be needed. That’s wonderful.',\n           'But a good gardener knows: if you give away all the water, the garden dries up. On this step it’s very easy to give yourself away completely and not notice how empty it has become.',\n           'Let’s start with measure: whom you want to give to, how much — and what is left for you.'],\n    gr: ['After helping others, you feel empty. That means you give more than comes back to you.',\n         'It’s hard to say “no”. But “no” is also care: for yourself, and for keeping your help alive.',\n         'There’s no circle where you’re a co-creator. Look not for people to help, but for people to do things with.',\n         'It feels awkward to take money for what you do well. A price isn’t greed, it’s respect for your experience.'],\n    step: 'Count how many hours a month you give to others. And put the same number in your calendar — for yourself.',\n    product: '“Who needs my experience”', productText: 'A 14-day written programme: who needs your experience, in what form and on what terms, plus a separate part about measure.' },\n  { main: ['You are already high up — from here you can see almost the whole valley of your life. But something is stopping you from taking the last step to the top of the hill.',\n           'The decision to leave almost never closes by itself. It comes back with every difficulty: “what if we hadn’t left…”. And as long as this question stays open, life remains a draft — and a draft is easy to throw away.',\n           'It’s time to close it and start living your life for real, not in draft.'],\n    gr: ['“There” and “here” just won’t come together as one. The bridge between them is built from what you yourself choose to take from each shore.',\n         'You are still putting things off “until better times”. One postponed thing done this month will change more than years of thinking about it.',\n         'Home still feels temporary. Start with one nail in the wall — and hang something you love on it.',\n         'The decision to leave is still being replayed inside you. Write the story “if we hadn’t left” all the way to the end — honestly, year by year. Once it’s finished, it will stop coming back.'],\n    step: 'Do one thing you have been putting off “until we go back”: hang a picture, buy some beautiful dishes, sign up for something you have wanted to do for a long time.',\n    product: '“This is not a draft”', productText: 'A 21-day written programme: close the decision about your move on paper and stop living on pause. Next — “Map of a whole life”.' }\n];\nconst REFUGEE = 'Part of what you need right now — housing, documents, money — is not up to you. That really is how it is, and it is not your weakness. The municipal social services, the cantonal integration office and the Red Cross help with this — reach out to them, it is their job. Coaching does not replace them. It can walk alongside: help you get back your sleep, your rhythm, a small horizon and permission not to be strong every minute.';\nconst FIRST_YEAR = 'You have been here for less than a year. Almost everyone spends the first year on the lower steps — the ground is still swaying, as after a long voyage. This is normal, not a diagnosis.';\nconst LONG_TIME = 'You have been here for many years, yet life still seems to be on pause. If that makes you sad, know this: it is one of the most common stories. You are not alone — and it can change.';\nconst HEART = [\n  'Loudest of all right now is caring for yourself: rest, quiet, safety. Your heart is asking for a breather — and that is wise.',\n  'Loudest of all are your people, warmth and roots. Being part of a circle matters to you.',\n  'Loudest of all is your own voice: deciding for yourself, not bending, taking action.',\n  'Loudest of all is order: doing things properly, understanding the rules, being reliable.',\n  'Loudest of all is your work: growing, making something of yourself, getting what you are worth.',\n  'Loudest of all are people and the warmth between them: for everyone to be well.',\n  'Loudest of all is the view from the hill: seeing the whole and choosing what is yours.',\n  'Loudest of all is the “bigger than me”: connection with everything and care for those who will come after.'\n];\nconst TRAPS = {\n  sky:   'The phrase “I’m at home everywhere” is beautiful — and it can be true. But when there is no one to call and no strength in the morning, it sometimes helps you not to notice that there is no home anywhere yet. The sky above home is wonderful when there is a home beneath it. Let’s start with the foundation — and then these words will come true.',\n  green: 'You are generous, and helping others comes easily to you. But sometimes helping others is the noblest way of not dealing with your own question: “and where am I going?” Your own workshop first — then the garden for others will bloom too, instead of taking your last drop of water.',\n  yellow:'You see life broadly and can hold different truths at once. But the view from the hill doesn’t replace sleep, your people or your own voice. The steps under your feet first — the hill isn’t going anywhere.',\n  blue:  'You try so hard to do everything right… Could it be that the rules have become a way of not taking risks and not saying “I want” out loud? Sometimes courage matters more than precision.'\n};\n\n/* ---------- утилиты ---------- */\nconst $ = id => document.getElementById(id);\nconst sum = a => a.reduce((x, y) => x + y, 0);\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };\nconst lvName = k => `${k + 1} · ${LV[k].name}`;\n\n/* ---------- значки ступеней ---------- */\nfunction lvIcon(k, size = 24, col){   // значки — из общей библиотеки assets/icons.js\n  return ico(['earth', 'hearth', 'door', 'key', 'workshop', 'sprout', 'hill', 'sky'][k], col || LV[k].line, LV[k].fill, size);\n}\n\n/* ---------- стартовая страница: плитки, два входа, путеводитель ---------- */\n$('stTiles').innerHTML = LV.map((l, k) => `<div class=\"st-tile${k === 7 ? ' sky' : ''}\" style=\"--f:${l.fill};--l:${l.line};--s:${l.soft}\">\n  ${lvIcon(k, 26)}<b>${l.name}</b><span>${k + 1} · ${l.color.toLowerCase()} · ${l.short}</span></div>`).join('');\n\n$('stAB').innerHTML = abHtml();\n\nfunction renderGuide(){\n  const levels = GUIDE.levels.map((g, k) => {\n    const l = LV[k];\n    return `<details class=\"st-lv${k === 7 ? ' sky' : ''}\" id=\"guide-${k + 1}\" style=\"--f:${l.fill};--l:${l.line};--s:${l.soft}\">\n      <summary><span class=\"st-ico\">${lvIcon(k, 30)}</span><span class=\"st-sum\"><span class=\"st-n\">Step ${g.n} · ${g.color.toLowerCase()}</span><b>${g.name}</b><span class=\"st-sub\">${g.teaser}</span></span><span class=\"st-plus\" aria-hidden=\"true\"></span></summary>\n      <div class=\"st-body\">\n        ${g.note ? `<p class=\"note\">${g.note}</p>` : ''}\n        <div class=\"st-story\">${g.body}</div>\n        <div class=\"st-ask\"><h4>Pick up a pen: five questions for yourself</h4>${g.ask}</div>\n        ${k === 3 ? `<div class=\"st-swiss\"><b>${ico('swissguide', '#6E4F3C', null, 22)} If you live in Switzerland</b><p>My free Swiss Guide Telegram bot in Russian: documents, insurance, taxes, school, housing, letters from the municipality and unwritten rules. Map and keys in one place.</p><a href=\"https://t.me/swisscompass_bot\" target=\"_blank\" rel=\"noopener\">${ico('swissguide', '#FFFFFF', 'rgba(255,255,255,.25)', 18)} Open the bot: @swisscompass_bot</a></div>` : ''}\n        ${k < 7 ? `<div><button type=\"button\" class=\"btn ghost st-totest\">Check whether this step holds → test</button></div>` : ''}\n      </div></details>`;\n  }).join('');\n  $('guide').innerHTML = `<div id=\"backRes\" hidden><button type=\"button\" class=\"btn ghost\" id=\"backResBtn\">← Back to my report</button></div><div class=\"blk st-guide-intro\"><div class=\"eyebrow\">A guide to the steps</div><h2>${GUIDE.introTitle}</h2><div class=\"st-story\">${GUIDE.intro}</div></div>\n    <div class=\"row\" style=\"justify-content:space-between\"><h2 style=\"margin:0\">Eight steps</h2>\n      <button type=\"button\" class=\"btn ghost\" id=\"openAll\" style=\"padding:8px 16px\">Expand all</button></div>\n    <div class=\"stack\" style=\"gap:12px\">${levels}</div>\n    <div class=\"blk st-guide-end\"><div class=\"st-story\">${GUIDE.end}</div><div><button type=\"button\" class=\"btn st-totest\">Take the “7 Steps of Stability” test</button></div></div>\n    ${GUIDE.sources ? `<details class=\"st-sources\"><summary>Sources</summary>${GUIDE.sources}</details>` : ''}`;\n  $('openAll').addEventListener('click', () => {\n    const all = [...document.querySelectorAll('.st-lv')], open = all.some(d => !d.open);\n    all.forEach(d => d.open = open); $('openAll').textContent = open ? 'Collapse all' : 'Expand all';\n  });\n}\nrenderGuide();\nfunction showPart(id){\n  $('guide').hidden = id !== 'guide'; $('testPrep').hidden = id !== 'testPrep';\n  $('goGuide').setAttribute('aria-pressed', id === 'guide'); $('goTest').setAttribute('aria-pressed', id === 'testPrep');\n}\nfunction openGuide(n){\n  const fromResult = !$('result').hidden;\n  $('result').hidden = true; $('quiz').hidden = true; $('intro').hidden = false;\n  $('backRes').hidden = !(fromResult || finished);\n  showPart('guide');\n  const d = n ? $('guide-' + n) : null;\n  if (d){ d.open = true; setTimeout(() => d.scrollIntoView({ behavior: 'smooth', block: 'start' }), 30); }\n  else $('guide').scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n$('goGuide').addEventListener('click', () => openGuide());\n$('backResBtn').addEventListener('click', () => { const v = loadSaved(); if (v && v.finished){ restore(v); showResult(); } else { $('intro').hidden = true; $('result').hidden = false; window.scrollTo(0, 0); } });\n$('goTest').addEventListener('click', () => { showPart('testPrep'); $('testPrep').scrollIntoView({ behavior: 'smooth', block: 'start' }); });\ndocument.addEventListener('click', ev => {\n  if (ev.target.closest('.st-totest')){ showPart('testPrep'); $('testPrep').scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }\n  const a = ev.target.closest('[data-guide]');\n  if (a && !a.closest('.pdf-page')){ ev.preventDefault(); openGuide(+a.dataset.guide); }\n});\nif (/guide-(\\d)/.test(location.hash)) { /* ссылка из PDF: открыть путеводитель после приветствия */\n  window.__guideFromHash = +location.hash.match(/guide-(\\d)/)[1];\n}\n(function(){ const go = $('svGo'); if (go && window.__guideFromHash) go.addEventListener('click', () => setTimeout(() => { if (!$('testStart').hidden) openGuide(window.__guideFromHash); }, 0)); })();\n\n/* ---------- состояние теста ---------- */\nlet ctx, ans, sky, pts, goals, goalText, order, sitOrder, steps, step = 0, myName = '', last = null, finished = false, startedAt = 0;\n\n/* ---------- память: ответы сохраняются в этом браузере после каждого клика ---------- */\nconst SAVE_KEY = 'irinaTests.stupeni.v1';\nfunction save(){\n  try { localStorage.setItem(SAVE_KEY, JSON.stringify({ ctx, ans, sky, pts, goals, goalText, order, sitOrder, step, myName, finished, startedAt, t: Date.now() })); } catch(e){}\n}\nfunction loadSaved(){ try { const v = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null'); return v && v.ans && v.pts ? v : null; } catch(e){ return null; } }\nfunction forget(){ try { localStorage.removeItem(SAVE_KEY); } catch(e){} }\nfunction restore(v){\n  ({ ctx, ans, sky, pts, order, sitOrder, myName, finished } = v); startedAt = v.startedAt || v.t;\n  if (ctx.stay === undefined) ctx.stay = null;\n  goals = v.goals || ITEMS.map(() => null); goalText = v.goalText || ITEMS.map(() => '');\n  buildSteps(); step = Math.min(v.step || 0, steps.length - 1);\n  $('nameMe').value = myName || '';\n}\nfunction reset(){\n  finished = false; startedAt = Date.now();\n  ctx = { how: null, years: null, stay: null };\n  ans = ITEMS.map(() => Array(8).fill(null));\n  sky = Array(6).fill(null);\n  pts = SITS.map(() => [0, 0, 0, 0]);\n  goals = ITEMS.map(() => null); goalText = ITEMS.map(() => '');\n  order = ITEMS.map(() => shuffle([0,1,2,3,4,5,6,7]));\n  sitOrder = SITS.map(() => shuffle([0,1,2,3]));\n}\nconst val = (it, v) => it[2] ? 4 - v : v;\nconst stageScore = k => sum(ans[k].map((v, i) => val(ITEMS[k][i], v)));\nconst stagePct = k => Math.round(stageScore(k) / 32 * 100);\nconst statusOf = p => p >= 75 ? 2 : p >= 50 ? 1 : 0;\nconst allHold = () => ans.every(a => a.every(v => v !== null)) && ITEMS.every((_, k) => statusOf(stagePct(k)) === 2);\nfunction buildSteps(){\n  steps = [{ t: 'about' }];\n  ITEMS.forEach((_, k) => steps.push({ t: 'stage', k }));\n  if (allHold()) steps.push({ t: 'sky' });\n  for (let i = 0; i < SITS.length; i += SITS_PER_SCREEN) steps.push({ t: 'sit', ids: SITS.slice(i, i + SITS_PER_SCREEN).map((_, j) => i + j) });\n  steps.push({ t: 'goal' });\n}\nconst totalCount = () => 3 + 56 + (steps.some(s => s.t === 'sky') ? 6 : 0) + SITS.length + 7;\nfunction doneCount(){\n  return (ctx.how !== null) + (ctx.years !== null) + (ctx.stay != null) + ans.flat().filter(v => v !== null).length\n    + (steps.some(s => s.t === 'sky') ? sky.filter(v => v !== null).length : 0) + pts.filter(p => sum(p) === 10).length + goals.filter(g => g !== null).length;\n}\n\n$('startBtn').addEventListener('click', () => {\n  myName = $('nameMe').value.trim();\n  resetInvite(); window.__leadCountry = '';\n  reset(); buildSteps(); step = 0;\n  $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0);\n});\n\nfunction choiceGroup(title, opts, key){\n  const wrap = document.createElement('div'); wrap.className = 'q';\n  wrap.innerHTML = `<p>${title}</p><div class=\"choices1\" role=\"group\"></div>`;\n  const g = wrap.querySelector('.choices1');\n  opts.forEach((o, i) => {\n    const b = document.createElement('button'); b.className = 'opt1'; b.type = 'button'; b.textContent = o;\n    b.setAttribute('aria-pressed', ctx[key] === i ? 'true' : 'false');\n    b.addEventListener('click', () => { ctx[key] = i; g.querySelectorAll('.opt1').forEach((x, n) => x.setAttribute('aria-pressed', n === i ? 'true' : 'false')); update(); });\n    g.appendChild(b);\n  });\n  return wrap;\n}\nfunction scaleItem(text, num, arr, i){\n  const q = document.createElement('div'); q.className = 'q';\n  q.innerHTML = `<p><span class=\"n\">${num}.</span>${text}</p><div class=\"opts\" role=\"group\" aria-label=\"How much this is like you\"></div>`;\n  const opts = q.querySelector('.opts');\n  for (let v = 0; v <= 4; v++){\n    const o = document.createElement('button'); o.className = 'opt'; o.type = 'button';\n    o.setAttribute('aria-pressed', arr[i] === v ? 'true' : 'false');\n    o.innerHTML = `<b>${v}</b><small>${LABELS[v]}</small>`;\n    o.addEventListener('click', () => { arr[i] = v; opts.querySelectorAll('.opt').forEach((x, n) => x.setAttribute('aria-pressed', n === v ? 'true' : 'false')); update(); });\n    opts.appendChild(o);\n  }\n  return q;\n}\nfunction sitItem(s, num){\n  const q = document.createElement('div'); q.className = 'q st-sit';\n  const left = () => 10 - sum(pts[s]);\n  q.innerHTML = `<p><span class=\"n\">${num}.</span>${SITS[s][0]}</p><div class=\"st-pts\"></div><div class=\"st-left\"></div>`;\n  const box = q.querySelector('.st-pts'), leftEl = q.querySelector('.st-left');\n  const paint = () => {\n    const l = left();\n    leftEl.textContent = l === 0 ? 'All 10 points allocated ✓' : `Points left: ${l}`;\n    leftEl.classList.toggle('done', l === 0);\n    box.querySelectorAll('.st-row').forEach(r => {\n      const o = +r.dataset.o, v = pts[s][o];\n      r.querySelector('.st-v').textContent = v;\n      r.querySelector('.minus').disabled = v === 0;\n      r.querySelector('.plus').disabled = l === 0;\n      r.querySelector('.st-dots').innerHTML = '<i></i>'.repeat(v);\n      r.classList.toggle('on', v > 0);\n    });\n    update();\n  };\n  sitOrder[s].forEach(o => {\n    const r = document.createElement('div'); r.className = 'st-row'; r.dataset.o = o;\n    r.innerHTML = `<div class=\"st-t\"><span>${SITS[s][1][o][1]}</span><span class=\"st-dots\"></span></div>\n      <div class=\"st-ctl\"><button type=\"button\" class=\"minus\" aria-label=\"Remove a point\">−</button><span class=\"st-v\">0</span><button type=\"button\" class=\"plus\" aria-label=\"Add a point\">+</button></div>`;\n    r.querySelector('.minus').addEventListener('click', () => { if (pts[s][o] > 0){ pts[s][o]--; paint(); } });\n    r.querySelector('.plus').addEventListener('click', () => { if (left() > 0){ pts[s][o]++; paint(); } });\n    r.querySelector('.st-t').addEventListener('click', () => { if (left() > 0){ pts[s][o]++; paint(); } });\n    box.appendChild(r);\n  });\n  paint();\n  return q;\n}\n\nfunction renderStep(){\n  const list = $('qlist'), S = steps[step]; list.innerHTML = '';\n  $('stepLabel').textContent = `Step ${step + 1} of ${steps.length}`;\n  document.documentElement.style.setProperty('--accent', 'var(--plum)');\n  $('roleTitle').style.color = 'var(--plum)';\n  if (S.t === 'about'){\n    $('partTag').textContent = 'About you';\n    $('roleTitle').textContent = 'Your story';\n    $('roleSub').textContent = 'Three questions about your story. They don’t count towards the steps, but they will help me tell you more precisely where you are heading.';\n    list.appendChild(choiceGroup('How did you end up here?', HOW, 'how'));\n    list.appendChild(choiceGroup('How long have you been living in the new country?', YEARS, 'years'));\n    list.appendChild(choiceGroup('Do you want to stay and live here?', STAY, 'stay'));\n  } else if (S.t === 'stage'){\n    $('partTag').textContent = 'Part 1 · Anchor · over the last 4 weeks';\n    $('roleTitle').textContent = `Step ${S.k + 1} of 7`;\n    $('roleSub').textContent = CHEER[S.k];\n    let n = S.k * 8;\n    order[S.k].forEach(i => list.appendChild(scaleItem(ITEMS[S.k][i][1], ++n, ans[S.k], i)));\n  } else if (S.t === 'sky'){\n    $('partTag').textContent = 'The sky above home · bonus';\n    $('roleTitle').textContent = 'All seven steps beneath you are holding';\n    $('roleTitle').style.color = LV[7].line;\n    $('roleSub').textContent = 'This is rare — and it is your achievement. Above the home there is also the sky: not a step that needs fixing, but a horizon to grow towards. Six statements — let’s see where you are in relation to it.';\n    let n = 56;\n    SKY.forEach((it, i) => list.appendChild(scaleItem(it[1], ++n, sky, i)));\n  } else if (S.t === 'goal'){\n    $('partTag').textContent = 'Part 3 · Your goal';\n    $('roleTitle').textContent = 'Where you want to be';\n    $('roleSub').textContent = 'Imagine yourself three to six months from now. How strong do you want each step to be? 0 — this doesn’t matter right now, 10 — an anchor you can put your full weight on. If you like, add one line about what you would like to change here: that way the goal becomes yours, not a general one.';\n    ITEMS.forEach((_, k) => list.appendChild(goalItem(k)));\n  } else {\n    const first = S.ids[0] === 0;\n    $('partTag').textContent = 'Part 2 · Situations';\n    $('roleTitle').textContent = first ? 'Twelve scenes from life' : `Situations ${S.ids[0] + 1}–${S.ids[S.ids.length - 1] + 1} of 12`;\n    $('roleSub').textContent = first\n      ? 'Each scene has four options. You have 10 points: give more to whatever is closer to you. You can give all 10 to one option or split them. All the options are fine, just different. Don’t choose what seems right; choose what you are really like.'\n      : 'Allocate 10 points in each scene: more to whatever is closer to you.';\n    S.ids.forEach(s => list.appendChild(sitItem(s, s + 1)));\n  }\n  $('next').textContent = step === steps.length - 1 ? 'Show my report' : 'Next';\n  update();\n}\nfunction goalItem(k){\n  const l = LV[k], q = document.createElement('div'); q.className = 'q st-goal'; q.style.cssText = `--l:${l.line};--f:${l.fill};--s:${l.soft}`;\n  q.innerHTML = `<div class=\"st-gh\"><span class=\"st-ico\">${lvIcon(k, 22)}</span><b>${k + 1} · ${l.name}</b><span class=\"st-gv\"></span></div>\n    <input type=\"range\" min=\"0\" max=\"10\" step=\"1\" aria-label=\"How strong you want the step “${l.name}” to be\" value=\"${goals[k] ?? 5}\">\n    <div class=\"st-gscale\"><span>0 · not important now</span><span>10 · a solid anchor</span></div>\n    <textarea class=\"st-gtext\" rows=\"2\" maxlength=\"160\" placeholder=\"My goal here (optional). For example: ${GOAL_HINT[k]}\">${esc(goalText[k] || '')}</textarea>`;\n  const r = q.querySelector('input[type=range]'), v = q.querySelector('.st-gv');\n  const paint = () => { v.textContent = goals[k] === null ? 'choose' : goals[k] + ' of 10'; q.classList.toggle('set', goals[k] !== null); r.style.setProperty('--p', ((goals[k] ?? 5) * 10) + '%'); };\n  r.addEventListener('input', () => { goals[k] = +r.value; paint(); update(); });\n  r.addEventListener('pointerdown', () => { if (goals[k] === null){ goals[k] = +r.value; paint(); update(); } });\n  q.querySelector('.st-gtext').addEventListener('input', e => { goalText[k] = e.target.value; save(); });\n  paint();\n  return q;\n}\nfunction stepComplete(){\n  const S = steps[step];\n  if (S.t === 'goal') return goals.every(g => g !== null);\n  if (S.t === 'about') return ctx.how !== null && ctx.years !== null && ctx.stay != null;\n  if (S.t === 'stage') return ans[S.k].every(v => v !== null);\n  if (S.t === 'sky') return sky.every(v => v !== null);\n  return S.ids.every(s => sum(pts[s]) === 10);\n}\nfunction update(){\n  save();\n  const d = doneCount(), T = totalCount();\n  $('countLabel').textContent = `${d} of ${T}`;\n  $('prog').style.width = (d / T * 100) + '%';\n  $('next').disabled = !stepComplete();\n}\n$('next').addEventListener('click', () => {\n  if (steps[step].t === 'stage' && steps[step].k === 6) buildSteps();   // бонус появляется, если все 7 ступеней крепкие\n  if (step < steps.length - 1){ step++; renderStep(); window.scrollTo(0, 0); } else showResult();\n});\n$('back').addEventListener('click', () => {\n  if (step > 0){ step--; renderStep(); window.scrollTo(0, 0); }\n  else { $('quiz').hidden = true; $('intro').hidden = false; }\n});\n\n/* ---------- подсчёт ---------- */\nfunction compute(){\n  const pct = ITEMS.map((_, k) => stagePct(k));\n  const st = pct.map(statusOf);\n  const hasSky = steps.some(s => s.t === 'sky');\n  const skySum = hasSky ? sum(sky.map((v, i) => val(SKY[i], v))) : null;\n  let o = st.indexOf(0);                           // самая нижняя «здесь начинаем»\n  if (o < 0) o = st.indexOf(1);                    // иначе самая нижняя «поскрипывает»\n  let top = null;\n  if (o < 0){ o = 6; top = skySum >= 18 ? 'horizon' : 'edge'; }\n  const oLevel = top === 'horizon' ? 8 : o + 1;    // 1–8\n  const gr = [0,1,2,3].map(g => sum(ITEMS[o].map((it, i) => it[0] === g ? val(it, ans[o][i]) : 0)));\n  const weak = [2,1,0,3].reduce((b, g) => gr[g] < gr[b] ? g : b, 2);\n  const extra = st.findIndex((s, k) => k > o && s === 0);\n  const heart = LV.map(() => 0);\n  SITS.forEach((s, i) => s[1].forEach(([lv], j) => heart[lv] += pts[i][j]));\n  const hp = heart.map(v => Math.round(v / 60 * 100));\n  const rank = heart.map((v, k) => [v, k]).sort((a, b) => b[0] - a[0]);\n  const c = rank[0][1], c2 = rank[0][0] - rank[1][0] < 4 ? rank[1][1] : null;\n  const quiet = rank[rank.length - 1][1];\n  const cLevel = c + 1;\n  const combo = cLevel === oLevel || cLevel === oLevel + 1 ? 'same' : cLevel > oLevel ? 'above' : 'below';\n  const trap = cLevel === 8 && (st[0] === 0 || st[1] === 0) ? 'sky'\n    : cLevel === 6 && st[4] === 0 ? 'green'\n    : cLevel === 7 && (st[0] === 0 || st[1] === 0 || st[2] === 0) ? 'yellow'\n    : cLevel === 4 && st[2] === 0 ? 'blue' : null;\n  return { pct, st, skySum, o, top, oLevel, gr, weak, extra, heart, hp, c, c2, quiet, combo, trap };\n}\n\n/* ---------- картинки разбора ---------- */\nconst INK = '#2F2924', MUTED = '#8C7F71';\nconst tx = (x, y, t, o = {}) => `<text x=\"${x}\" y=\"${y}\" text-anchor=\"${o.a || 'start'}\" font-family=\"${o.serif ? 'Forum, Georgia, serif' : 'Manrope, sans-serif'}\" font-size=\"${o.s || 13}\" font-weight=\"${o.w || 400}\" fill=\"${o.c || INK}\">${t}</text>`;\nlet svgN = 0;\nfunction wcFilter(){ const id = 'wc' + (++svgN); return [id, `<defs><filter id=\"${id}\" x=\"-5%\" y=\"-20%\" width=\"110%\" height=\"140%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".035\" numOctaves=\"2\" seed=\"${svgN % 7 + 2}\"/><feDisplacementMap in=\"SourceGraphic\" scale=\"4\"/></filter></defs>`]; }\n\n/* Лестница: 7 ступеней снизу вверх + небо пунктиром (ширина рассчитана на телефон) */\nfunction ladderSVG(r){\n  const W = 400, stepH = 40, gap = 7, x0 = 2, dx = 17, bw = 280, top = 50, H = top + 7 * (stepH + gap);\n  const [fid, defs] = wcFilter();\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"A staircase of seven steps\">${defs}`;\n  const row = (k, x, y, p, me, dashed) => {\n    const l = LV[k]; let t = '';\n    t += `<rect x=\"${x}\" y=\"${y}\" width=\"${bw}\" height=\"${stepH}\" rx=\"10\" fill=\"#FFFFFF\" fill-opacity=\".6\"/>`;\n    if (p > 0) t += `<rect x=\"${x + 2}\" y=\"${y + 2}\" width=\"${(bw - 4) * p / 100}\" height=\"${stepH - 4}\" rx=\"8\" fill=\"${l.fill}\" filter=\"url(#${fid})\"/>`;\n    t += `<rect x=\"${x}\" y=\"${y}\" width=\"${bw}\" height=\"${stepH}\" rx=\"10\" fill=\"none\" stroke=\"${l.line}\" stroke-width=\"${me ? 2.8 : 1.2}\" ${dashed ? 'stroke-dasharray=\"5 4\"' : ''}/>`;\n    t += `<g transform=\"translate(${x + 8} ${y + 9})\">${lvIcon(k, 22).replace(/^<svg[^>]*>|<\\/svg>$/g, '')}</g>`;\n    t += tx(x + 36, y + 26, `${k + 1} · ${l.name}`, { serif: true, s: 16, c: l.line });\n    return t;\n  };\n  const skyOn = r.top === 'horizon', sx = x0 + 7 * dx;\n  s += row(7, sx, 4, skyOn ? 100 : 0, skyOn, !skyOn);\n  s += tx(sx + bw - 10, 30, skyOn ? 'you are here' : 'horizon', { a: 'end', s: 12, c: LV[7].line, w: skyOn ? 800 : 500 });\n  for (let k = 0; k < 7; k++){\n    const y = top + (6 - k) * (stepH + gap), x = x0 + k * dx, l = LV[k], p = r.pct[k], me = r.o === k && r.top !== 'horizon';\n    s += row(k, x, y, p, me, false);\n    s += tx(x + bw - 10, y + 26, (me ? (r.top === 'edge' ? 'on the edge · ' : 'you are here · ') : '') + p + '%', { a: 'end', s: me ? 13 : 12.5, w: 800, c: l.line });\n  }\n  return s + '</svg>';\n}\n/* Профиль сердца: 8 дорожек */\nfunction heartSVG(r){\n  const W = 400, rowH = 36, H = 6 + rowH * 8, x0 = 150, x1 = 352;\n  const [fid, defs] = wcFilter();\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Heart profile\">${defs}`;\n  r.hp.forEach((v, k) => {\n    const y = 6 + k * rowH, l = LV[k], hi = k === r.c || k === r.c2;\n    s += `<g transform=\"translate(0 ${y + 6})\">${lvIcon(k, 20).replace(/^<svg[^>]*>|<\\/svg>$/g, '')}</g>`;\n    s += tx(26, y + 21, l.name, { s: 13.5, w: hi ? 800 : 500, c: l.line });\n    s += `<rect x=\"${x0}\" y=\"${y + 7}\" width=\"${x1 - x0}\" height=\"20\" rx=\"10\" fill=\"${l.soft}\" stroke=\"${l.line}\" stroke-width=\"${hi ? 1.8 : .7}\"/>`;\n    if (v > 0) s += `<rect x=\"${x0 + 2}\" y=\"${y + 9}\" width=\"${(x1 - x0 - 4) * v / 100}\" height=\"16\" rx=\"8\" fill=\"${l.fill}\" filter=\"url(#${fid})\"/>`;\n    s += tx(W - 2, y + 22, v + '%', { a: 'end', s: 13, w: hi ? 800 : 500, c: l.line });\n  });\n  return s + '</svg>';\n}\nconst WHEEL_LABEL = ['Body', 'My people', 'Voice', 'Order', 'Work', 'Contribution', 'The whole'];\nconst wheelSVG = (fill, outline, size) => petalWheelSVG(ITEMS.map((_, k) => ({ label: (k + 1) + ' ' + WHEEL_LABEL[k], fill: LV[k].fill, line: LV[k].line })), fill, outline, size);\nfunction graniHtml(r){\n  const l = LV[r.o];\n  return `<div class=\"st-grani\">${GR.map((g, i) => `<div class=\"${i === r.weak ? 'weak' : ''}\"><span><b>${g}</b> · ${GR_SUB[i]}</span>\n    <div class=\"bar\" style=\"background:${l.soft}\"><i style=\"width:${r.gr[i] / 8 * 100}%;background:${l.line}\"></i></div><small>${r.gr[i]} of 8</small></div>`).join('')}</div>`;\n}\n\nconst HOLD = [\n  'When the ground under your feet is shaking, almost all your strength goes into holding on. There is simply none left for moving forward, and that isn’t laziness but physical exhaustion.',\n  'Without your own people, every move is twice as hard: there is no one to share the joy with and no one to lean on when you are scared.',\n  'Until your voice comes back, every goal runs into “I can’t”: to call, to ask, to insist. And the goal gets put off so you don’t have to face that feeling.',\n  'When it’s unclear how things work here, the fear of getting it wrong turns out to be stronger than the wish. Waiting feels safer than doing it wrong.',\n  'While your own business and your own price have not yet been found, it is easy to live by other people’s goals: “I need to find a job”, “I need to learn the language”. But other people’s goals give you no strength.',\n  'When you give others more than you keep for yourself, there simply isn’t enough time and water left for your own things.',\n  'While the decision about the move is still open, life feels like a draft. And why set goals in a draft?'\n];\nconst STATES = {\n  alpha: ['Balance', 'Right now your life is in relative balance: the way you live and what you need mostly match. This is a good time to look after what you already have and calmly take a look at the next step, without rush or heroics.'],\n  beta:  ['Vague unease', 'Right now you are more in a state of vague unease: you feel that something is off, but it’s hard to say what exactly and where to go. This is a normal and even necessary stage: this is exactly where change begins. The important thing is not to get stuck in it for long, but to turn “something is off” into a clear question.'],\n  gamma: ['Dead end', 'Right now you seem to be at a dead end: it’s already clear what is wrong, but there seems to be no way out. You want to, but it doesn’t work; you try, but nothing moves. Hence irritation, helplessness, the wish to give it all up. This is the hardest place on the path, and getting out of it alone is hardest of all. Usually the way out begins with naming the barrier.'],\n  delta: ['Shift', 'Right now you seem to be on the threshold of a shift: desire, attention and support are pointing the same way. This is a time when small steps bring noticeable results. It’s important to support this moment so the energy doesn’t scatter.']\n};\nfunction moveState(r, gaps, G){\n  const fails = r.st.filter(x => x === 0).length, maxGap = Math.max(...gaps), stay = ctx.stay;\n  const cLevel = r.c + 1, oLevel = r.top === 'horizon' ? 8 : r.o + 1;\n  if (fails === 0 && maxGap <= 15 && stay === 0) return 'alpha';\n  if (fails <= 1 && !r.top && G === r.o && cLevel <= oLevel + 1 && cLevel >= oLevel - 1 && (stay === 0 || stay === 1)) return 'delta';\n  if (fails >= 1 && (maxGap >= 30 || r.trap)) return 'gamma';\n  return 'beta';\n}\nfunction stopsAndDrives(r, gaps, G){\n  const stops = [], drives = [];\n  const lowFail = r.st.findIndex(x => x === 0);\n  if (lowFail >= 0 && lowFail <= 1) stops.push(['Your strength goes to the lower steps', `The step “${LV[lowFail].name}” needs care, and while it isn’t holding, almost all your strength goes into holding on. Before going higher, your body and heart need an anchor.`]);\n  if (Math.max(...gaps) <= 10) stops.push(['No clear goal', 'Where you want to be almost matches what already is. Without the feeling “I want it to be different”, change doesn’t begin. Sometimes it’s tiredness, and sometimes a quiet ban on wanting. A clear goal can be found, and that is a good place to start.']);\n  else if (!goalText.some(t => t && t.trim())) stops.push(['The goal is still vague', 'You marked how much you want to strengthen the steps, but didn’t describe in words what it will look like. When it’s unclear what “it worked” looks like, it’s hard to take the first step.']);\n  if (!r.top){\n    const w = r.weak;\n    stops.push([['Inner barrier: feelings', 'Inner barrier: something is off in what you do', 'Outer barrier: circumstances', 'Barrier in your thoughts: beliefs'][w],\n      ['The main barrier on your step is feelings: shame, fear, tiredness. You know and can do a lot, but something inside is holding you back. What helps here is not another set of instructions but gentle attention to yourself.',\n       'The main barrier on your step is in action: you know what’s needed, but there are no steps yet. What helps are very small, regular actions and someone beside you to remind you.',\n       'The main barrier on your step is outside: there aren’t enough people, conditions, resources. It is not your fault. Here it’s important to separate what can be changed from what you will have to work around for now.',\n       'The main barrier on your step is in your thoughts: “I have no right”, “I can’t”, “it’s too late”. Beliefs like these sound like the truth, but they are only habitual thoughts, and they can be reconsidered.'][w]]);\n  }\n  if (ctx.stay === 2 || ctx.stay === 4) stops.push(['The horizon is unclear', ctx.stay === 2 ? 'You have not yet decided whether to stay. While the question is open, it’s hard to invest in long-term goals: the language, your own business, friends.' : 'The decision to stay or leave doesn’t depend only on you. Uncertainty set by others takes a lot of strength.']);\n  if (r.st[1] < 2) stops.push(['Little support', 'Change needs support: people who will back you up when you are scared or when things don’t work out. When you have few people of your own, even a good goal fades halfway.']);\n  r.st.forEach((x, k) => { if (x === 2 && drives.length < 2) drives.push(LV[k].name); });\n  return { stops: stops.slice(0, 3), drives };\n}\nfunction pathBlocks(r, A, PDF){\n  const { cur, goal, gaps, G } = A, maxGap = gaps[G];\n  const texts = goalText.map((t, k) => [k, (t || '').trim()]).filter(x => x[1]);\n  const allTen = goals.every(g => g === 10), noRise = maxGap <= 10;\n  let gapTxt;\n  if (noRise) gapTxt = 'It seems hard for you right now to say where you want to be. Your goals almost match what already is. This happens when your strength is only enough for today, or when wanting feels dangerous: what if it doesn’t work out? This is an important discovery too. A clear goal doesn’t appear by itself, it can be found, and that is the first thing we could work on together.';\n  else gapTxt = `The biggest gap is on the step “${LV[G].name}”: now ${cur[G]}%, and you want ${goal[G]}%.`\n    + (G === r.o && !r.top ? ' And this is the same step that is worth starting with. Desire and support point the same way, and that is a very good sign: your strength will go where it is needed most.'\n      : G > r.o && !r.top ? ` But beneath it, the step “${LV[r.o].name}” still needs care. Often that is exactly why movement doesn’t happen: you want to go up, but your strength goes into holding on down below.`\n      : ' This step is below the one you are standing on, and that is wise: you sense that your support needs strengthening.');\n  { const big = gaps.map((g, k) => [g, k]).filter(([g]) => g >= 20).sort((a, b) => b[0] - a[0]);\n    if (big.length > 1) gapTxt += ' You clearly want to strengthen ' + joinRu(big.slice(0, 3).map(([g, k]) => `${nm(k)} (from ${cur[k]} to ${goal[k]}%)`)) + '.';\n    const lower = gaps.map((g, k) => [g, k]).filter(([g]) => g <= -20);\n    if (lower.length) gapTxt += ` And the step ${joinRu(lower.map(([g, k]) => nm(k)))} is currently stronger than you need: perhaps it takes more of your strength than you would like, and that strength could be freed up for something else.`;\n    const ownGoal = !r.top && goalText[r.o] && goalText[r.o].trim();\n    if (ownGoal) gapTxt += ` On your step you wrote yourself: “${esc(goalText[r.o].trim())}”. Keep these words, they make a good starting point.`; }\n  if (allTen) gapTxt += ' You would also like all the steps to be ten out of ten strong. That is a very understandable wish, but everything at once almost never works. A good goal is a single one, and it can be reached within a few months.';\n  const B = [];\n  const goalsBox = texts.length ? `<div class=\"st-goals\"><b>Your words about your goal</b>${texts.map(([k, t]) => `<p style=\"--l:${LV[k].line}\"><span>${LV[k].name}</span>${esc(t)}</p>`).join('')}</div>` : '';\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Where you are now and where you want to be</div><h2>Three wheels of your life</h2>\n    <p>The same seven steps in a circle. The longer the petal, the stronger the step. The first wheel shows where you are now, based on your test answers. The second shows where you want to be, based on your goals. The third shows both at once: the distance between the filled petal and the dotted line is your path.</p>\n    <div class=\"st-wheels3\"><figure class=\"both\">${wheelSVG(cur, goal)}<figcaption>Together: now and where you want to be</figcaption></figure><figure>${wheelSVG(cur)}<figcaption>Where you are now</figcaption></figure><figure>${wheelSVG(goal)}<figcaption>Where you want to be</figcaption></figure></div>\n    ${WHEEL_LEGEND}</div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Your path</div><h2>The difference between “now” and “where you want to be”</h2><p>${gapTxt}</p>${goalsBox}</div>` });\n  const ms = A.ms;\n  const sd = stopsAndDrives(r, gaps, G), ST = STAY_TXT[ctx.stay ?? 2];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">To stay or not</div><h2>${ST[0]}</h2><p>${ST[1]}</p>\n    ${(ctx.stay === 1 || ctx.stay === 2) && r.st[6] < 2 ? `<p class=\"st-soft\">This echoes your seventh step, “The view from the hill”: while the decision is still open, life easily stays a draft. What often helps is not deciding once and for all, but honestly writing down what keeps you here and what pulls you there.</p>` : ''}</div>` });\n  B.push({ html: `<div class=\"blk st-hold\"><div class=\"eyebrow\">Where you are heading</div><h2>Your current state: ${STATES[ms][0].toLowerCase()}</h2>\n    <p>${STATES[ms][1]}</p>\n    <div class=\"st-states\">${['alpha','beta','gamma','delta'].map(k => `<span class=\"${k === ms ? 'on' : ''}\">${STATES[k][0]}</span>`).join('<i>→</i>')}</div>\n    <p class=\"note\">The creators of Spiral Dynamics, Don Beck and Christopher Cowan, described how people change not in a straight line but in a circle: from balance through vague unease and a dead end to a shift and a new balance, one step higher. Every state is normal, the important thing is not to get stuck.</p>\n    ${sd.drives.length ? `<p><b>What already holds you and moves you forward:</b> ${sd.drives.map(n => `the step “${n}”`).join(' and ')}${ctx.stay === 0 ? ', and your decision to stay' : ''}. You can rely on this.</p>` : ''}\n    <h3>What is holding you back right now</h3>\n    <div class=\"st-stops\">${sd.stops.map(([h, t]) => `<div><b>${h}</b><p>${t}</p></div>`).join('')}</div>\n    <p>None of this is a verdict. According to Beck and Cowan, change happens when there is strength, a feeling of “I don’t want it like this any more”, clarity about where to go, a named barrier and support beside you. Each of these conditions can be created, and you can work with them gently.</p></div>` });\n  B.push({ html: `<div class=\"blk st-together\"><div class=\"eyebrow\">A path you can walk together</div><h2>${myName ? esc(myName) + ', this is' : 'This is'} your path from one wheel to the other</h2>\n    <p>You can walk it alone. Or together, in partnership. In coaching I don’t give advice and don’t decide for you. I work in depth, through emotional intelligence. Together we find what is holding you in particular, turn “I want things to be good” into a clear goal that is truly yours, and move towards it in small steps at your own pace, relying on the steps that are already strong for you.</p>\n    <p>In an introductory meeting, 30 minutes online, we’ll get to know each other, look at your wheels together, talk through what you want to work on and see how far I can be of help to you. How to book is just below.</p></div>` });\n  return B;\n}\nfunction swissHtml(r, country){\n  if (country && country !== 'Швейцария') return '';\n  const head = country ? 'For life in Switzerland' : 'If you live in Switzerland';\n  const lead = !r.top && r.o === 3 ? 'Right now the step “Map and keys” takes the most strength. Part of this load can be lifted today.' : 'A little support for the step “Map and keys”.';\n  return `<div class=\"blk swiss-guide\"><div class=\"eyebrow\">${head}</div><h2>A guide to Switzerland — Swiss Guide</h2>\n    <p>${lead} This is my free Telegram bot in Russian. It brings together answers to practical questions about life in Switzerland: documents and permits, insurance, taxes, school, housing, letters from the municipality and unwritten rules. So that your energy is left for what matters to you.</p>\n    <div class=\"invite-links\"><a href=\"https://t.me/swisscompass_bot\" target=\"_blank\" rel=\"noopener\">${ico('swissguide', '#FFFFFF', 'rgba(255,255,255,.25)', 18)} Open the bot: @swisscompass_bot</a></div></div>`;\n}\n\n/* ---------- индивидуальные интерпретации ---------- */\nconst GR_DESC = [\n  ['energy and wellbeing', 'sleep, food and routine', 'a place of your own and calm about money', 'permission to rest'],\n  ['warmth with people', 'being able to invite people and meet up', 'your people close by', 'the feeling “I belong here”'],\n  ['inner confidence', 'acting on your own', 'respect from those around you', 'the right to what is yours'],\n  ['calm when letters arrive', 'order in your paperwork', 'a reliable source of answers', 'understanding the rules here'],\n  ['ease when you talk about yourself', 'steps towards your own business', 'your own money and recognition', 'knowing your own price'],\n  ['joy in giving', 'being able to say “no”', 'a circle where you are a co-creator', 'knowing what it is all for'],\n  ['the feeling that you are living your own life', 'the courage not to put things off “for later”', 'a home that feels like yours', 'peace with the decision to leave']\n];\nconst nm = k => `“${LV[k].name}”`;\nconst joinRu = a => a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' and ' + a[a.length - 1];\nfunction ladderPattern(r){\n  const st = r.st, fails = st.map((x, k) => x === 0 ? k : -1).filter(k => k >= 0), holds = st.map((x, k) => x === 2 ? k : -1).filter(k => k >= 0), shaky = st.map((x, k) => x === 1 ? k : -1).filter(k => k >= 0);\n  if (!fails.length && !shaky.length) return 'All seven steps beneath you are holding. That is a rare and very grown-up picture: you have energy, your people, a voice, order, your own work, giving, and the sense that this is your life. Now the question is no longer about repairs, but about where to grow next.';\n  if (fails.some(k => k <= 2) && holds.filter(k => k >= 4).length >= 2) return `Your staircase has an unusual shape: a lot is holding at the top (${joinRu(holds.filter(k => k >= 4).map(nm))}), while lower down, care is needed at ${joinRu(fails.filter(k => k <= 2).map(nm))}. This often happens to strong women who carry work, family and other people’s worries, and forget about their own base. On the outside you are coping, but this success stands on a thin floor, and sooner or later your body or loneliness makes itself felt. Strengthening the bottom is not a step back, but a way to keep everything you have already built.`;\n  if (fails.length >= 4) return `Right now a lot needs care at once: ${joinRu(fails.map(nm))}. If things feel hard, that makes sense: the move knocked out several supports at once, and you are having to hold on almost without a floor under your feet. It’s important not to try to fix everything at the same time. One lower step, truly strengthened, will give you the strength for the next.`;\n  if (fails.length === 1) return `Almost your whole staircase is holding, and only one step, ${nm(fails[0])}, needs care${shaky.length ? `, and ${joinRu(shaky.map(nm))} ${shaky.length > 1 ? 'creak' : 'creaking'} a little` : ''}. That’s good news: you have plenty of support, and you can stand on it to lift up that very step.`;\n  if (!fails.length) return `None of your steps is collapsing, but ${joinRu(shaky.map(nm))} are hanging by a thread, as they say. In an ordinary week you cope, but in a hard one it’s exactly these steps that give way first. Now is a good time to strengthen them without rushing, while there is no crisis.`;\n  return `Two or three of your steps need care: ${joinRu(fails.map(nm))}${holds.length ? `, while ${joinRu(holds.map(nm))} are holding firm` : ''}. It’s worth starting with the lowest of them — that way each next one will stand on something solid.`;\n}\nfunction contextLines(r){\n  const o = r.top ? -1 : r.o, L = [];\n  if (o >= 0){\n    if (ctx.years === 0 && o >= 4) L.push('You’ve been here less than a year, and the lower steps are already holding. That’s a lot of work, and it deserves to be recognised.');\n    if (ctx.years === 1 && o <= 2) L.push(`You’ve been here for more than a year, and the step ${nm(o)} still needs care. This often happens in the second or third year: the first wave of energy has passed, and a new anchor hasn’t grown yet.`);\n    if (ctx.years >= 2 && o <= 3) L.push(`You’ve been here for several years, and still the step ${nm(o)} isn’t holding. So it’s not about time: time alone won’t strengthen it, a different approach is needed, and it can be found.`);\n    if (ctx.how === 2 && o === 2) L.push('When you move to be with your husband, it’s easy to end up as the one others decide for: at first the language, the money and the connections are his. Your voice comes back when there are things you do yourself.');\n    if (ctx.how === 0 && o === 4) L.push('When the move happened for your husband’s job or for the family, your own work is often put off “until later”. That’s understandable, but “later” doesn’t come by itself.');\n    if (ctx.how === 1 && o === 1) L.push('When you move for work, your days are full, but your own people are missing: there are colleagues, but no one close. This is a very common story, and here your circle doesn’t form at work.');\n    if ((ctx.stay === 2 || ctx.stay === 4) && o <= 3) L.push('You don’t yet know whether you’re here for long, and that makes the lower steps especially shaky: it’s hard to settle in when you’re not sure it’s worth it.');\n  }\n  return L;\n}\nfunction itemsOf(k){ return ITEMS[k].map((it, i) => ({ k, i, t: it[1], rev: !!it[2], a: ans[k][i], v: val(it, ans[k][i]) })); }\nfunction yourWords(r){\n  if (r.top) return '';\n  const own = itemsOf(r.o), low = [...own].sort((a, b) => a.v - b.v).slice(0, 2), high = [...own].sort((a, b) => b.v - a.v).filter(x => x.v >= 3).slice(0, 2);\n  const all = ITEMS.flatMap((_, k) => k === r.o ? [] : itemsOf(k)).filter(x => x.v === 4 && !x.rev);\n  const strong = all.sort((a, b) => a.k - b.k).filter((x, j, arr) => arr.findIndex(y => y.k === x.k) === j).slice(0, 3);\n  const q = x => `<div class=\"st-quote\" style=\"--l:${LV[x.k].line};--s:${LV[x.k].soft}\"><p>“${x.t.replace(/\\.$/, '')}”</p><span>your answer: ${LABELS[x.a]}</span></div>`;\n  return `<div class=\"blk\"><div class=\"eyebrow\">Your own answers</div><h2>What you said about yourself</h2>\n    <p>The quietest places of the step ${nm(r.o)} are in these phrases. Read them again: often this is exactly where the first step is hiding.</p>\n    <div class=\"st-quotes\">${low.map(q).join('')}</div>\n    ${high.length ? `<p>And here is what is already working for you on this step, something you can lean on:</p><div class=\"st-quotes\">${high.map(q).join('')}</div>` : ''}\n    ${strong.length ? `<p>And your strengths on the other steps:</p><div class=\"st-quotes\">${strong.map(q).join('')}</div>` : ''}</div>`;\n}\nfunction heartExample(r){\n  let best = null;\n  SITS.forEach((s, i) => s[1].forEach(([lv, t], j) => { if (lv === r.c && (!best || pts[i][j] > best.p)) best = { q: s[0], t, p: pts[i][j] }; }));\n  return best && best.p >= 4 ? `For example, in the scene “${best.q.replace(/[.?]$/, '')}” you gave ${best.p} out of 10 points to the option “${best.t.replace(/\\.$/, '')}”. This is how that note sounds in your life.` : '';\n}\nfunction portrait(r, A){\n  const NN = myName ? esc(myName) : '';\n  const holds = r.st.map((x, k) => x === 2 ? k : -1).filter(k => k >= 0);\n  const parts = [];\n  parts.push(holds.length === 7 ? `${capLead(NN, 'right now your anchor is the whole staircase, all seven steps.')}` : holds.length ? `${capLead(NN, `right now your anchor is ${joinRu(holds.slice(0, 3).map(nm))}.`)}` : `${capLead(NN, 'right now no step is holding at full strength, and that is an honest place to start from.')}`);\n  if (!r.top) parts.push(`It’s worth starting with the step ${nm(r.o)}: the quietest part here is ${GR_DESC[r.o][r.weak]}.`);\n  parts.push(r.c === r.o && !r.top ? `Your heart speaks from this same step.` : !r.top && r.c > r.o ? `Your heart is already looking higher, to the step ${nm(r.c)}.` : `Right now your heart speaks from the step ${nm(r.c)}.`);\n  if (A.gaps[A.G] > 10) parts.push(`What you want most is to strengthen ${nm(A.G)}.`);\n  const SP = ['You have decided to stay', 'You’re more likely staying, but sometimes you have doubts', 'You have not yet decided whether to stay', 'You are thinking of going back or moving on', 'The decision to stay doesn’t depend only on you'];\n  parts.push(`${capJoin(ctx.stay != null ? SP[ctx.stay] + ', and' : '', `right now you are closest to the state of “${STATES[A.ms][0].toLowerCase()}”.`)}`);\n  return parts.join(' ');\n}\nfunction guidePart(k){\n  const d = document.createElement('div'); d.innerHTML = GUIDE.levels[k].body;\n  const ps = [...d.children].filter(x => x.tagName === 'P');\n  const q = d.querySelector('blockquote');\n  return { voice: q ? q.innerHTML : '', rise: ps.length ? ps[ps.length - 1].innerHTML : '', gift: ps.length > 2 ? ps[ps.length - 2].innerHTML : '', ask: GUIDE.levels[k].ask };\n}\nfunction analysis(r){\n  const cur = r.pct, goal = goals.map(g => (g ?? 0) * 10);\n  const gaps = cur.map((v, k) => goal[k] - v), G = gaps.indexOf(Math.max(...gaps));\n  return { cur, goal, gaps, G, ms: moveState(r, gaps, G) };\n}\n\n/* ---------- разбор ---------- */\nfunction buildBlocks(){\n  const r = compute(); last = r;\n  const PDF = !!window.__PDF;\n  const N = esc(myName), date = new Date().toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long', year: 'numeric' });\n  const sk = r.top === 'horizon' ? 7 : r.o, L = LV[sk];\n  const country = window.__leadCountry || ((typeof loadLead === 'function' && loadLead()) || {}).country || '';\n  const guideHref = n => (typeof SITE_URL !== 'undefined' && SITE_URL ? SITE_URL.replace(/\\/?$/, '/') + 'stupeni/' : '') + '#guide-' + n;\n  const A = analysis(r); r.moveState = STATES[A.ms][0];\n  const B = []; wsReset();\n  wsSituation('Choose one specific situation from the last few weeks when you felt your quietest step creak: when you lacked energy, your people, a voice, clarity or meaning. Take the one that came to mind first.');\n  const title = r.top === 'horizon' ? 'The sky above home' : r.top === 'edge' ? `${r.o + 1} · ${LV[r.o].name}, at the edge of the sky` : lvName(r.o);\n  const tile = (lab, val, col) => `<div class=\"st-tile2\" style=\"--l:${col}\"><span>${lab}</span><b>${val}</b></div>`;\n\n  /* 1. Обложка: главное коротко */\n  B.push({ html: `<div class=\"blk st-cover\" style=\"--f:${L.fill};--l:${L.line};--s:${L.soft}\">\n      <div class=\"st-cover-top\"><div><div class=\"eyebrow\">Steps of Stability · report</div><div class=\"cover-slogan\">${TEST_META.slogan}</div>${N ? `<div class=\"names\">${N}</div>` : ''}\n        <p class=\"note\">${date} · in the country: ${YEARS[ctx.years]} · ${STAY_SHORT[ctx.stay] || ''}</p></div>\n        <div class=\"st-cover-ico\">${lvIcon(sk, 64)}</div></div>\n      <p class=\"st-now\">Your step right now</p><h1 style=\"color:${L.line}\">${title}</h1>\n      <p class=\"st-portrait\">${portrait(r, A)}</p>\n      <div class=\"st-tiles2\">\n        ${r.top ? '' : tile('Quietest facet', GR[r.weak], L.line)}\n        ${tile('Loudest in your heart', LV[r.c].name, LV[r.c].line)}\n        ${tile('What you want most', A.gaps[A.G] > 10 ? LV[A.G].name : 'not clear yet', LV[A.G].line)}\n        ${tile('State', STATES[A.ms][0], '#6E4F3C')}\n      </div></div>` });\n\n  /* 2. Лестница */\n  const yearLine = ctx.years === 0 && r.st.slice(0, 4).some(x => x === 0) ? FIRST_YEAR\n    : ctx.years === 3 && r.st[6] < 2 ? LONG_TIME : '';\n  B.push({ html: `<div class=\"blk st-ladder-blk\"><div class=\"eyebrow\">Your staircase</div>\n      <div class=\"st-two\"><div class=\"st-ladder\">${ladderSVG(r)}</div>\n      <div class=\"stack\" style=\"gap:10px\"><h2>${N ? N + ', here is' : 'Here is'} your staircase</h2>\n      <p>${ladderPattern(r)}</p>\n      <p class=\"note\"><b>Solid</b> — from 75%, <b>creaks</b> — 50–74%, <b>we start here</b> — below 50%. Your step is the lowest one that needs care: you can’t build any higher than that.</p>\n      ${yearLine ? `<p class=\"st-soft\">${yearLine}</p>` : ''}</div></div></div>` });\n\n  /* 3. Твоя ступень подробно */\n  if (r.top){\n    const txt = r.top === 'horizon'\n      ? ['All seven steps beneath you are solid — and you are looking beyond your own life. There is nothing to fix here: the house is built, and above it is the sky.',\n         'This is where those who later open doors for others come from — mentors, people who host gatherings, authors. If the thought “I want something to remain after me” resonates with you — let’s talk.']\n      : ['Your staircase is solid — all seven steps are holding. That’s a lot, and it’s your achievement.',\n         'The next question is no longer about repairs but about height: what do you want to leave behind?'];\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:${L.line};--cs:${L.soft}\">\n      <div class=\"role-head\"><div class=\"ico\">${lvIcon(sk, 26)}</div><h3>${title}</h3></div>\n      ${txt.map(p => `<p>${p}</p>`).join('')}\n      <div class=\"st-next\"><b>What’s next</b><p>There is no mini-product here — and there shouldn’t be. Next comes a conversation: “Map of a Whole Life”, the personal programme “Clear Path”, mentoring.</p></div></div>` });\n  } else {\n    const R = RES[r.o], g = guidePart(r.o);\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:${L.line};--cs:${L.soft}\">\n      <div class=\"role-head\"><div class=\"ico\">${lvIcon(r.o, 26)}</div><h3>Step ${title}</h3><span class=\"pill\" style=\"background:${L.line}\">${STATUS[r.st[r.o]]}</span><span class=\"sc\">${r.pct[r.o]}%</span></div>\n      ${R.main.map(p => `<p>${p}</p>`).join('')}\n      ${contextLines(r).map(t => `<p class=\"st-ctx\">${t}</p>`).join('')}\n      ${g.voice ? `<div class=\"st-voice\" style=\"--s:${L.soft}\"><span>Do you recognise yourself?</span>${g.voice}</div>` : ''}\n      ${r.o === 0 && ctx.how === 3 ? `<div class=\"st-soft\"><b class=\"st-h\">If you had to leave because of war or danger</b><p>${REFUGEE}</p></div>` : ''}\n      </div>` });\n    B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Four facets of the step</div><h2>Where exactly the crack is</h2>\n      <p class=\"note\">Every step has four facets: what you feel, what you do, what is around you and what you believe in. The quietest facet shows you where to start.</p>\n      ${graniHtml(r)}\n      <p>${(() => { const strong = [0,1,2,3].reduce((b, x) => r.gr[x] > r.gr[b] ? x : b, 0); return strong === r.weak || r.gr[strong] === r.gr[r.weak] ? `All four facets sound roughly the same for you: the step needs care as a whole, not in just one place.` : `On this step, your strongest is ${GR_DESC[r.o][strong]} (${GR[strong]}), and your quietest is ${GR_DESC[r.o][r.weak]} (${GR[r.weak]}). So it makes sense to lean on the first to build up the second.`; })()}</p>\n      <div class=\"callout st-co\" style=\"--c:${L.line};border-color:${L.line};background:${L.soft}\"><h3>Quietest facet: ${GR[r.weak]}</h3><p>${R.gr[r.weak]}</p></div>\n      ${r.extra >= 0 ? `<p class=\"st-soft\">There is one more step that needs care — <b style=\"color:${LV[r.extra].line}\">“${LV[r.extra].name}”</b>. We will get to it. But it is still better to start from the bottom: that way each next step stands on something solid.</p>` : ''}\n      </div>` });\n    B.push({ html: yourWords(r) });\n    B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">How to climb higher</div><h2>What helps on this step</h2>\n      <p>${g.rise}</p>${experimentHtml()}\n      <div class=\"steps\">\n      <div><span class=\"num\" style=\"background:${L.line}\">1</span><div><b>A step for this week</b><p>${R.step}</p></div></div>\n      <div><span class=\"num\" style=\"background:${L.line}\">2</span><div><b>What’s next: ${R.product}</b><p>${R.productText}</p></div></div>\n      <div><span class=\"num\" style=\"background:${L.line}\">3</span><div><b>In 4–6 weeks</b><p>Take the test again and see how your staircase has changed.</p></div></div>\n      </div></div>` });\n    wsStep(R.step); wsStep('What’s next: ' + R.product + '. ' + R.productText);\n    wsAdd('Five questions for yourself', 'Step «' + LV[r.o].name + '»', liTexts(g.ask), 6);\n    B.push({ html: `<div class=\"blk st-askblk\" style=\"--l:${L.line}\"><div class=\"eyebrow\">Pick up a pen</div><h2>Five questions for yourself</h2>\n      <p class=\"note\">Answer in writing, without rushing. There is more about the “${LV[r.o].name}” step in the guide. <button type=\"button\" class=\"linkbtn screen-only\" data-guide=\"${r.o + 1}\">Open the guide →</button><a class=\"pdf-only\" href=\"${guideHref(r.o + 1)}\">The guide on the website →</a></p>\n      <div class=\"st-ask\">${g.ask}</div></div>` });\n    B.push({ html: wsNoteHtml() });\n  }\n\n  { const sw = swissHtml(r, country); if (sw) B.push({ float: true, html: sw }); }\n\n  /* 4. Все ступени: описание каждой */\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">All seven steps</div><h2>How each step holds you</h2>\n    <div class=\"st-list\">${ITEMS.map((_, k) => `<div class=\"st-li${k === r.o && !r.top ? ' me' : ''}\" style=\"--l:${LV[k].line};--s:${LV[k].soft}\">\n      <span class=\"st-ico\">${lvIcon(k, 22)}</span><div><b>${lvName(k)} <small>· ${STATUS[r.st[k]]}</small></b><span>${STEP_LINE[k][r.st[k]]}</span></div><em>${r.pct[k]}%</em></div>`).join('')}</div></div>` });\n\n  /* 5. Сердце */\n  const C = LV[r.c], comboTxt = {\n    same: 'You think and decide from the step you are standing on — or you are already looking ahead to the next one. This is the most natural growth: your feet and your gaze move together.',\n    above: `Your heart is already up high — where “${C.name}” is. But the “${LV[Math.min(r.oLevel, 8) - 1].name}” step under your feet still needs care. This is not a contradiction but a hint: strengthen the step, and the top will truly be yours rather than something you reach by force.`,\n    below: `Your anchor is stronger than you think: the steps up to “${LV[Math.min(r.oLevel, 8) - 1].name}” are holding. But right now your heart has gone back down — to the “${C.name}” step. This happens after a hard period, an illness or great exhaustion. It is not a setback but a signal: take care of yourself.`\n  }[r.combo];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Where your heart’s music comes from</div><h2>Heart profile</h2>\n    <p>The first part showed what you are standing on. The situations show something else: which step you are thinking, deciding and dreaming from right now. It is like music: all eight notes sound, but one is louder than the rest right now.</p>\n    <div class=\"st-two st-two-heart\"><div class=\"st-heart\">${heartSVG(r)}</div>\n    <div class=\"stack\" style=\"gap:10px\"><div class=\"callout st-co\" style=\"--c:${C.line};border-color:${C.line};background:${C.soft}\"><h3>Loudest: ${C.name.toLowerCase()}${r.c2 !== null ? ` and ${LV[r.c2].name.toLowerCase()}` : ''}</h3>\n      <p>${r.c2 !== null ? `Right now “${C.name}” and “${LV[r.c2].name}” sound almost equally loud in you. It is as if you are between two notes — this happens when something is changing.` : HEART[r.c]}</p></div>\n    <p>${comboTxt}</p>${heartExample(r) ? `<p class=\"st-ctx\">${heartExample(r)}</p>` : ''}</div></div>\n    <p class=\"note\">Quietest right now is “${LV[r.quiet].name}”. This is neither bad nor good — this note is simply barely audible in your decisions for now. Sometimes it is worth asking yourself whether you miss it.</p>\n    ${r.trap ? `<div class=\"st-soft\"><b class=\"st-h\">A gentle observation</b><p>${TRAPS[r.trap]}</p></div>` : ''}</div>` });\n\n  /* 6. Цель, колёса, остаться, движение, путь вместе */\n  pathBlocks(r, A, PDF).forEach(b => B.push(b));\n\n  B.push({ html: inviteHtml({ name: myName, country: window.__leadCountry || '', interest: surveyAnswers().interest,\n                              focus: { coach: LV[sk].focus, psy: 'bring more warmth and understanding into your relationship' } }) });\n  B.push({ float: true, html: channelHtml(window.__leadCountry || country) });\n  B.push({ html: `<div class=\"blk st-final\" style=\"--s:${L.soft}\"><h2>${N ? N + ', remember' : 'Remember'} the main thing</h2>\n    <p>The staircase you see is not a verdict and not a grade. It is a snapshot of today. In a month it will be different, in a year completely different. Every step you strengthen makes everything above it stronger.</p>\n    <p>You have already come further than you think. The house is being built. And you are the one in charge of it.</p></div>` });\n  B.push({ float: true, html: `<div class=\"blk testinfo\"><div class=\"eyebrow\">About this questionnaire</div><p>${TEST_INFO.why}</p>${PDF ? '' : abHtml()}</div>` });\n  B.push({ float: true, html: moreTestsHtml(TEST_META.id) });\n  B.push({ html: authorHtml() });\n  B.push({ html: disclaimerHtml() });\n  r.title = title;\n  if (!WS.sections.length) { wsAdd('Five questions for yourself', 'Step «' + LV[sk].name + '»', liTexts(guidePart(sk).ask), 6); B.splice(Math.max(1, B.length - 3), 0, { float: true, html: wsNoteHtml() }); }\n  return B;\n}\nfunction showResult(){\n  finished = true; save(); renderResume();\n  $('report').innerHTML = buildBlocks().map(b => b.html).join('');\n  $('quiz').hidden = true; $('result').hidden = false; window.scrollTo(0, 0);\n}\n\n/* ---------- связь с общей анкетой ---------- */\nconst LEAD_HOOKS = {\n  personName: () => myName,\n  fileBase: () => 'Vosem_stupenej',\n  fileNames: () => myName ? [myName] : [],\n  payload: () => {\n    const r = last, scores = {};\n    ITEMS.forEach((_, k) => scores[`${k + 1} ${LV[k].name}, %`] = r.pct[k]);\n    if (r.skySum !== null) scores['8 Небо (бонус, из 24)'] = r.skySum;\n    LV.forEach((l, k) => scores[`Сердце: ${l.name}, %`] = r.hp[k]);\n    ITEMS.forEach((_, k) => scores[`Цель ${k + 1} ${LV[k].name} (0–10)`] = goals[k]);\n    return { result: r.title,\n      scores,\n      notes: `как приехала: ${HOW[ctx.how]}; остаться: ${STAY_SHORT[ctx.stay] || '—'}; состояние: ${last.moveState || '—'}; в стране: ${YEARS[ctx.years]}; слабая грань: ${r.top ? '—' : GR[r.weak]}; сердце: ${LV[r.c].name}${r.c2 !== null ? ' + ' + LV[r.c2].name : ''}; сочетание: ${r.combo}; ловушка: ${r.trap || 'нет'}; цели: ${goalText.map((t, k) => t && t.trim() ? LV[k].name + ' — ' + t.trim() : '').filter(Boolean).join(' | ') || '—'}` };\n  }\n};\n\n/* ---------- «продолжить с того места» ---------- */\nfunction renderResume(){\n  const box = $('stResume'); if (!box) return;\n  const v = loadSaved();\n  if (!v){ box.hidden = true; box.innerHTML = ''; return; }\n  const when = new Date(v.t).toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long' });\n  const answered = (v.ctx.how !== null) + (v.ctx.years !== null) + (v.ctx.stay != null) + v.ans.flat().filter(x => x !== null).length + v.pts.filter(p => sum(p) === 10).length;\n  box.hidden = false;\n  box.innerHTML = v.finished\n    ? `<div><b>${capLead(v.myName ? esc(v.myName) : '', `your report from ${when} has been saved`)}</b><p>You can open it again or take the test again, for example in a few weeks, to see how the staircase has changed.</p></div>\n       <div class=\"st-resume-btns\"><button type=\"button\" class=\"btn\" id=\"resOpen\">Open my report</button><button type=\"button\" class=\"btn ghost\" id=\"resNew\">Take it again</button></div>`\n    : `<div><b>${capLead(v.myName ? esc(v.myName) : '', `you already started the test on ${when}`)}</b><p>Your answers have been saved: ${answered} of ${3 + 56 + SITS.length + 7} answered. You can continue from where you stopped.</p></div>\n       <div class=\"st-resume-btns\"><button type=\"button\" class=\"btn\" id=\"resGo\">Continue</button><button type=\"button\" class=\"btn ghost\" id=\"resNew\">Start again</button></div>`;\n  const go = $('resGo'), open = $('resOpen');\n  if (go) go.addEventListener('click', () => { restore(loadSaved()); resetInvite(); $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0); });\n  if (open) open.addEventListener('click', () => { restore(loadSaved()); resetInvite(); showResult(); });\n  $('resNew').addEventListener('click', () => { forget(); renderResume(); showPart('testPrep'); $('testPrep').scrollIntoView({ behavior: 'smooth', block: 'start' }); });\n}\nrenderResume();\n\n/* полоса сверху страниц PDF — в цветах ступеней */\ndocument.documentElement.style.setProperty('--pdf-strip', 'linear-gradient(90deg,' + LV.map(l => l.fill).join(',') + ')');\n", "/* =====================================================================\n   PDF разбора и бланка, форма «Хочешь получать мои материалы?», отправка в Google Таблицу.\n   С 02.10.2026: PDF скачивается сразу, без анкеты. Результаты теста в таблицу НЕ уходят.\n   В таблицу уходят: анонимная запись при скачивании PDF (тест, дата, язык, страна, источник, мини-опрос)\n   и — только если человек сам заполнил форму — его контакты (без результатов).\n   Тест задаёт: TEST_META {id, name}, buildBlocks(), showResult(), LEAD_HOOKS.\n   Страны и PAGE_LANG — в privacy.js. Тексты на четырёх языках — здесь же (LT).\n   ===================================================================== */\nconst LT_ALL = {\n  ru: {\n    dlTitle1: 'Скачать разбор', dlText1: 'Красивый PDF с разбором без вопросов теста: картинки, описания, рекомендации, план на 4 недели и вопросы для размышления.', dlBtn1: 'Скачать разбор',\n    dlTitle: 'Скачать разбор и бланк для записей',\n    dlText: 'Красивый PDF с разбором без вопросов теста: картинки, описания, рекомендации, план на 4 недели и вопросы для размышления. Вместе с ним скачается бланк для записей со всеми вопросами из разбора, чтобы распечатать его и ответить своей рукой.',\n    dlBtn: 'Скачать разбор и бланк', again: 'Пройти заново',\n    wsTitle: 'Бланк для записей', wsText: 'Все вопросы и шаги из твоего разбора с местом для ответов. Его можно распечатать и заполнить от руки.', wsBtn: 'Скачать бланк',\n    matEyebrow: 'По желанию', matTitle: 'Хочешь получать мои материалы?',\n    matText: 'Оставь имя и e-mail, и я буду присылать полезные материалы и рассказывать о новых тестах. Твои ответы на тест остаются только у тебя: мне придут лишь данные из этой формы.',\n    name: 'Имя *', email: 'E-mail *', tg: 'Telegram', tgPh: '@username', wa: 'WhatsApp', waPh: '+41 79 …',\n    consent: link => `Я соглашаюсь, что Ирина Вознесенская получит данные из этой формы, как описано в ${link} *`, consentLink: 'Политике конфиденциальности',\n    news: 'Хочу получать письма с полезными материалами. Отписаться можно в любой момент.',\n    adult: 'Мне есть 18 лет *', send: 'Отправить',\n    errName: 'Напиши, пожалуйста, своё имя.', errEmail: 'Проверь e-mail: похоже, в нём ошибка.', errConsent: 'Чтобы отправить форму, нужно согласие.', errAdult: 'Этот тест предназначен для людей от 18 лет.',\n    sent: 'Спасибо! Данные отправлены.', sendFail: 'Не получилось отправить. Проверь интернет и попробуй ещё раз.',\n    noLib: 'Не получилось загрузить модуль PDF. Проверь интернет и обнови страницу.',\n    making: 'Готовлю PDF…', madeMain: 'Разбор сохранён. Готовлю бланк для записей…',\n    madeBoth: 'Готово! Сохранены два файла: разбор и бланк для записей. Если они не открылись, загляни в папку «Загрузки».',\n    madeOne: 'Разбор сохранён. Если он не открылся, загляни в папку «Загрузки».',\n    madeWsLater: 'Разбор сохранён. Бланк для записей можно скачать кнопкой ниже.',\n    wsMaking: 'Готовлю бланк…', wsDone: 'Бланк сохранён. Распечатай его и пиши от руки.', wsFail: 'Не получилось подготовить бланк. Попробуй ещё раз.',\n    cancel: 'Сохранение отменено.', fail: 'Не получилось подготовить PDF. Попробуй ещё раз.',\n    wsFile: 'Бланк для записей', wsFoot: ' · бланк для записей'\n  },\n  uk: {\n    dlTitle1: 'Завантажити розбір', dlText1: 'Гарний PDF із розбором без питань тесту: малюнки, описи, рекомендації, план на 4 тижні та питання для роздумів.', dlBtn1: 'Завантажити розбір',\n    dlTitle: 'Завантажити розбір і бланк для записів',\n    dlText: 'Гарний PDF із розбором без питань тесту: малюнки, описи, рекомендації, план на 4 тижні та питання для роздумів. Разом із ним завантажиться бланк для записів з усіма питаннями з розбору, щоб роздрукувати його й відповісти від руки.',\n    dlBtn: 'Завантажити розбір і бланк', again: 'Пройти знову',\n    wsTitle: 'Бланк для записів', wsText: 'Усі питання та кроки з твого розбору з місцем для відповідей. Його можна роздрукувати й заповнити від руки.', wsBtn: 'Завантажити бланк',\n    matEyebrow: 'За бажанням', matTitle: 'Хочеш отримувати мої матеріали?',\n    matText: 'Залиш ім’я та e-mail, і я надсилатиму корисні матеріали та розповідатиму про нові тести. Твої відповіді на тест залишаються тільки в тебе: мені прийдуть лише дані з цієї форми.',\n    name: 'Ім’я *', email: 'E-mail *', tg: 'Telegram', tgPh: '@username', wa: 'WhatsApp', waPh: '+380 …',\n    consent: link => `Я погоджуюся, що Ірина Вознесенська отримає дані з цієї форми, як описано в ${link} *`, consentLink: 'Політиці конфіденційності',\n    news: 'Хочу отримувати листи з корисними матеріалами. Відписатися можна будь-коли.',\n    adult: 'Мені є 18 років *', send: 'Надіслати',\n    errName: 'Напиши, будь ласка, своє ім’я.', errEmail: 'Перевір e-mail: схоже, у ньому помилка.', errConsent: 'Щоб надіслати форму, потрібна згода.', errAdult: 'Цей тест призначений для людей від 18 років.',\n    sent: 'Дякую! Дані надіслано.', sendFail: 'Не вдалося надіслати. Перевір інтернет і спробуй ще раз.',\n    noLib: 'Не вдалося завантажити модуль PDF. Перевір інтернет і онови сторінку.',\n    making: 'Готую PDF…', madeMain: 'Розбір збережено. Готую бланк для записів…',\n    madeBoth: 'Готово! Збережено два файли: розбір і бланк для записів. Якщо вони не відкрилися, зазирни в папку «Завантаження».',\n    madeOne: 'Розбір збережено. Якщо він не відкрився, зазирни в папку «Завантаження».',\n    madeWsLater: 'Розбір збережено. Бланк для записів можна завантажити кнопкою нижче.',\n    wsMaking: 'Готую бланк…', wsDone: 'Бланк збережено. Роздрукуй його й пиши від руки.', wsFail: 'Не вдалося підготувати бланк. Спробуй ще раз.',\n    cancel: 'Збереження скасовано.', fail: 'Не вдалося підготувати PDF. Спробуй ще раз.',\n    wsFile: 'Бланк для записів', wsFoot: ' · бланк для записів'\n  },\n  de: {\n    dlTitle1: 'Auswertung herunterladen', dlText1: 'Ein schönes PDF mit deiner Auswertung, ohne die Testfragen: Bilder, Beschreibungen, Empfehlungen, ein Plan für 4 Wochen und Fragen zum Nachdenken.', dlBtn1: 'Auswertung herunterladen',\n    dlTitle: 'Auswertung und Notizblatt herunterladen',\n    dlText: 'Ein schönes PDF mit deiner Auswertung, ohne die Testfragen: Bilder, Beschreibungen, Empfehlungen, ein Plan für 4 Wochen und Fragen zum Nachdenken. Dazu wird ein Notizblatt mit allen Fragen aus der Auswertung heruntergeladen, zum Ausdrucken und Ausfüllen von Hand.',\n    dlBtn: 'Auswertung und Notizblatt herunterladen', again: 'Noch einmal machen',\n    wsTitle: 'Notizblatt', wsText: 'Alle Fragen und Schritte aus deiner Auswertung mit Platz für deine Antworten. Zum Ausdrucken und Ausfüllen von Hand.', wsBtn: 'Notizblatt herunterladen',\n    matEyebrow: 'Freiwillig', matTitle: 'Möchtest du meine Materialien erhalten?',\n    matText: 'Hinterlasse deinen Namen und deine E-Mail, dann schicke ich dir hilfreiche Materialien und erzähle dir von neuen Tests. Deine Antworten im Test bleiben nur bei dir: Ich erhalte nur die Angaben aus diesem Formular.',\n    name: 'Name *', email: 'E-Mail *', tg: 'Telegram', tgPh: '@username', wa: 'WhatsApp', waPh: '+41 79 …',\n    consent: link => `Ich bin einverstanden, dass Iryna Voznesenskaya die Angaben aus diesem Formular erhält, wie in der ${link} beschrieben *`, consentLink: 'Datenschutzerklärung',\n    news: 'Ich möchte E-Mails mit hilfreichen Materialien erhalten. Abmelden ist jederzeit möglich.',\n    adult: 'Ich bin mindestens 18 Jahre alt *', send: 'Senden',\n    errName: 'Bitte gib deinen Namen ein.', errEmail: 'Bitte prüfe deine E-Mail-Adresse.', errConsent: 'Zum Senden brauche ich dein Einverständnis.', errAdult: 'Dieser Test ist für Personen ab 18 Jahren.',\n    sent: 'Danke! Deine Angaben wurden gesendet.', sendFail: 'Das Senden hat nicht geklappt. Prüfe deine Internetverbindung und versuche es noch einmal.',\n    noLib: 'Das PDF-Modul konnte nicht geladen werden. Prüfe deine Internetverbindung und lade die Seite neu.',\n    making: 'PDF wird erstellt…', madeMain: 'Auswertung gespeichert. Das Notizblatt wird erstellt…',\n    madeBoth: 'Fertig! Zwei Dateien wurden gespeichert: die Auswertung und das Notizblatt. Falls sie sich nicht geöffnet haben, schau im Ordner «Downloads» nach.',\n    madeOne: 'Auswertung gespeichert. Falls sie sich nicht geöffnet hat, schau im Ordner «Downloads» nach.',\n    madeWsLater: 'Auswertung gespeichert. Das Notizblatt kannst du unten herunterladen.',\n    wsMaking: 'Notizblatt wird erstellt…', wsDone: 'Notizblatt gespeichert. Druck es aus und schreib von Hand.', wsFail: 'Das Notizblatt konnte nicht erstellt werden. Versuche es noch einmal.',\n    cancel: 'Speichern abgebrochen.', fail: 'Das PDF konnte nicht erstellt werden. Versuche es noch einmal.',\n    wsFile: 'Notizblatt', wsFoot: ' · Notizblatt'\n  },\n  en: {\n    dlTitle1: 'Download your results', dlText1: 'A beautiful PDF with your results, without the test questions: pictures, descriptions, recommendations, a 4-week plan and questions to reflect on.', dlBtn1: 'Download results',\n    dlTitle: 'Download your results and notes sheet',\n    dlText: 'A beautiful PDF with your results, without the test questions: pictures, descriptions, recommendations, a 4-week plan and questions to reflect on. A notes sheet with all the questions from your results is downloaded with it, to print out and answer by hand.',\n    dlBtn: 'Download results and notes sheet', again: 'Take it again',\n    wsTitle: 'Notes sheet', wsText: 'All the questions and steps from your results with space for your answers. Print it out and fill it in by hand.', wsBtn: 'Download notes sheet',\n    matEyebrow: 'Optional', matTitle: 'Would you like to receive my materials?',\n    matText: 'Leave your name and e-mail, and I will send you useful materials and tell you about new tests. Your test answers stay with you only: I only receive the details from this form.',\n    name: 'Name *', email: 'E-mail *', tg: 'Telegram', tgPh: '@username', wa: 'WhatsApp', waPh: '+41 79 …',\n    consent: link => `I agree that Iryna Voznesenskaya receives the details from this form, as described in the ${link} *`, consentLink: 'Privacy policy',\n    news: 'I would like to receive e-mails with useful materials. I can unsubscribe at any time.',\n    adult: 'I am 18 or older *', send: 'Send',\n    errName: 'Please enter your name.', errEmail: 'Please check your e-mail address.', errConsent: 'Your consent is needed to send the form.', errAdult: 'This test is for people aged 18 and over.',\n    sent: 'Thank you! Your details have been sent.', sendFail: 'Sending failed. Check your internet connection and try again.',\n    noLib: 'The PDF module could not be loaded. Check your internet connection and reload the page.',\n    making: 'Preparing the PDF…', madeMain: 'Results saved. Preparing the notes sheet…',\n    madeBoth: 'Done! Two files have been saved: your results and the notes sheet. If they did not open, look in your Downloads folder.',\n    madeOne: 'Results saved. If the file did not open, look in your Downloads folder.',\n    madeWsLater: 'Results saved. You can download the notes sheet with the button below.',\n    wsMaking: 'Preparing the notes sheet…', wsDone: 'Notes sheet saved. Print it out and write by hand.', wsFail: 'The notes sheet could not be prepared. Please try again.',\n    cancel: 'Saving cancelled.', fail: 'The PDF could not be prepared. Please try again.',\n    wsFile: 'Notes sheet', wsFoot: ' · notes sheet'\n  }\n};\nconst L = LT_ALL[PAGE_LANG] || LT_ALL.ru;\nconst HAS_WS = typeof worksheetBlocks === 'function';\nconst ASK_ADULT = (typeof BRAND !== 'undefined' && BRAND === 'psy');   // тесты о паре — только для взрослых\n\nfunction leadFormHtml(){\n  return `<div class=\"blk actions dl-box\" style=\"margin-top:18px\">\n    <h3>${HAS_WS ? L.dlTitle : L.dlTitle1}</h3>\n    <p>${HAS_WS ? L.dlText : L.dlText1}</p>\n    <p class=\"err\" id=\"formErr\" hidden></p>\n    <div class=\"row\">\n      <button class=\"btn\" type=\"button\" id=\"pdfBtn\">${HAS_WS ? L.dlBtn : L.dlBtn1}</button>\n      <button class=\"btn ghost\" type=\"button\" id=\"again\">${L.again}</button>\n    </div>\n    ${HAS_WS ? `<div class=\"ws-offer\" id=\"wsOffer\" hidden><b>${L.wsTitle}</b><span>${L.wsText}</span><button class=\"btn\" type=\"button\" id=\"wsBtn\">${L.wsBtn}</button></div>` : ''}\n    <span class=\"status\" id=\"status\" hidden></span>\n    <p class=\"note keep\" id=\"keepLine\"></p>\n    ${deleteAnswersHtml()}\n  </div>\n  <div class=\"blk mat-box\">\n    <div class=\"eyebrow\">${L.matEyebrow}</div><h3>${L.matTitle}</h3>\n    <p>${L.matText}</p>\n    <form id=\"lead\" class=\"stack\" style=\"gap:12px\" novalidate>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fName\">${L.name}</label><input id=\"fName\" maxlength=\"40\" autocomplete=\"given-name\"></div>\n        <div class=\"field\"><label for=\"fEmail\">${L.email}</label><input id=\"fEmail\" type=\"email\" maxlength=\"80\" autocomplete=\"email\"></div>\n      </div>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fTg\">${L.tg}</label><input id=\"fTg\" maxlength=\"40\" placeholder=\"${L.tgPh}\" autocomplete=\"off\"></div>\n        <div class=\"field\"><label for=\"fWa\">${L.wa}</label><input id=\"fWa\" type=\"tel\" maxlength=\"25\" placeholder=\"${L.waPh}\" autocomplete=\"tel\"></div>\n      </div>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fConsent\"> <span>${L.consent(`<a href=\"${legalUrl('privacy')}\" target=\"_blank\" rel=\"noopener\">${L.consentLink}</a>`)}</span></label>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fNews\"> <span>${L.news}</span></label>\n      ${ASK_ADULT ? `<label class=\"check\"><input type=\"checkbox\" id=\"fAdult\"> <span>${L.adult}</span></label>` : ''}\n      <p class=\"err\" id=\"matErr\" hidden></p>\n      <div class=\"row\"><button class=\"btn\" type=\"submit\" id=\"matBtn\">${L.send}</button></div>\n      <p class=\"note\" id=\"matOk\" hidden></p>\n    </form>\n  </div>`;\n}\ndocument.querySelectorAll('[data-lead]').forEach(el => el.innerHTML = leadFormHtml());\n\nconst el = id => document.getElementById(id);\nfunction setStatus(t){ el('status').textContent = t; el('status').hidden = !t; }\nfunction setErr(t){ el('formErr').textContent = t; el('formErr').hidden = !t; }\nel('again').addEventListener('click', () => { el('result').hidden = true; el('intro').hidden = false; window.scrollTo(0,0); });\n\n/* прежняя анкета хранила контакты; теперь браузер помнит только страну (в мини-опросе) */\nfunction loadLead(){ return { country: surveyCountry(), name: (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '' }; }\n\nconst _showResult = showResult;\nshowResult = function(){\n  _showResult();\n  setErr(''); setStatus('');\n  if (el('wsOffer')) el('wsOffer').hidden = true;\n  el('keepLine').textContent = retentionLine();\n  if (!el('fName').value) el('fName').value = (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '';\n};\n\n// Чёткость PDF: 3 = около 290 точек на дюйм (хорошо для печати). На слабых телефонах — 2.5.\nconst PDF_SCALE = (/iPhone|iPad|Android/i.test(navigator.userAgent) && (navigator.deviceMemory || 4) < 4) ? 2.5 : 3;\nasync function buildPdf(getBlocks = buildBlocks, foot = null){\n  const stage = el('stage'); stage.innerHTML = '';\n  window.__PDF = true; let blocks; try { blocks = getBlocks(); } finally { window.__PDF = false; }\n  const footText = foot || footerLine();\n  const pages = [];\n  const newPage = () => {\n    const p = document.createElement('div'); p.className = 'pdf-page';\n    p.innerHTML = `<div class=\"strip\"></div><div class=\"pbody\"></div><div class=\"pfoot\"><span>${footText}</span><span class=\"pn\"></span></div>`;\n    stage.appendChild(p); pages.push(p); return p.querySelector('.pbody');\n  };\n  let body = newPage();\n  const mk = b => { const h = document.createElement('div'); h.innerHTML = b.html; return h.firstElementChild; };\n  const over = () => body.scrollHeight > body.clientHeight + 1;\n  const used = new Set();\n  for (let i = 0; i < blocks.length; i++){\n    const b = blocks[i];\n    if (!b.html || used.has(i)) continue;\n    if (b.newPage && body.children.length) body = newPage();\n    const node = mk(b);\n    body.appendChild(node);\n    if (over() && body.children.length > 1){\n      node.remove();\n      // свободное место внизу страницы заполняем небольшими «плавающими» блоками, которые идут дальше (float: true)\n      for (let j = i + 1; j < blocks.length; j++){\n        if (!blocks[j].float || used.has(j) || !blocks[j].html) continue;\n        const f = mk(blocks[j]); body.appendChild(f);\n        if (over()) f.remove(); else used.add(j);\n      }\n      body = newPage(); body.appendChild(node);\n    }\n    if (body.scrollHeight > body.clientHeight + 1 && body.children.length === 1){   // один блок выше страницы — уменьшаем, чтобы ничего не обрезалось\n      const k = body.clientHeight / node.scrollHeight;\n      node.style.transformOrigin = 'top left'; node.style.transform = `scale(${k})`; node.style.width = (100 / k) + '%';\n    }\n  }\n  pages.forEach((p, i) => p.querySelector('.pn').textContent = `${i+1} / ${pages.length}`);\n  if (document.fonts && document.fonts.ready) await document.fonts.ready;\n  const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({ unit:'pt', format:'a4', compress:true });\n  for (let i = 0; i < pages.length; i++){\n    const canvas = await html2canvas(pages[i], { scale:PDF_SCALE, backgroundColor:'#FFFFFF', useCORS:true, logging:false });\n    (function(cv, t){ const c = cv.getContext('2d'), w = cv.width, h = cv.height, fs = Math.round(Math.max(w, h) * 0.032); c.save(); c.font = '700 ' + fs + 'px Manrope, sans-serif'; c.fillStyle = 'rgba(110,79,60,0.075)'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.translate(w / 2, h / 2); c.rotate(-Math.PI / 7); const sx = fs * 9, sy = fs * 5, R = Math.hypot(w, h) / 2 + sx; for (let y = -R, r = 0; y <= R; y += sy, r++) for (let x = -R + (r % 2) * sx / 2; x <= R; x += sx) c.fillText(t, x, y); c.restore(); })(canvas, 'voznesenskaya.ch');\n    if (i) pdf.addPage();\n    pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, 595.28, 841.89, undefined, 'FAST');\n    const pr = pages[i].getBoundingClientRect(), k = 595.28 / pr.width;\n    pages[i].querySelectorAll('a[href]').forEach(a => {\n      if (!/^https?:/.test(a.href)) return;\n      const r = a.getBoundingClientRect();\n      pdf.link((r.left - pr.left) * k, (r.top - pr.top) * k, r.width * k, r.height * k, { url: a.href });\n    });\n  }\n  stage.innerHTML = '';\n  return pdf.output('blob');\n}\n\nlet downloadsCap = null;\n(async () => { try { if (window.claude && window.claude.use) downloadsCap = await window.claude.use('downloads'); } catch(e){ downloadsCap = null; } })();\nasync function saveBlob(blob, filename){\n  if (downloadsCap){ await downloadsCap.save({ filename, data: blob }); return; }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = filename; a.rel = 'noopener'; document.body.appendChild(a); a.click(); setTimeout(() => a.remove(), 1000);\n  setTimeout(() => URL.revokeObjectURL(url), 60000);\n}\nconst cleanName = s => s.replace(/[\\\\/:*?\"<>|]+/g, ' ').replace(/\\s+/g, ' ').trim();\n\n/* ---------- отправка в таблицу: без результатов теста ---------- */\nfunction basePayload(){\n  const src = new URLSearchParams(location.search);\n  const sv = (typeof surveyAnswers === 'function') ? surveyAnswers() : { heard: [], interest: [] };\n  return {\n    testId: TEST_META.id, testName: TEST_META.name, lang: PAGE_LANG, country: surveyCountry(),\n    heard: sv.heard.join(', '), interest: sv.interest.join(', '),\n    source: src.get('utm_source') || src.get('src') || document.referrer || 'прямой заход'\n  };\n}\nasync function post(payload){\n  if (!ENDPOINT) return;\n  await fetch(ENDPOINT, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body: JSON.stringify(payload) });\n}\nlet statSent = false;\nasync function sendStat(){       // анонимно: без имени, e-mail и результатов; один раз за открытие разбора\n  if (statSent) return; statSent = true;\n  try { await post({ kind: 'stat', ...basePayload() }); } catch(e){}\n}\n\n/* ---------- скачать разбор и бланк ---------- */\nel('pdfBtn').addEventListener('click', async () => {\n  setErr('');\n  if (!window.jspdf || !window.html2canvas) return setErr(L.noLib);\n  const btn = el('pdfBtn'); btn.disabled = true; setStatus(L.making);\n  try {\n    sendStat();\n    const blob = await buildPdf();\n    const fname = cleanName([TEST_META.name, ...LEAD_HOOKS.fileNames(), new Date().toLocaleDateString(DATE_LOCALE)].filter(Boolean).join(' — '));\n    await saveBlob(blob, fname + '.pdf');\n    if (!HAS_WS){ setStatus(L.madeOne); return; }\n    el('wsOffer').hidden = false;\n    setStatus(L.madeMain);\n    try { await downloadWorksheet(); setStatus(L.madeBoth); }\n    catch(e2){ setStatus(L.madeWsLater); }\n  } catch(e){\n    setStatus('');\n    setErr(e && e.code === 'declined' ? L.cancel : L.fail);\n  } finally { btn.disabled = false; }\n});\nasync function downloadWorksheet(){\n  const nm = (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '';\n  const pair = (typeof WS_PAIR !== 'undefined') ? WS_PAIR : TEST_META.id === 'roza-lyubvi';\n  const blob = await buildPdf(() => { buildBlocks(); return worksheetBlocks({ name: nm, pair }); }, footerLine() + L.wsFoot);\n  const fname = cleanName([L.wsFile, TEST_META.name, nm, new Date().toLocaleDateString(DATE_LOCALE)].filter(Boolean).join(' — '));\n  await saveBlob(blob, fname + '.pdf');\n}\nif (el('wsBtn')) el('wsBtn').addEventListener('click', async () => {\n  const b = el('wsBtn'); b.disabled = true; setErr(''); setStatus(L.wsMaking);\n  try { await downloadWorksheet(); setStatus(L.wsDone); }\n  catch(e){ setStatus(''); setErr(e && e.code === 'declined' ? L.cancel : L.wsFail); }\n  finally { b.disabled = false; }\n});\n\n/* ---------- форма «Хочешь получать мои материалы?» (по желанию) ---------- */\nel('lead').addEventListener('submit', async (ev) => {\n  ev.preventDefault();\n  const err = t => { el('matErr').textContent = t; el('matErr').hidden = !t; };\n  err(''); el('matOk').hidden = true;\n  const lead = { name: el('fName').value.trim(), email: el('fEmail').value.trim(), telegram: el('fTg').value.trim(), whatsapp: el('fWa').value.trim(),\n                 marketing: el('fNews').checked, consent: el('fConsent').checked, adult: ASK_ADULT ? el('fAdult').checked : null };\n  if (!lead.name) return err(L.errName);\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(lead.email)) return err(L.errEmail);\n  if (!lead.consent) return err(L.errConsent);\n  if (ASK_ADULT && !lead.adult) return err(L.errAdult);\n  const b = el('matBtn'); b.disabled = true;\n  try {\n    await post({ kind: 'lead', ...basePayload(), ...lead });\n    el('matOk').textContent = L.sent; el('matOk').hidden = false;\n    el('lead').querySelectorAll('input').forEach(i => { if (i.type === 'checkbox') i.checked = false; else if (i.id !== 'fName') i.value = ''; });\n  } catch(e){ err(L.sendFail); }\n  finally { b.disabled = false; }\n});\nwindow.__buildPdf = buildPdf;\n"]};
